SELECT 'moj-all-verified-judgments-review-002-chunk-074' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"58ccffea-0008-58ff-a948-47aecf281352","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج حشيش -حيازة حشيش -حيازة حبوب محظورة- حيازة هيروين مخدر -تعاطي الهيروين واحلشيش -احلبوب احملظورة -اشتراك يف حيازة لغرض الترويج -تستر -إقرار حتقيق ا- تعزير بالسجن واجللد والغرامة -تعزير باملنع من السفر -تعزير باملصادرة -إلغاء شريحة جوال -إقامة حد املسكر على متعاطي","document_number":"34197957","case_number":"34171886","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/24","year":"1434","subject":"مخدرات -ترويج حشيش -حيازة حشيش -حيازة حبوب محظورة- حيازة هيروين مخدر -تعاطي الهيروين واحلشيش -احلبوب احملظورة -اشتراك يف حيازة لغرض الترويج -تستر -إقرار حتقيق ا- تعزير بالسجن واجللد والغرامة -تعزير باملنع من السفر -تعزير باملصادرة -إلغاء شريحة جوال -إقامة حد املسكر على متعاطي","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34197957:‬تاريخه‪1434/04/24:‬هـ‬\n                    ‫رقم الدعوى‪34171886:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n    ‫‪/34227641‬ج‪/2‬ب تاريخه‪1434/05/29:‬هـ‬\n\n\n‫مخــدرات‪ -‬ترويــج حشــيش‪ -‬حيــازة حشــيش ‪ -‬حيــازة حبــوب محظــورة‪-‬‬\n‫حيــازة هيرويــن مخــدر‪ -‬تعاطــي الهيرويــن واحلشــيش‪ -‬احلبــوب‬\n‫احملظــورة ‪ -‬اشــتراك يف حيــازة لغــرض الترويــج‪ -‬تســتر‪ -‬إقــرار حتقيق ًا‪-‬‬\n‫تعزيــر بالســجن واجللــد والغرامــة‪ -‬تعزيــر باملنــع مــن الســفر‪ -‬تعزيــر‬\n‫باملصــادرة‪ -‬إلغــاء شــريحة جــوال‪ -‬إقامــة حــد املســكر علــى متعاطــي‬\n                                                                ‫احلشــيش ‪.‬‬\n\n\n\n      ‫‪ -1‬نهي النبي ‪ -‬صلى اهلل عليه وسلم ‪ -‬عن كل مسكر ومفتر ‪.‬‬\n                          ‫‪ -2‬القاعدة الفقهية ‪ :‬املرء مؤاخذ بإقراره ‪.‬‬\n‫‪ -3‬املــواد ‪ -56 -38‬الفقــرة األولــى مــن املــادة ‪ 53‬مــن نظــام مكافحــة‬\n                                         ‫املخــدرات واملؤثــرات العقليــة ‪.‬‬\n             ‫‪ -4‬تعميم سمو وزير الداخلية رقم ‪ 47‬يف ‪1421/3/18‬هـ ‪.‬‬\n          ‫‪ -5‬تعميم سمو وزير الداخلية رقم ‪ 9798‬يف ‪1428/2/10‬هـ ‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا بترويــج األول للحشــيش‬\n‫املخــدر بقصــد االجتــار وحيــازة احلشــيش بقصــد الترويــج وحيــازة‬\n‫احلبــوب احملظــورة والهيرويــن بقصــد التعاطــي وتعاطيــه ســابقا لهــا‬\n‫واتهــام الثانــي بنقــل احلشــيش املخــدر وإحــرازه بقصــد الترويــج وحيــازة‬\n                                                                                 ‫‪344‬‬\n\f      ‫احلبــوب احملظــورة والهيرويــن بقصــد التعاطــي وتعاطيــه الســابق لهــا‪،‬‬\n      ‫وطلــب املدعــي العــام إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بالعقوبــة‬\n      ‫الــواردة يف الفقــرة األولــى مــن املــادة (‪ )38‬مــن نظــام مكافحة املخدرات‬\n      ‫واملؤثــرات العقليــة وتشــديد العقوبــة لقــاء ســوابقهما ومصــادرة اجلوالــن‬\n      ‫املضبوطــن يف اجلرميــة وتعزيرهمــا لتســترهما‪ ،‬حيــث إنــه مت القبــض‬\n      ‫علــى املدعــى عليهمــا بعــد ورود بــاغ مفــاده أن املدعــى عليــه األول لديــه‬\n      ‫كميــة مــن احلشــيش املخــدر ويريــد بيعــه ومت التنســيق معــه علــى شــراء‬\n      ‫الكميــة ومت ذلــك وتبــن أن املدعــى عليــه الثانــي هــو الــذي ســلم املدعــى‬\n      ‫عليه األول الكمية التي مت بيعها وقام بنقلها ‪ ،‬أقر املدعى عليهما مبا‬\n      ‫أســند إليهمــا ‪ ،‬بنــاء علــى مــا ســبق حكمــت احملكمــة بتعزيــر املدعــى‬\n      ‫عليهمــا بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة اجلوالــن‬\n      ‫وإلغــاء الشــريحتني املســتخدمتني يف اجلرميــة ‪ ،‬إقامــة حــد املســكر علــى‬\n                     ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬      ‫املدعــى عليهمــا ُ‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..............‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n                                                                                 ‫ّ‬\n      ‫احملكمــة اجلزائيــة يف محافظــة االحســاء املكلــف برقــم ‪34171886‬‬\n      ‫وتاريــخ ‪ 1434/04/15‬ه ـ املقيــدة باحملكمــة برقــم ‪34917252‬‬\n      ‫وتاريــخ ‪ 1434/04/15‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1434/04/24‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 10 : 30‬وفيهــا حضــر املدعــي العــام ‪..............‬‬\n      ‫املعمــد بالترافــع أمــام هــذه احملكمــة مبوجــب خطــاب ســعادة رئيــس‬\n      ‫دائــرة التحقيــق واالدعــاء العــام مبحافظــة االحســاء ذي الرقــم ‪..............‬‬\n\n‫‪345‬‬\n\f‫والتاريــخ ‪ 1433/12/01‬ه ـ وادعــى ضــد احلاضريــن معــه ‪..............‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..............‬و‪..............‬‬\n‫ال يف دعواه‬    ‫ســعودي اجلنســية مبوجب الســجل املدني رقم (‪ )..............‬قائ ً‬\n‫فباالطــاع علــى محضــر القبــض املعــد مــن قبــل مكافحــة املخــدرات‬\n‫مبحافظــة األحســاء تبــن أنــه بتاريــخ ‪1434/1/7‬ه ـ توفــرت معلومــات‬\n‫لــدى ادارة مكافحــة املخــدرات مبحافظــة األحســاء مــن أحــد املصــادر‬\n‫الســرية لــدى مكافحــة املخــدرات مبنطقــة مكــة املكرمــة تفيــد بــأن‬\n‫املتهــم األول لديــه كميــة كبيــرة مــن احلشــيش املخــدر ويبحــث عــن‬\n‫مشــتري لتلــك الكميــة فتــم إعــداد اخلطــة الالزمــة لإلطاحــة باملتهــم‬\n‫ومت التنســيق مــع املتهــم األول مــن قبــل مكافحــة املخــدرات مبنطقــة‬\n‫مكــة املكرمــة بــأن هنالــك مشــتري مبحافظــة األحســاء يرغــب بشــراء‬\n‫تلــك الكميــة فوافــق املتهــم األول علــى ذلــك ومت تكليــف أحــد أفــراد‬\n‫فرقــة مكافحــة املخــدرات مبحافظــة األحســاء للقيــام بــدور املشــتري‬\n‫ويف يــوم األربعــاء ‪1434/1/7‬ه ـ مت االتصــال علــى املتهــم األول علــى‬\n‫جوالــه رقــم(‪ )..............‬علــى مســمع مــن الفرقــة القابضــة وطلــب منــه‬\n‫بيعــه (‪ )35‬كيلــو مــن احلشــيش املخــدر فوافــق املتهــم األول علــى ذلــك‬\n‫ومت ترقيــم مبلــغ حكومــي وقــدره (‪ )18000‬ثمانيــة عشــر ألــف ريــال‬\n‫ويف يــوم اخلميــس اتصــل املشــتري رجــل األمــن باملتهــم األول وطلــب منــه‬\n‫الكميــة املطلوبــة وأفــاد بــأن الكميــة يف محافظــة رأس تنــورة وأن‬\n‫هنالــك شــخص آخــر ســوف يقــوم بإحضارهــا ويف يــوم اخلميــس تقابــل‬\n‫املشــتري رجــل األمــن باملتهــم األول وســلمه قطعتــن مــن احلشــيش املخــدر‬\n‫بلــغ وزنهمــا (‪ )9‬تســعة جــرام كعينــة للكميــة أحيلت عينــه منها للتحليل‬\n‫برقــم (‪ )..............‬املتفــق عليــه ويف يــوم الثالثــاء اتصــل املشــتري رجــل‬\n\n\n                                                                                      ‫‪346‬‬\n\f      ‫األمــن علــى املتهــم األول وأخبــره بــأن العينــة مناســبة وطلــب إحضــار(‪)35‬‬\n      ‫كيلــو مــن احلشــيش واتفــق علــى مــكان وموعــد اســتالم الكميــة‬\n      ‫وقــد ورد للعمليــات أن املتهــم األول اســتلم الكميــة مــن املتهــم الثانــي‬\n      ‫الــذي نقــل الكميــة مــن محافظــة رأس تنــورة إلــى األحســاء بســيارة‬\n      ‫مــن نــوع ‪ ....‬موديــل ‪2009‬م حتمــل اللوحــة رقــم (‪ )..............‬ويف يــوم‬\n      ‫األربعاء‪1434/1/14‬ه ـ ويف املــكان املتفــق عليــه حضــر املتهــم األول‬\n      ‫علــى ســيارة مــن نــوع ‪ .......‬موديــل (‪ )2004‬حتمــل اللوحــة دبــي رقمهــا‬\n      ‫(‪ )..............‬وقابــل املشــتري رجــل األمــن وســلمه حقيبــة بهــا خمســة عشــر‬\n      ‫كيلــو مــن احلشــيش املخــدر وأحيلــت للتحليــل برقــم (‪ )..............‬وأثنــاء‬\n      ‫شــروع املتهــم يف اســتالم املبلــغ شــك يف األمــر وحــاول الفــرار فتــم القبض‬\n      ‫عليــه وأفــاد بأنــه يوجــد كميــة مــن املخــدرات يف منــزل املتهــم الثانــي‬\n      ‫وبتفتيشــه عثــر بحوزتــه علــى قطعتــن ســوداء يشــتبه أن تكــون مــن‬\n      ‫احلشــيش املخــدر تــزن (‪)95‬خمســة وتســعون جرام ـ ًا أحيلــت عينــه منهــا‬\n      ‫برقــم (‪)..............‬وعدد(‪)5‬خمســة حبــات يشــتبه أن تكــون مــن حبــوب‬\n      ‫األمفيتامــن أحيلــت برقــم (‪)..............‬وعــدد(‪ )7‬حبــات يشــتبه أن تكون‬\n      ‫محظــورة أحيلــت برقــم (‪)..............‬وكيســن نايلــون بهــا آثــار الهرويــن‬\n      ‫بلــغ وزنهــا (‪)3،2‬ثالثــة جــرام واثنــن مــن العشــرة مــن اجلــرام أحيلــت‬\n      ‫كاملــة للتحليــل برقــم (‪ )..............‬كمــا ضبــط بحوزتــه جهــاز جــوال‬\n      ‫يحمــل الرقــم التسلســلي (‪ )..............‬وشــريحة اتصــال رقــم(‪)..............‬‬\n      ‫املســتخدم يف عمليــة الترويــج وباالنتقــال إلــى شــقة املتهــم الثانــي الواقعــة‬\n      ‫يف محافظــة رأس تنــورة مت القبــص علــى املتهــم ‪( ..............‬فــرزت لــه‬\n      ‫أوراق) بداخــل الشــقة وبتفتيــش الشــقه عثــر علــى (‪ )9‬تســعة كيلــو مــن‬\n      ‫احلشــيش املخــدر أحيلــت للتحليــل برقــم (‪ )..............‬ومجموعــة مــن قطــع‬\n\n\n‫‪347‬‬\n\f‫احلشــيش املخــدر تزن(‪)180‬جــرام معــدة للترويــج أحيلــت عينــه منهــا‬\n‫للتحليــل برقــم (‪ )..............‬وعــدد(‪ )72‬اثنــان وســبعون حبــة مــن احلبــوب‬\n‫احملظــورة أحيلــت عينــه منهــا للتحليــل برقــم (‪ )..............‬وعــدد(‪ )3‬حبات‬\n‫مــن حبــوب الكبتاجــون أرســلت كاملــة للتحليــل برقــم (‪)..............‬‬\n‫وعــدد (‪ )20‬حبــة زهريــة اللــون مــن احلبــوب احملظــورة أرســلت عينــه‬\n‫منهــا للتحليــل برقــم (‪ )..............‬وعــدد (‪ )8‬ثمانيــة أكيــاس نايلــون بهــا‬\n‫آثــار الهرويــن املخــدر تــزن مبجموعهــا (‪ )3،6‬ثالثــة جــرام وســتة مــن‬\n‫العشــرة مــن اجلــرام أحيلــت كاملــة للتحليــل برقــم (‪ )..............‬وســاح‬\n‫مــن نــوع مســدس (مت فــرز أوراق مســتقلة للســاح)‪ .‬وقــد أثبــت التقريــر‬\n‫الكيمــاوي الشــرعي رقــم (‪ )..............‬لعــام ‪1434‬ه ـ إيجابيــة عينــات‬\n‫رقم(‪..............‬ورقــم (‪ )..............‬ورقــم (‪ )..............‬ورقــم (‪)..............‬‬\n‫ورقــم (‪ )..............‬للحشــيش املخــدر املــدرج علــى اجلــدول رقــم (‪ )1‬فئة (أ)‬\n‫كمــا أثبــت التقريــر ايجابيــة العينتــن رقــم (‪ )..............‬ورقــم (‪)..............‬‬\n‫ملــادة األمفيتامــن املــدرج باجلــدول رقــم (‪ )2‬فئــة (ب) امللحــق بنظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة كمــا أثبــت التقريــر إيجابيــة‬\n‫العينتــن رقــم (‪ )..............‬ورقــم (‪ )..............‬لعقــار البــرازوالم املــدرج‬\n‫باجلــدول رقــم (‪ )2‬فئــة (د) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة وباســتجواب األول ‪ :‬اقــر بواقعــة القبــض والضبــط وأفــاد بأنــه‬\n‫ورد إليــه اتصــال مــن املكلــف بالشــراء علــى جوالــه املذكــور أعــاه‬\n‫وطلــب منــه شــراء خمســة عشــر كيلــو مــن احلشــيش املخــدر فوافــق‬\n‫علــى ذلــك وقابلــه يف يــوم األثنــن ‪1434/1/12‬ه ـ وســلمه (‪ )9‬تســعة‬\n‫جــرام مــن احلشــيش املخــدر كعينــة لباقــي الكميــة ويف يــوم اخلميــس‬\n‫‪1434/1/14‬ه ـ قابــل املكلــف وســلمه حقيبــة بهــا (‪ )15‬خمســة عشــر‬\n\n\n                                                                                            ‫‪348‬‬\n\f      ‫كيلــو مــن احلشــيش املخــدر كمــا أقــر بحيــازة قطعتــن مــن احلشــيش‬\n      ‫املخــدر تــزن مبجموعهمــا(‪ )95‬خمســة وتســعون جرام ـ ًا وعــدد(‪)5‬‬\n      ‫خمــس حبــات مــن حبــوب األمفيتامــن وعــدد (‪ )7‬ســبع حبــات مــن‬\n      ‫حبــوب البــرازوالم وكيســن بهــا آثــار الهرويــن املخــدر بقصــد التعاطــي‬\n      ‫والترويــج كمــا أقــر بإيداعــه احلشــيش املخــدر املضبــوط لــدى املتهــم‬\n      ‫الثانــي بقصــد الترويــج كمــا أقــر بتعاطيــه للحشــيش املخــدر والهرويــن‬\n      ‫املخــدر ونفــى معرفتــه باملتهــم ‪ ...............‬وباســتجواب الثاني‪:‬أقــر بنقــل‬\n      ‫احلشــيش املخــدر مــن محافظــة رأس تنــورة إلــى األحســاء بقصــد الترويــج‬\n      ‫كمــا أقــر بحيازتــه ملــا ضبــط يف شــقته مــن احلشــيش املخــدر بقصــد‬\n      ‫تخزينهــا لــأول لغــرض يبعهــا أو اســتعمالها كمــا أقــر بحيازتــه حلبــوب‬\n      ‫األمفيتامــن احملظــورة والهرويــن املخــدر وحبــوب البــرازوالم املضبوطــة‬\n      ‫يف شــقته بقصــد التعاطــي ونفــى عالقــة املتهــم ‪..............‬باملضبوطــات أو‬\n      ‫علمــه بعمليــة الترويــج أقــر باســتخدام جوالــه مــن نــوع ‪ .....‬يحمــل شــريحة‬\n                 ‫اتصــال رقــم (‪ )..............‬يف عمليــة التنســيق للنقــل الكميــة‪.‬‬\n      ‫وقــد أســفر التحقيــق عــن توجيــه االتهــام لــ‪ .............. /‬ببيــع (‪)15،9‬‬\n      ‫خمســة عشــر كيلــو وتســعة جــرام مــن احلشــيش املخــدر بقصــد االجتــار‬\n      ‫وحيــازة (‪ )9،180‬تســعة كيلــو ومائــة وثمانــون جرام ـ ًا مــن احلشــيش‬\n      ‫املخــدر بقصــد الترويــج وحيــازة قطعتــن من احلشــيش املخــدر بلغ وزنهما‬\n      ‫(‪ )95‬خمســة وتســعون جرام ـ ًا وعــدد (‪ )5‬خمــس حبــات مــن حبــوب‬\n      ‫األمفيتامــن احملظــور وعــدد (‪ )7‬ســبع حبــات مــن حبــوب البــرازوالم‬\n      ‫احملظــور وحيــازة عــدد (‪ )2‬كيســن نايلــون بهمــا آثــار الهرويــن بلــغ‬\n      ‫وزنهمــا (‪ )3،2‬ثالثــة جرامــات واثنــن مــن العشــرة مــن اجلــرام بقصــد‬\n                                           ‫التعاطــي وتعاطيــه ألنواعهــا يف الســابق‬\n\n\n‫‪349‬‬\n\f‫واتهــام ‪.............. /‬بنقــل (‪ )15‬خمســة عشــر كيلــو مــن احلشــيش املخــدر‬\n‫بقصــد الترويــج ‪ ،‬واحــراز (‪ )9،180‬تســعة كيلــو ومائــة وثمانــون جــرام‬\n‫مــن احلشــيش املخــدر بقصــد الترويــج باالشــتراك مــع األول وحيــازة عــدد‬\n‫(‪ )20‬عشــرون حبــة مــن حبــوب البــرازوالم احملظــورة وعــدد (‪)3‬ثــاث‬\n‫حبــات مــن حبــوب األمفيتامــن احملظــور وعــدد (‪ )8‬ثمــان أكيــاس‬\n‫حتــوي آثــار الهرويــن بلــغ وزن مجموعهــا (‪ )3،6‬ثالثــة جــرام وســتة مــن‬\n‫العشــرة مــن اجلــرام بقصــد التعاطــي وحيــازة عــدد (‪ )72‬حبــة مــن حبــوب‬\n‫الكونازيبــام بقصــد التعاطــي وتعاطيــه ألنواعهــا يف الســابق‪،‬املجرم‬\n‫مبوجــب املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫وتســتر همــا علــى مصــدر املخــدرات‪ .‬كمــا أثبــت التقريــر ايجابيــة‬\n‫العينــة رقــم (‪ )..............‬لعقــار الكونازيبــام املــدرج باجلــدول رقــم (‪)2‬‬\n‫فئــة (د) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة كمــا‬\n‫أثبــت التقريــر ايجابيــة العينتــن رقــم (‪..............‬ورقــم (‪ )..............‬ملــادة‬\n                             ‫الهرويــن املخــدر‪ .‬وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ -1‬ماجــاء يف اقــرار املتهــم األول املدونــة علــى الصفحــات رقــم‬\n‫(‪ )10،9،6،5‬مــن دفتــر التحقيــق املرفــق لفــه رقــم(‪ )34‬داخــل الطــرد‪.‬‬\n‫‪ -2‬ماجــاء يف اقــرار املتهــم الثانــي املدونــة علــى الصفحــات رقــم‬\n‫(‪ )8،7،2،1‬مــن دفتــر التحقيــق املرفــق لفــه رقــم(‪ )34‬داخــل الطــرد‪.‬‬\n‫‪-4‬ماجــاء يف محضــر القبــض املــدون علــى الصفحــات رقــم‬\n‫(‪ )17،16،15،14،13،12‬مــن دفتــر االســتدالل املرفــق لفــه(‪)15‬‬\n                                                                       ‫داخــل الطــرد‪.‬‬\n    ‫‪-5‬ما جاء يف التقرير الكيماوي املرفق لفة (‪ )42،41‬داخل الطرد ‪.‬‬\n\n\n                                                                                            ‫‪350‬‬\n\f      ‫وبالبحــث عــن ســوابقهم تبــن وجــود ثــاث عشــرة ســابقة للمتهــم األول‬\n      ‫األولــى معاكســة والثانيــة ســرقة والثالثــة دخــول منــزل لغــرض ســيء‬\n      ‫والرابعــة شــرب املســكرات وفعــل فاحشــة اللــواط واخلامســة شــرب‬\n      ‫املســكرات ودخــول املنــازل لغــرض ســيء والسادســة مخــدرات وحيــازة‬\n      ‫ســاح بــدون ترخيــص وشــرب املســكرات والســابعة تكــرار دخــول‬\n      ‫مستشــفى األمــل مــن اإلدمــان والثامنــة والتاســعة حيــازة واســتعمال‬\n      ‫مخــدرات والعاشــرة واحلاديــة عشــر حيــازة مخــدرات داخــل الســجن‬\n      ‫والثانيــة عشــر حيــازة وســتعمال مخــدرات والثالثــة عشــر حيــازة‬\n      ‫مخــدرات داخــل الســجن وحيــازة واســتعمال مخــدرات وتســتر على مروج‬\n      ‫املخــدرات وتبــن وجــود ثمــان ســوابق للمتهــم الثانــي األولــى أخالقيــة‬\n      ‫والثانيــة شــرب املســكرات والثالثــة حيــازة مخــدرات والرابعــة حيــازة‬\n      ‫واســتعمال مخــدرات وقيــادة الســيارة وهــو بحالــة ســكر واخلامســة‬\n      ‫شــرب املســكرات والتســبب يف حــادث مــروري والسادســة شــرب‬\n      ‫مســكرات واســتعمال مخــدرات والســابعة حيــازة واســتعمال مخــدرات‬\n      ‫وحيــازة أدوات اســتعمال املخــدرات وتكــرار ســوابقة والثامنــة اســتعمال‬\n                                                      ‫مخــدرات ‪ .‬إجــراءات أخــرى‪:‬‬\n      ‫ورد خطــاب مكافحــة املخــدرات رقــم (‪ )..............‬يف ‪1434/2/17‬ه ـ‬\n      ‫املتضمــن تعــاون املتهــم األول مــع املكافحــة يف ضبــط عــدد مــن‬\n      ‫مروجــي املخــدرات‪ .‬وحيــث إن مــا أقــدم عليــه املذكــوران ‪ ،‬وهمــا‬\n      ‫بكامــل أهليتهمــا املعتبــرة شــرع ًا ‪ ،‬فعــل مجــرم ومعاقــب عليــه نظام ـ ًا‬\n      ‫يف ضــوء نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n      ‫باملرســوم امللكــي الكــرمي (م‪ )39/‬وتاريــخ ‪1426/87‬ه ـ ممــا يتعــن‬\n      ‫معــه إحالتهمــا للمحكمــة اجلزائيــة اســتناد ًا علــى املادتــن(‪)128-126‬‬\n\n\n‫‪351‬‬\n\f‫مــن نظــام اإلجــراءات اجلزائيــة لطلــب إثبــات إدانتهمــا مبــا اســند إليهمــا‬\n                                                ‫واحلكــم عليهمــا مبــا يلــي ‪- :‬‬\n‫‪ -1‬احلكــم علــى األول والثانــي بالعقوبــة الــواردة يف الفقــرة األولــى مــن‬\n‫املــادة (‪ )38‬مــن النظــام املشــار إليــه لقــاء مــا أســند إليهمــا ‪ ،‬لكونهــا‬\n‫العقوبــة األشــد بنــاء علــى الفقــرة األولــى مــن املــادة (‪ )62‬مــن ذات النظــام‬\n‫وتشــديد العقوبــة عليهمــا لقــاء تعــدد ســوابقهما اســتناد ًا لبرقيــة نائــب‬\n                 ‫وزيــر الداخليــة رقــم (‪ )93958/5/5/1‬يف ‪1429/8/23‬هــ‪..‬‬\n‫‪ -2‬مصــادرة اجلوالــن املضبوطــن مــع املتهــم األول والثانــي واملســتخدم‬\n‫يف اجلرميــة املوصوفــان يف القــرار وفقـ ًا للفقــرة (األولــى) مــن املــادة (‪)53‬‬\n‫مــن نظــام املشــار إليــه وإيــداع املبالــغ يف حســاب إدارة املخــدرات بنــاء‬\n            ‫علــى تعميــم وزيــر الداخليــة رقــم (‪)47‬وتاريخ‪1421/2/18‬هــ‪. .‬‬\n‫‪ -3‬إلغــاء شــريحتي االتصــال املســتخدمة يف اجلرميــة وعــدم صرفهمــا‬\n‫للمتهمــن اســتناد ًا لتعميــم وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪9‬‬\n                                                               ‫‪1428/2/10-‬ه ـ‬\n‫‪ -4‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )56‬مــن النظــام‬\n                                                            ‫مبنعهــم مــن الســفر‪.‬‬\n           ‫‪ -5‬معاقبتهما بعقوبة تعزيرية لتسترهما على مصدر املخدرات‪.‬‬\n‫ا مــا‬‫هــذه دعــواي وبســؤال املدعــى عليــه األول ‪..............‬أجــاب قائ ـ ً‬\n‫ذكــره املدعــي العــام مــن بتاريــخ ‪1434/1/14‬ه ـ مت القبــض علــي مــن‬\n‫قبــل احــدى فــرق مكافحــة املخــدرات التابعــة حملافظــة األحســاء فهــذا‬\n‫صحيــح وكذلــك مــا ذكــره املدعــي العــام مــن أنــه مت االتصــال بــي علــى‬\n‫هاتفــي اجلــوال رقــم ‪..............‬وطلــب منــي (‪ )35‬كيلــو مــن احلشــيش‬\n                      ‫املخــدر مببلــغ وقــدره ‪ 18000‬ريــال فهــذا كلــه صحيــح‬\n\n\n                                                                                        ‫‪352‬‬\n\f      ‫وكذلــك مــا ذكــره املدعــي العــام مــن أننــي قمــت ببيــع (‪ )15،9‬خمســة‬\n      ‫عشــر كيلــو وتســعة جــرام مــن احلشــيش املخــدر وأنــه ُعثــر معــي قطعتــن‬\n      ‫مــن احلشــيش املخــدر تــزن مبجموعهمــا(‪ )95‬خمســة وتســعون جرام ـ ًا‬\n      ‫وعــدد(‪ )5‬خمــس حبــات مــن حبــوب األمفيتامــن وعــدد (‪ )7‬ســبع حبــات‬\n      ‫مــن حبــوب البــرازوالم وكيســن بهــا آثــار الهرويــن املخــدر قصــدي مــن‬\n                                  ‫حيازتهــا التعاطــي والترويــج فهــذا كلــه صحيــح‬\n      ‫وكذلــك مــا ذكــره املدعــي العــام مــن أننــي أتعاطــى احلشــيش املخــدر‬\n      ‫والهرويــن املخــدر فهــذا صحيــح وكذلــك مــا ذكــره املدعــي العــام مــن‬\n      ‫وجــود ثالثــة عشــر ســابقة علــي فصحيــح أيض ـ ًا وقــد خدعنــي فيهــا‬\n      ‫شــخص يدعــى ‪..............‬ســبق أن تعرفــت عليــه يف ســجن احلايــر وكان‬\n      ‫لــي عنــده مبلــغ وقــدره خمســة عشــر ألــف ريــال قيمــة ســيارة وأخبرنــي‬\n      ‫بأننــي إن ذهبــت بهــذه احلقيبــة التــي حتتــوي حشــيش فســوف يســلم لــي‬\n      ‫مبلغــي الــذي عنــده وأمــا مــا ذكــره املدعــي العــام مــن أننــي تســترت‬\n      ‫علــى مصدرهــا فغيــر صحيــح حيــث إننــي أخبرتهــم بأننــي اســتلمتها مــن‬\n                       ‫شــخص يدعــى ‪..............‬وأنــا تائــب ونــادم هكــذا أجــاب‬\n      ‫ا مــا ذكــره املدعــي‬ ‫وبســؤال املدعــى عليــه الثانــي ‪..............‬أجــاب قائ ـ ً‬\n      ‫العــام مــن أننــي قمــت بنقــل (‪ )15‬خمســة عشــر كيلــو مــن احلشــيش‬\n      ‫املخــدر بقصــد الترويــج وإحــراز (‪ )9،180‬تســعة كيلــو ومائــة وثمانــون‬\n      ‫جــرام مــن احلشــيش املخــدر بقصــد الترويــج باالشــتراك مــع األول فهــذا‬\n      ‫كلــه صحيــح وكذلــك مــا ذكــره املدعــي العــام مــن أنــه وجــد بشــقتي‬\n      ‫بعــد تفتيشــها عــدد (‪ )20‬عشــرون حبــة مــن حبــوب البــرازوالم احملظــورة‬\n      ‫وعــدد (‪)3‬ثــاث حبــات مــن حبــوب األمفيتامني احملظــور وعدد (‪ )8‬ثمان‬\n      ‫أكيــاس حتــوي آثــار الهرويــن بلــغ وزن مجموعهــا (‪ )3،6‬ثالثــة جــرام‬\n\n\n‫‪353‬‬\n\f‫وســتة مــن العشــرة مــن اجلــرام قصــدي وحيــازة عــدد (‪ )72‬حبــة من حبوب‬\n‫الكونازيبــام مــن حيازتهــا التعاطــي ووكذلــك مــا ذكــره املدعــي العــام‬\n‫مــن أننــي تعاطيــت ألنواعهــا يف الســابق فهــذا صحيــح أيض ـ ًا وكذلــك‬\n‫مــا ذكــره املدعــي العــام مــن وجــود ثمــان ســوابق علــي فهــذا صحيــح‬\n‫وأمــا مــا ذكــره املدعــي العــام مــن أننــي تســترت علــى مصــدر احلشــيش‬\n‫فغيــر صحيــح حيــث ذكــرت لهــم أن املدعــى عليــه األول هــو مــن وضعهــا‬\n‫عنــدي مــن أجــل حفظهــا هكــذا أجــاب وبســؤال املدعــي العــام عــن هــل‬\n‫ا ليــس لــدي ســوى مــا ذكرتــه يف أوراق املعاملــة‬            ‫لديــه بينــة أجــاب قائ ـ ً‬\n‫هكــذا أجــاب وباالطــاع علــى دفاتــر التحقيــق وجــد أن املدعــى عليهمــا‬\n‫أفــادا عــن مصــدر هــذا احلشــيش وباإلطــاع علــى املعاملــة وجــد فيهــا‬\n‫علــى لفــة رقــم ‪ 25‬التقريــر الكيمــاوي الشــرعي رقــم (‪ )..............‬لعــام‬\n‫‪1434‬ه ـ املتضمــن إيجابيــة عينــات رقــم(‪ ..............‬ورقــم (‪ ..............‬ورقــم‬\n‫(‪..............‬ورقــم (‪ )..............‬ورقــم (‪ )..............‬للحشــيش املخــدر املــدرج‬\n‫علــى اجلــدول رقــم (‪ )1‬فئــة (أ) كمــا أثبــت التقريــر ايجابيــة العينتــن رقم‬\n‫(‪/42‬هــ) ورقــم (‪ )..............‬ملــادة األمفيتامــن املــدرج باجلــدول رقــم (‪)2‬‬\n‫فئــة (ب) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة كمــا‬\n‫أثبــت التقريــر إيجابيــة العينتــن رقــم (‪ )..............‬ورقــم (‪ )..............‬لعقــار‬\n‫البــرازوالم املــدرج باجلــدول رقــم (‪ )2‬فئــة (د) امللحــق بنظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة كمــا أثبــت التقريــر ايجابيــة العينــة رقــم‬\n‫(‪ )..............‬لعقــار الكونازيبــام املــدرج باجلــدول رقــم (‪ )2‬فئــة (د) امللحــق‬\n‫بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة كمــا أثبــت التقريــر‬\n‫ايجابيــة العينتــن رقــم (‪ )..............‬ورقــم (‪ )..............‬ملــادة الهرويــن‬\n                                                                               ‫املخــدر ا‪.‬هـ‬\n\n\n                                                                                               ‫‪354‬‬\n\f      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإقــرار املدعــى عليهمــا‬\n      ‫وحيــث إن املــرء مؤاخــذ بإقــراره والتقريــر الكيمــاوي الشــرعي ولنهــي‬\n      ‫النبــي صلــى اهلل عليــه وســلم عــن كل مســكر ومفتــر كمــا يف حديــث‬\n      ‫أم ســلمه رضــي اهلل عنهــا وحيــث إن املدعــى عليهمــا أقــرا بالترويــج‬\n      ‫واحليــازة بقصــد التعاطــي وحيــث إن مــا أقــدم عليــه املدعــى عليهمــا‬\n      ‫ضــرب مــن ضــروب اإلفســاد بــاألرض لذلــك كلــه ثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه ‪ ..............‬ببيــع (‪ )15،9‬خمســة عشــر كيلــو وتســعة جــرام‬\n      ‫مــن احلشــيش املخــدر بقصــد االجتــار وحيــازة (‪ )9،180‬تســعة كيلــو‬\n      ‫ومائــة وثمانــون جرام ـ ًا مــن احلشــيش املخــدر بقصــد الترويــج وحيــازة‬\n      ‫قطعتــن مــن احلشــيش املخــدر بلــغ وزنهمــا (‪ )95‬خمســة وتســعون جرامـ ًا‬\n      ‫وعــدد (‪ )5‬خمــس حبــات مــن حبــوب األمفيتامــن احملظــور وعــدد (‪)7‬‬\n                                     ‫ســبع حبــات مــن حبــوب البــرازوالم احملظــور‬\n      ‫وحيــازة عــدد (‪ )2‬كيســن نايلــون بهمــا آثــار الهرويــن بلــغ وزنهمــا‬\n      ‫(‪ )3،2‬ثالثــة جرامــات واثنــن مــن العشــرة مــن اجلــرام بقصــد التعاطــي‬\n      ‫وتعاطيــه ألنواعهــا يف الســابق وكذلــك ثبــت لــدي إدانــة املدعــى عليــه ‪/‬‬\n      ‫‪ ..............‬بنقــل (‪ )15‬خمســة عشــر كيلــو مــن احلشــيش املخــدر بقصــد‬\n      ‫الترويــج ‪ ،‬واحــراز (‪ )9،180‬تســعة كيلــو ومائــة وثمانــون جــرام مــن‬\n      ‫احلشــيش املخــدر بقصــد الترويــج باالشــتراك مــع األول وحيــازة عــدد‬\n      ‫(‪ )20‬عشــرون حبــة مــن حبــوب البــرازوالم احملظــورة وعــدد (‪)3‬ثــاث‬\n      ‫حبــات مــن حبــوب األمفيتامــن احملظــور وعــدد (‪ )8‬ثمــان أكيــاس‬\n      ‫حتــوي آثــار الهرويــن بلــغ وزن مجموعهــا (‪ )3،6‬ثالثــة جــرام وســتة مــن‬\n      ‫العشــرة مــن اجلــرام بقصــد التعاطــي وحيــازة عــدد (‪ )72‬حبــة مــن حبــوب‬\n      ‫الكونازيبــام بقصــد التعاطــي وتعاطيــه ألنواعهــا يف الســابق ولــم يثبــت‬\n\n\n‫‪355‬‬\n\f‫لــدي تســترهما علــى مصــدر املخــدرات وحكمــت عليهمــا مبــا يلــي ‪:‬‬\n‫أو ًال ‪ :‬جلــد كل مــن املدعــى عليــه األول والثانــي ثمانــن جلــدة دفعــة‬\n‫واحــدة حــد املســكر ثاني ـ ًا ‪ :‬ســجن كل واحــد مــن املدعــى عليهمــا‬\n‫مــدة عشــر ســنوات حتتســب منهــا مــدة بقائهمــا بالســجن بخصــوص‬\n‫هــذه القضيــة وجلــد كل واحــد منهمــا ألــف جلــدة تعزيــر ًا مفرقــة علــى‬\n‫عشــرين دفعــة كل دفعــة خمســن جلــدة بــن كل دفعــة واألخــرى مــدة‬\n‫أســبوعني وإلــزام كل واحــد مــن املدعــى عليــه األول والثانــي بغرامــة‬\n‫ماليــة قدرهــا عشــرة آالف ريــال وذلــك مبوجــب املــادة ‪ 38‬مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة ثالث ـ ًا ‪ :‬منــع كل مــن املدعــى‬\n‫عليــه األول والثانــي مــن الســفر خــارج اململكــة مــدة عشــر ســنوات بعــد‬\n‫تنفيــذ مــدة محكوميتــه وذلــك مبوجــب املــادة ‪ 56‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة رابعـ ًا ‪ :‬مصــادرة اجلوالــن املضبوطــن مــع‬\n‫املدعى عليه األول الذي يحمل الرقم التسلســلي (‪ )..............‬و وكذلك‬\n‫اجلــوال املضبــوط مــع املدعــى عليــه الثانــي مــن نــوع ‪ .....‬واملســتخدمان يف‬\n‫اجلرميــة املوصوفــان يف القــرار وفقـ ًا للفقــرة (األولــى) مــن املــادة (‪ )53‬مــن‬\n‫نظــام املشــار إليــه وإيــداع املبالــغ يف حســاب إدارة املخــدرات بنــاء علــى‬\n                     ‫تعميــم وزيــر الداخليــة رقــم (‪)47‬وتاريخ‪1421/2/18‬هــ‪.‬‬\n‫خامس ـ ًا ‪ :‬إلغــاء شــريحة االتصــال رقــم (‪ )..............‬و رقــم (‪)..............‬‬\n‫املســتخدمتان يف اجلرميــة وعــدم صرفهمــا للمتهمــن اســتناد ًا لتعميــم‬\n                  ‫وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10- 9‬ه ـ‬\n‫سادسـ ًا ‪ :‬رد دعــوى املدعــي العــام بخصــوص معاقبــة املدعــى عليــه األول‬\n‫والثانــي عقوبــة تعزيريــة لقــاء تســترهما علــى مصــدر املواد املخــدرة لعدم‬\n‫ثبوتهــا وبــه حكمــت وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليــه‬\n\n\n                                                                                        ‫‪356‬‬\n\f      ‫قــرر املدعــي العــام االعتــراض علــى احلكــم وطلــب رفــع املعاملــة إلــى‬\n      ‫محكمــة االســتئناف بــدون الئحــة فأجبتــه لطلبــه وأمــا املدعــى عليهمــا‬\n           ‫قــررا قناعتهمــا بــه وبــه ختمــت اجللســة يف متــام الســاعة احلاديــة عشــر‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                 ‫وســلم ‪ .‬حــرر يف ‪ 1434/04/24‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪ 1434/06/27‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 08 : 15‬وفيهــا عــادت املعاملــة مــن محكمــة‬\n      ‫اإلســتئناف باملنطقــة الشــرقية برقــم ‪ 341215707‬يف ‪1434/06/19‬ه ـ‬\n      ‫واملتعلقــة بدعــوى املدعــي العــام ضــد ‪..............‬و ‪..............‬املدون هويتهما‬\n      ‫ســابق ًا يف قضيــة مخــدرات وبرفقهــا القــرار الشــرعي برقــم ‪34227641‬‬\n      ‫وتاريــخ ‪1434/05/29‬ه ـ الصــادر مــن الدائــرة اجلزائيــة الثالثيــة الثانيــة‬\n      ‫مبحكمــة االســتئناف باملنطقــة الشــرقية املتضمــن إنــه بدراســة‬\n      ‫القــرار وصــورة ضبطــه وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي‬\n      ‫وأحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى قرارنــا رقــم ‪ 34197957‬يف‬\n      ‫نصــه ‪:‬وبدراســة القــرار وصــورة ضبطــة‬      ‫‪1434/04/24‬ه ـ املتضمــن مــا ُّ‬\n      ‫وأوراق املعاملــة لوحــظ أن مــا حكــم بــه فضيلتــه علــى املدعــى عليهمــا‬\n      ‫مــن جــزاء وغرامــة قليــل جــدا نظــرا لســوابقهما وكثــرة الكميــة املباعة‬\n      ‫واحملــازه وكذلــك لــم يحكــم فضيلتــه مبصــادرة الســيارة املســتعملة يف‬\n      ‫نقــل احلشــيش ملالحظــة ذلــك واعــادة املعاملــة الكمــال الزمهــا واهلل‬\n      ‫املوفــق وعليــه أجيــب أصحــاب الفضيلــة قضــاة محكمــة االســتئناف‬\n      ‫وفقهــم اهلل لــكل خيربأننــي عدلــت عمــا حكمــت بــه علــى املدعــى‬\n      ‫عليهمــا فيمــا يخــص الســجن والغرامــة وحكمــت علــى كل واحــد مــن‬\n      ‫املدعــى عليهمــا وذلــك بســجنه مــدة اثنــا عشــر ســنة حتتســب منهــا مــده‬\n\n\n‫‪357‬‬\n\f‫بقائهــا بالســجن بخصــوص هــذه القضيــة وبغرامــة ماليــة قدرهــا اثنــا‬\n‫عشــر ألــف ريــال علــى كل واحــد منهمــا وأمــا فيمــا يخــص مصــادرة‬\n‫الســيارات فــإن املدعــي العــام لــم يطالــب بهــا واملدعــى عليهمــا ال ميلــكان‬\n‫هــذه الســيارات هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض ذلــك املدعــي‬\n‫العــام واملدعــى عليهمــا قــرروا جميعــا اعتراضهــم عليــه وطلبــوا رفــع‬\n‫املعاملــة الــى محكمــة االســتئاف بــدون الئحــة فأجبتهــم لطلبهــم وبــه‬\n‫ختمــت اجللســة يف متــام الســاعة ‪ 08 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/27‬هـ‬\n‫احلمد هلل وحده وبعد ‪ . . .‬فقد اطلعن ــا نحن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/1638844‬ج‪ 2‬وتاريــخ ‪1434/7/8‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n‫املكلــف برقــم ‪ 34/1215707‬وتاريــخ ‪1434/7/3‬ه ـ املرفــق بهــا القــرار‬\n‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪.............. /‬املســجل‬\n‫برقــم ‪ 34197957‬وتاريــخ ‪1434/4/24‬ه ـ اخلــاص بدعوى‪/‬املدعــي‬\n‫ـد‪/‬كل مــن‪............../1‬و‪............../2‬يف قضيــة مخــدرات وقــد‬\n                                                                ‫ٍ‬        ‫العــام ضـ‬\n‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه‬\n‫فضيلتــه علــى قرارنــا رقــم ‪/34227641‬ج‪/2‬ب وتاريــخ ‪1434/5/29‬ه ـ‬\n‫قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى‬\n ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/7/22‬هــ‪.‬‬\n\n\n\n\n                                                                                      ‫‪358‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":344,"source_page_end":358,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"dace94d7b19925fbcd06c993cd6f206755aaf0ca57a935cba81c46d186c1488c","normalized_text_hash":"641627917d78aa7ce34fd8f5f7e4a0e3be61e94f3032b423f73fd89d3df96199","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p344-34197957"},{"id":"7903f98c-5b29-57af-a2b6-b13072a312f6","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج حبوب محظورة -تعزير بالسجن واجللد واملنع من السفر وتعزير باملصادرة وبإلغاء شريحة جوال -وبإعادة مبلغ مرقم -شهادة موصلة -ثبوت إدانة.","document_number":"34246013","case_number":"34171979","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/19","year":"1434","subject":"مخدرات -ترويج حبوب محظورة -تعزير بالسجن واجللد واملنع من السفر وتعزير باملصادرة وبإلغاء شريحة جوال -وبإعادة مبلغ مرقم -شهادة موصلة -ثبوت إدانة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34246013 :‬تاريخه‪1434/6/19 :‬هـ‬\n                          ‫رقم الدعوى‪34171979 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34293815‬تاريخه‪1434/08/10:‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬ترويــج حبــوب محظــورة ‪ -‬تعزيــر بالســجن واجللــد واملنــع‬\n       ‫مــن الســفر وتعزيــر باملصــادرة وبإلغــاء شــريحة جــوال ‪ -‬وبإعــادة مبلــغ‬\n                                         ‫مرقــم ‪ -‬شــهادة موصلــة ‪ -‬ثبــوت إدانــة‪.‬‬\n\n\n\n\n       ‫املــواد ( ‪ ) 60 - 56 - 53 - 38‬مــن نظــام مكافحــة املخــدرات و املؤثــرات‬\n                                                                      ‫العقليــة‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بيــع احلبــوب احملظــورة بقصــد‬\n       ‫اإلجتــار ‪ -‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه‬\n       ‫بالعقوبــة الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة‬\n       ‫املخــدرات واملؤثــرات العقليــة واملنــع مــن الســفر ومصــادرة اجلــوال وإلغــاء‬\n       ‫الشــريحة املســتخدمة يف اجلرميــة ‪ ،‬حيــث إنــه مت القبــض علــى املدعــى‬\n       ‫عليــه بعــد ورود معلومــات مفادهــا أن املدعــى عليــه يعمــل يف محــل بيــع‬\n       ‫التمــور ويــروج احلبــوب احملظــورة ومت التنســيق مع أحــد املصادر ومتكينه‬\n       ‫مــن االتصــال علــى املدعــى عليــه علــى جوالــه وطلــب شــراء كميــة مــن‬\n       ‫احلبــوب فوافــق علــى ذلــك فتــم ترقيــم املبلــغ احلكومــي وتوجــه املصــدر‬\n       ‫إلــى مقــر املدعــى عليــه وتقابــل املصــدر مــع املدعــى عليــه حتــت أنظــار‬\n\n‫‪359‬‬\n\f‫الفرقــة القابضــة ثــم دخــا أحــد املكاتــب وبعــد أكثــر مــن دقيقتــن‬\n‫خــرج املصــدر وأعطــى اإلشــارة الدالــة علــى االســتالم والتســليم فتــم‬\n‫القبــض علــى املدعــى عليــه وضبــط املبلــغ احلكومــي معــه كمــا ضبــط‬\n‫معــه اجلــوال املســتخدم يف عمليــة التنســيق وقــد ســلم املصــدر احلبتــن‬\n‫التــي اســتلمها مــن املدعــى عليــه ‪ ،‬إنــكار املدعــى عليــه ‪ ،‬فأحضــر‬\n‫املدعــي العــام بينــة موصلــة وهــم أعضــاء الفرقــة القابضــة ‪ ،‬فثبتــت إدانــة‬\n‫املدعــى عليــه ‪ .‬بنــاء علــى مــا تقــدم حكمــت احملكمــة تعزيــر املدعــى‬\n‫عليــه بالســجن واجللــد واملنــع مــن الســفر ومصــادرة الهاتــف اجلــوال وإلغــاء‬\n‫شــريحته وإعــادة املبلــغ املرقــم ‪ُ .‬صــدق احلكــم من محكمة االســتئناف‪.‬‬\n\n\n\n\n‫اجلزائيــة‬\n   ‫ّ‬         ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة‬\n‫باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة يف محافظــة االحســاء املكلــف برقــم ‪ 34171979‬وتاريــخ‬\n‫‪ 1434/04/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34917746‬وتاريــخ‬\n‫‪ 1434/04/15‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/04/28‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 12 : 00‬وفيهــا حضــر املدعــي العــام وادعــى ضــد‬\n‫احلاضــر معــه ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪............‬‬\n‫قائــا يف دعــواه باالطــاع علــى محضــر القبــض و الضبــط والتفتيــش‬\n‫ا ُملعــد مــن قبــل مكافحــة املخــدرات مبحافظــة األحســاء املــؤرخ يف‬\n‫‪1434/3/8‬ه ـ تبــن أنــه مت القبــض علــى املدعــى عليــه إثــر معلومــات مــن‬\n‫أحــد مصادرهــم الســرية تفيــد بــأن املدعــى عيلــه يعمــل يف مصنــع ‪.....‬‬\n‫و يــروج احلبــوب احملظــورة وقــد مت متكــن املصــدر مــن االتصــال علــى‬\n\n                                                                                       ‫‪360‬‬\n\f      ‫جــوال املدعــى عليــه رقــم (‪ )..........‬وطلــب منــه شــراء حبــوب محظــورة‬\n      ‫مببلــغ مئــة ريــال فوافــق علــى ذلــك ‪ ،‬و أخبــره بــأن احلبــوب موجــودة لديــه‬\n      ‫يف مقــر عملــه فتــم ترقيــم املبلــغ احلكومــي وتفتيــش املصــدر وتوجــه‬\n      ‫املصــدر إلــى داخــل املصنــع حتــت أنظــار الفرقــة وتقابــل املصــدر مــع‬\n      ‫املدعــى عليــه ودخــا أحــد املكاتــب وبعــد أكثــر مــن دقيقتــن خــرج‬\n      ‫املصــدر وأعطــى اإلشــارة الدالــة علــى االســتالم والتســليم فتــم القبــض‬\n      ‫علــى املدعــى عليــه وضبــط املبلــغ احلكومــي بجيــب قميصــه العلــوي وهو‬\n      ‫املبلــغ املعــد لكشــف القضيــة كمــا ضبــط بحيازتــه اجلــوال املســتخدم‬\n      ‫يف عمليــة التنســيق نــوع (‪ )......‬يحمــل الرقــم املصنعــي (‪ )............‬ولــم‬\n      ‫يعثــر معــه علــى أي مــن احملظــورات يف ســيارته وقــد ســلم املصــدر احلبتني‬\n      ‫التــي اســتلمها مــن املدعــى عليــه وباســتجواب املدعــى عليــه أقــر بعائديــة‬\n      ‫اجلــوال املشــار إليــه لــه و ال يســتخدمه أحــد غيــره وقــد أثبــت التقريــر‬\n      ‫الكيماوي الشرعي رقم (‪ ).....‬لعام ‪1434‬هـ إيجابية ما مت ضبطه ملادة‬\n      ‫اإلمفيتامــن املنبــه احملظــور املدرجــة يف اجلــدول (‪ )2‬فئــة (ب) مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة وانتهــى التحقيــق مــع املدعــى‬\n      ‫عليــه إلــى توجيــه االتهــام لــه ببيــع حبتــن مــن حبــوب األمفيتامــن املنبــه‬\n      ‫احملظــور بقصــد االجتــار و املجــرم نظام ـ ًا يف ضــوء الفقــرة الثانيــة مــن‬\n      ‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n               ‫باملرســوم امللكــي الكــرمي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n                                                      ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n      ‫‪ -1‬إقــراره بعائديــة اجلــوال املســتخدم يف اجلرميــة لــه املــدون علــى‬\n          ‫الصفحتــن رقــم (‪ )2.1‬مــن ملــف التحقيــق املرفــق لفــة (‪.)10‬‬\n      ‫‪ -2‬محضــر القبــض والضبــط والتفتيــش املــدون علــى الصفحتــن رقــم‬\n\n\n‫‪361‬‬\n\f                                    ‫(‪ )11‬مــن ملــف االســتدالل املرفــق لفــة (‪.)5‬‬\n                           ‫‪ -3‬التقرير الكيماوي الشرعي املرفق لفة (‪.)20‬‬\n‫ـرعا‬\n   ‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شـ ً‬\n‫نظامــا ؛ لــذا اطلــب إثبــات مــا أسن ــد‬\n                                         ‫ً‬      ‫ـب عليــه‬\n                                                        ‫فعــل محــرم ومجــرم ومعاقـ ٌ‬\n                                                      ‫إليــه و احلكــم عليــه بالتالــي ‪:‬‬\n‫‪.1‬بالعقوبــة الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة‬\n                            ‫املخــدرات واملؤثــرات العقليــة لقــاء مــا أســند إليــه‪.‬‬\n‫‪.2‬منعــه مــن الســفر خــارج اململكــة بعــد تنفيــذ العقوبــة اســتناد ًا للفقــرة‬\n                                            ‫(‪ )1‬مــن املــادة (‪ )56‬مــن ذات النظــام‪.‬‬\n‫‪.3‬مصــادرة جــوال املتهــم نــوع (‪ ).....‬يحمــل الرقــم املصنعــي (‪)............‬‬\n‫املســتخدم يف اجلرمية اســتناد ًا للفقرة (‪ )1‬من املادة (‪ )53‬من ذات النظام‬\n‫‪ ،‬وايــداع األمــوال املتحصلــة مــن األعيــان يف حســاب إدارة املخــدرات‬\n‫اســتناد ًا لقــرار مجلــس الــوزراء رقــم (‪ )47‬وتاريــخ ‪1421/2/18‬هــ‪4.‬ـ‪.‬‬\n‫إلغاء شــريحة االتصال العائدة للمتهم املســتخدمة يف اجلرمية و املوصوفة‬\n‫يف القــرار وعــدم صرفهــا لــه مــرة أخــرى وفــق برقيــة وزيــر الداخليــة رقــم‬\n‫(‪ )9798/4/5/1‬وتاريــخ ‪1428/2/10-9‬ه ـ هــذه دعــواي وبعــرض‬\n‫الدعــوى علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام‬\n‫يف دعــواه مــن قيامــي ببيــع احلبــوب احملظــورة غيــر صحيــح والصحيــح‬\n‫أن زميلــي يف العمــل طلــب منــي أن اقــوم بحفــظ مبلــغ مائــة ‪ 100‬ريــال‬\n‫لكونــة وقــت غســيل التمــر فقمــت بأخــذ هــذا املبلــغ ثــم قبــض علينــا مــن‬\n‫املباحــث بعــد ذلــك هــذه إجابتــي وبعــرض ذلــك علــى املدعــي العــام قــال‬\n‫الصحيــح مــا ذكرتــه وبســؤاله البينــة علــى دعــواه قــال لــدي البينــه علــى‬\n‫ذلــك وســأحضرها يف اجللســة القادمــة لــذا قــررت رفــع اجللســة إلحضــار‬\n\n\n                                                                                            ‫‪362‬‬\n\f      ‫الشــهود يف القضيــة اهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                        ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/28‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق‪ 1434/05/27‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 11.30‬للنظــر بدعــوى املدعــي العــام ضــد‬\n      ‫وفيهــا حضــر وفيهــا حضــر الطرفــان كمــا يف اجللســة الســابقة وبســؤال‬\n      ‫املدعــي العــام عــن بينتــه قــال أنهــا لــم حتضــر يف هــذه اجللســة رغــم‬\n      ‫تبلغهــم بخطــاب هيئــة التحقيــق واالدعــاء العــام رقــم ‪ 341125574‬يف‬\n      ‫‪1434/5/7‬ه ـ وأطلــب اإلمهــال إلــى جلســة أخــرى إلحضــار الشــهود‬\n      ‫يف القضيــة لــذا قــررت رفــع اجللســة إلحضــار بينــة املدعــي العــام واهلل‬\n      ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                   ‫‪ 1434/05/27‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االثنــن املوافــق ‪1434/6/19‬ه ـ‬\n      ‫افتتحــت اجللســة للنظــر بدعــوى املدعــي العــام ضــد وفيهــا حضــر‬\n      ‫ال مــن‬\n            ‫الطرفــان كمــا يف اجللســة الســابقة واحضــر معــه للشــهادة ك ً‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....................‬و ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..........................‬وبســؤالهما‬\n      ‫ا اشــهد‬  ‫عمــا لديهمــا مــن شــهادة شــهد كل واحــد منهمــا مبفــرده قائ ـ ً‬\n      ‫بــأن أحــد املصــادر لدينــا بلــغ بــأن املدعــى عليــه يقــوم بترويــج احلبــوب‬\n      ‫احملظــورة يف مصنــع ‪ ......‬فقمنــا بالتنســيق مــع املصــدر واتصــل باملدعــى‬\n      ‫عليــه علــى أن يقــوم بشــراء احلبــوب منــه فوافــق املدعــى عليــه علــى ذلــك‬\n      ‫وطلــب منــه حبتــن مببلــغ مئــة ‪ 100‬ريــال واجتهنــا إلــى مصنــع التمــور‬\n      ‫وقمنــا بتفتيــش املصــدر وســلم املبلــغ احلكومــي ثــم اجتــه إلــى املدعــى‬\n      ‫عليــه وكلمــه ثــم دخــل معــه يف أحــد املكاتــب وعنــد خروجــه اعطانــا‬\n\n\n‫‪363‬‬\n\f‫اإلشــارة فتــم القبــض علــى املدعــى عليــه ويف جيبــه العلــوي املبلــغ‬\n‫احلكومــي وســلمنا املصــدر احلبتــن التــي مت شــرائها هــذا مــا رأينــا وبــه‬\n‫نشــهد وبعــرض ذلــك علــى املدعــى عليــه قــال مــا ذكــره الشــهود غيــر‬\n‫صحيــح وهــؤالء الشــهود ال اعرفهــم بعــد ذلــك جــرى ســؤال املدعــى عليــه‬\n‫عــن رقــم جوالــه فذكــر أن رقــم اجلــوال هــو املذكــور يف دعــوى املدعــي‬\n‫العــام وبالرجــوع إلــى التقريــر الكيمــاوي وجــدت فيــه إيجابيــة العينــة‬\n‫املضبوطــة لإلمفيتامــن بعــد ذلــك جــرى تزكيــة الشــاهدين مــن قبــل‬\n‫‪ ........‬ســعودي بالســجل املدنــي رقــم ‪ ........‬ســعودي بالســجل املدنــي رقــم‬\n‫‪ ...........‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبنــاء علــى شــهادة‬\n‫الشــاهدين املذكــورة أعــاه املعدلــن وفــق األصــول والقواعــد الشــرعية‬\n‫وفيهــا تفصيــل االتصــال علــى املدعــى عليــه وســماع صوتــه واإلتفــاق معــه‬\n‫علــى البيــع وحيــث أقــر املدعــى عليــه بــان اجلــوال املســتخدم معــه هــو‬\n‫اجلــوال الــذي ذكــره املدعــي العــام وبنــاء علــى قلــة الكميــة التــي قــام‬\n‫بترويجهــا املدعــى عليــه ولعــدم وجــود ســوابق مماثلــه لــه ونــزو ًال عــن‬\n‫احلــد األدنــى للمــادة ‪ 38‬مــن نظــام املخــدرات وبنــاء علــى املــادة ‪56 ، 53‬‬\n‫وبنــاء علــى املــادة ‪ 60‬وبنــاء علــى التقريــر الكيمــاوي وبنــاء علــى ذلــك‬\n‫كلــه فقــد حكمــت مبــا يلــي أو ًال ـ ثبــت لــدي قيــام املدعــى عليــه بترويــج‬\n‫حبتــن محظــورة وحكمــت بســجنه ملــدة ســنة وأربعــة أشــهر وجلــده مائــة‬\n‫وخمســن جلــده مفرقــة علــى ثــاث مــرات كل مــره خمســون جلــده‬\n‫بينهمــا عشــرة أيــام ودفعــه غرامــة ماليــة قدرهــا ثمانيــة آالف ‪8000‬‬\n‫ريــال ثانيـ ًا ـ منعــه مــن الســفر ملــدة ســنتني بعــد انتهــاء محكوميتــه ثالثـ ًا ـ‬\n‫مصــادرة الهاتــف اجلــوال وإلغــاء شــريحة االتصــال العائــدة للمدعــى عليــه‬\n‫وإعــادة املبلــغ احلكومــي الــذي اســتلمه املدعــى عليــه إلــى مكافحــة‬\n\n\n                                                                                            ‫‪364‬‬\n\f      ‫املخــدرات وبعــرض ذلــك عليــه وعلــى املدعــي العــام قــرر املدعــى عليــه‬\n      ‫عــدم قناعتــه وطلــب االســتئناف فأجبتــه لطلبــه وقــد ســلم نســخه مــن‬\n      ‫قــرار احلكــم يف نفــس اليــوم لتقــدمي الالئحــة االعتراضيــة وقــد أفهــم‬\n      ‫بــأن لــه مــدة ثالثــن يومـ ًا مــن تاريــخ االســتالم بعــد ذلــك يســقط حقــه يف‬\n      ‫طلــب االســتئناف وقــرر املدعــي العــام عــدم قناعتــه وطلــب االســتئناف‬\n      ‫فأجبتــه لطلبــه وقــرر بأنــه لــن يقــدم الئحــة اعتراضيــه وإمنــا يكتفــي‬\n      ‫بــأوراق املعاملــة والئحــة الدعــوى عــن واالعتــراض واهلل املوفــق اثبتــه‬\n                                                     ‫وللبيــان حــرر يف ‪1434/6/19‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد‪ ....‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n      ‫برقــم ‪ 34917746‬وتاريــخ ‪1434/7/25‬ه ـ املقيــدة لــدى احملكمــة‬\n      ‫برقــم ‪ 34/1877429‬وتاريــخ ‪1434/8/3‬ه ـ املرفــق بهــا القــرار الصــادر‬\n      ‫مــن فضيلــة القاضــي الشــيخ املســجل برقــم ‪ 34246013‬وتاريــخ‬\n      ‫‪1434/6/19‬ه ـ اخلــاص بدعوى‪/‬املدعــى العــام ضــد ‪ ..........‬يف قضيــة‬\n      ‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n      ‫فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n      ‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                        ‫وســلم حــرر يف ‪1434/8/9‬ه ـ‬\n\n\n\n\n‫‪365‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":359,"source_page_end":365,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d2d8527a5436db66b72d3fc5f50654a1eaf4770553ee3eb91739bac97c21eacc","normalized_text_hash":"b829a519d746669be447bca19c571c773632769bbca58b58d18341222bad2be2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p359-34246013"},{"id":"d2b90692-e8af-5a97-bc94-0240aa44532e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر - تستر -حتقيق ا -تعزير بالسجن واجللد والغرامة -إقامة حد املسكر على متعاطي احلشيش -تعزير باملنع والسفر -1املواد ( -الفقرة 1من املادة 53واملادة 56واملادة 60من نظام مكافحة املخدرات واملؤثرات العقلية .","document_number":"34197958","case_number":"34171997","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/24","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر - تستر -حتقيق ا -تعزير بالسجن واجللد والغرامة -إقامة حد املسكر على متعاطي احلشيش -تعزير باملنع والسفر -1املواد ( -الفقرة 1من املادة 53واملادة 56واملادة 60من نظام مكافحة املخدرات واملؤثرات العقلية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34197958:‬تاريخه ‪1434/4/24 :‬هـ‬\n                   ‫رقم الدعوى ‪34171997 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34238047‬تاريخه‪1434/06/12:‬هـ‬\n\n\n ‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر ‪ -‬تعاطــي احلشــيش املخــدر ‪-‬‬\n ‫تســتر ‪ -‬حتقيق ـ ًا ‪ -‬تعزيــر بالســجن واجللــد والغرامــة ‪ -‬إقامــة حــد‬\n              ‫املســكر علــى متعاطــي احلشــيش‪ -‬تعزيــر باملنــع والســفر‬\n\n\n\n\n ‫‪ -1‬املــواد ‪ ( -‬الفقــرة ‪ 1‬مــن املــادة ‪ 53‬واملــادة ‪ 56‬واملــادة ‪ 60‬مــن نظــام‬\n                                ‫مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n            ‫‪ -2‬تعميم سمو وزير الداخلية رقم ‪ 9798‬يف ‪1428/2/10‬هـ ‪.‬‬\n         ‫‪ -3‬تعميم سمو وزير الداخلية رقم ‪ 65980‬يف ‪1428/10/22‬هـ ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام ضــد املدعــى عليــه علــى شــراء و بيــع احلشــيش‬\n ‫املخــدر بقصــد االجتــار وتعاطيــه لــه‪ -‬وطلــب املدعــي العــام إثبــات مــا‬\n ‫أســند إليــه واحلكــم عليــه بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة‬\n ‫(‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ومصــادرة‬\n ‫اجلــوال املســتخدم يف اجلرميــة وإلغــاء شــريحة االتصــال وإلــزام املدعــى‬\n ‫عليــه بــرد املبلــغ احلكومــي وتعزيــره لقــاء تســتره علــى مصــدر احلشــيش‪،‬‬\n ‫حيــث إنــه مت القبــض علــى املدعــى عليــه متلبس ـ ًا بعــد ورود معلومــات‬\n ‫عنــه مفادهــا أنــه يقــوم بترويــج احلشــيش املخــدر ‪ ،‬صــادق املدعــى عليــه‬\n\n                                                                                         ‫‪366‬‬\n\f      ‫مبــا هــو منســوب إليــه ‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــر‬\n      ‫املدعــى عليــه بالســجن واجللــد واملنــع مــن الســفر والغرامــة ومصــادرة‬\n      ‫اجلــوال وإلغــاء شــريحته وإقامــة حــد املســكر ‪ .‬صــدق احلكــم مــن‬\n                                                          ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫اجلزائيــة‬\n         ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة‬\n      ‫باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة يف محافظــة االحســاء املكلــف برقــم ‪ 34171997‬وتاريــخ‬\n      ‫‪ 1434/04/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34917867‬وتاريــخ‬\n      ‫‪ 1434/04/15‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1434/04/24‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر املدعــي العــام ‪....‬‬\n      ‫املعمــد بالترافــع أمــام هــذه احملكمــة مبوجــب خطــاب ســعادة رئيــس‬\n      ‫دائــرة التحقيــق واالدعــاء العــام مبحافظــة االحســاء ذي الرقــم ‪13415‬‬\n      ‫والتاريــخ ‪ 1433/12/01‬ه ـ وادعــى ضــد احلاضــر معــه ‪ ....‬ســعودي‬\n      ‫ا يف دعــواه فباإلطــاع‬  ‫اجلنســي مبوجــب الســجل املدنــي رقــم ‪ ......‬قائ ـ ً‬\n      ‫علــى محضــر القبــض املعــد مــن قبــل إدارة مكافحــة املخــدرات تبــن‬\n      ‫أنــه بتاريــخ ‪1434/2/17‬ه ـ توفــرت معلومــات لــدى مكافحــة املخــدرات‬\n      ‫مــن مصادرهــا الســرية عــن قيــام املدعــى عليــه بترويــج احلشــيش املخــدر‬\n      ‫ومت عمــل اخلطــة الالزمــة لإلطاحــة باملدعــى عليــه باجلــرم املشــهود ومت‬\n      ‫متكــن املصــدر مــن االتصــال باملدعــى عليــه علــى جوالــه رقــم (‪)....‬‬\n      ‫وطلــب منــه بيعــه احلشــيش املخــدر فوافــق املدعــى عليــه علــى ذلــك وطلــب‬\n      ‫منــه احلضــور إليــه يف حــي ‪ .........‬ويف الوقــت واملــكان املتفــق عليــه ذهــب‬\n\n‫‪367‬‬\n\f‫املصــدر وركــب املدعــى عليــه معــه واجتهــوا إلــى حــي ‪ ............‬ومــن ثــم‬\n‫الرجوع حلي ‪ ............‬ثم نزل املدعى عليه من السيارة يف أحد األماكن‬\n‫بحــي ‪ ............‬ثــم عــاد املدعــى عليــه وســلم املصــدر قطعــة مــن احلشــيش‬\n‫املخــدر تــزن (‪ )3،4‬ثالثــة جرامــات وأربعــة مــن العشــرة مــن اجلــرام وبعــد‬\n‫القبــض علــى املدعــى عليــه أقــر بصحــة واقعــة الضبــط واســتالمه للمبلــغ‬\n‫احلكومــي املرقــم وبتفتيشــه لــم يعثــر علــى املبلــغ احلكومــي املرقــم ولــم‬\n‫يعثــر معــه علــى أي شــي مــن املمنوعــات وعثــر علــى جــوال مــن نــوع ‪......‬‬\n‫وشــريحة اتصــال رقــم (‪ )...‬واملســتخدم يف عمليــة الترويــج (صــدر أمــر‬\n                              ‫بحجــز اجلــوال والشــريحة متهيــد ًا ملصادرتهمــا)‪.‬‬\n‫وباســتجواب املدعــى عليــه ‪ /‬أقــر بتلقيــه اتصــا ًال مــن املصــدر علــى جواله‬\n‫املذكــور أعــاه وطلــب منــه قطعــة مــن احلشــيش املخــدر فطلــب منــه‬\n‫احلضــور إليــه وســلمه قطعــة مــن احلشــيش املخــدر كان قــد اشــتراها‬\n‫مــن شــخص لــم يذكــر أســمه‪ ،‬كمــا أقــر بتعاطيــه للحشــيش املخــدر‬\n                                                                       ‫يف الســابق ‪.‬‬\n‫وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪ 959‬ك ش) لعــام‬\n‫‪1434‬ه ـ ايجابيــة عينــة القطعــة املضبوطــة ملــادة احلشــيش احلشــيش‬\n‫املخــدر احملظــور واملــدرج يف اجلــدول (‪ )1‬فئــة (أ) مــن نظــام مكافحــة‬\n                                                  ‫املخــدرات واملؤثــرات العقليــة‪.‬‬\n‫وقــد أســفر التحقيــق عــن توجيــه االتهــام ل ـ ‪ .... /‬بشــراء وبيــع قطعــة‬\n‫مــن احلشــيش املخــدر تــزن (‪ )3،4‬ثالثــة جرامــات وأربعــة مــن العشــرة‬\n‫مــن اجلــرام بقصــد االجتــار وتعاطيــه لنوعــه يف الســابق ‪ ،‬وتســتره علــى‬\n                                                         ‫مصــدر احلشــيش املخــدر‪.‬‬\n                                                   ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n\n\n                                                                                       ‫‪368‬‬\n\f      ‫‪ -1‬مــا جــاء يف أقوالــه املدونــة علــى الصفحــة رقــم (‪ )2-1‬مــن دفتــر‬\n                                                                             ‫التحقيــق لفــه ‪.‬‬\n      ‫‪ -2‬محضــر القبــض املنــوه عنــه املــدون علــى الصفحــة رقــم (‪ )12‬املرفــق‬\n                                                                               ‫لفــة رقــم (‪. )9‬‬\n                                            ‫‪ -3‬التقرير الكيماوي املرفق على اللفة‪.‬‬\n      ‫وحيث إن ما أقدم عليه املذكور ‪ ،‬وهو بكامل أهليته املعتبرة شرعاً‪،‬‬\n      ‫فعــل محــرم ومعاقــب علي ــه شــرع ًا ونظامـ ًا يف ضــوء الفقــرة الثانيــة م ــن‬\n      ‫املــادة الثالثــة م ــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n      ‫باملرســوم امللكــي الكــرمي (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ أطلــب إثبــات‬\n                                            ‫مــا اســند إليــه واحلكــم عليــه مبــا يلــي ‪- :‬‬\n      ‫‪-1‬العقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )38‬مــن النظــام املشــار‬\n      ‫إليــه لقــاء مــا أســند إليــه ‪ ،‬لكونهــا العقوبــة األشــد اســتناد ًا للفقــرة‬\n                                            ‫األولــى مــن املــادة (‪ )62‬مــن ذات النظــام‪.‬‬\n      ‫‪-2‬احلكــم مبصــادرة جهــاز اجلــوال املوصــوف يف القــرار املســتخدمة يف‬\n      ‫اجلرميــة وفــق املــادة (‪ )53‬مــن نفــس النظــام وإيــداع املبالــغ يف حســاب‬\n      ‫ـاء علــى تعميــم وزيــر الداخليــة رقــم (‪ )74‬وتاريــخ‬         ‫إدارة املخــدرات بنـ ً‬\n                                                                          ‫‪1421/2/18‬ه ـ ‪.‬‬\n      ‫‪-3‬إلغــاء شــرائح االتصــال املوصوفــة يف القرار وفــق برقية وزير الداخلية‬\n                                ‫رقم (‪ )9798/4/5/1‬وتاريخ ‪1428/2/10-9‬هـ‪.‬‬\n      ‫‪-4‬إلزامــه بــرد املبلــغ احلكومــي العائــد ملكافحــة املخــدرات باألحســاء‬\n      ‫وقــدره (‪ )100‬مائــة ريــال اســتناد َا لتعميــم وزيــر الداخليــة رقــم (‪)65980‬‬\n                                                           ‫وتاريــخ ‪1422/10/23-22‬هـ‪.‬‬\n      ‫‪-5‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )56‬مــن النظــام مبنعــه‬\n\n\n‫‪369‬‬\n\f                                                                        ‫مــن الســفر‪.‬‬\n             ‫‪ _6‬بعقوبة تعزيرية لقاء تستره على مصدر احلشيش املخدر ‪.‬‬\n                                                                        ‫هذه دعواي‬\n‫ا مــا ذكــره املدعــي العــام مــن أننــي‬  ‫وبســؤال املدعــى عليــه أجــاب قائ ـ ً‬\n‫قمــت ببيــع قطعــة مــن احلشــيش املخــدر تــزن (‪ )3،4‬ثالثــة جرامــات‬\n‫وأربعــة مــن العشــرة مــن اجلــرام مببلــغ وقــدره مائــة ريــال بقصــد الترويــج‬\n‫فهــذا صحيــح حيــث إنــه مت االتصــال بــي علــى جوالــي رقــم ‪ ....‬واتفقــت‬\n‫معهــم علــى أن يحضــروا إلــي يف حــي ‪ ............‬وكذلــك مــا ذكــره‬\n‫املدعــي العــام مــن أنــه بتاريــخ ‪1434/2/17‬ه ـ قبــض علــي فهــذا صحيــح‬\n‫وكذلــك مــا ذكــره املدعــي العــام مــن أننــي أتعاطــى احلشــيش املخــدر‬\n‫فصحيــح وأمــا مــا ذكــره املدعــي العــام مــن أننــي تســترت علــى مصــدر‬\n‫احلشــيش فهــذا غيــر صحيــح حيــث إننــي أخبرتهــم بأننــي اشــتريتها مــن‬\n‫شــخص ال أعرفــه وأنــا تائــب ونــادم هكــذا أجــاب وبســؤال املدعــي‬\n‫العــام هــل لديــه بينــة علــى أن املدعــى عليــه تســتر علــى مصــدر احلشــيش‬\n‫ا ليــس لــدي ســوى مــا ذكرتــه يف املعاملــة هكــذا أجــاب‬          ‫أجــاب قائ ـ ً‬\n‫وبالرجــوع إلــى املعاملــة وجــد فيهــا علــى لفــة رقــم ‪ 12‬صحيفــة رقــم ‪2‬‬\n‫أقــوال املدعــى عليــه تبــن أنــه أخبرهــم بــأن مــن أعطــاه احلشــيش هــو‬\n‫شــخص مينــي ال يعــرف اســمه وهــي نفــس اإلجابــة التــي ذكرهــا لدينــا‬\n‫يف مجلــس احلكــم كمــا جــرى اإلطــاع علــى املعاملــة وجــد فيهــا‬\n‫علــى لفــة رقــم ‪ 24‬التقريــر الكيمــاوي الشــرعي رقــم ( ‪ 959‬ك ش )‬\n‫لعــام ‪1434‬ه ـ املتضمــن إيجابيــة العينــة املرســلة ملــادة احلشــيش املخــدر‬\n‫واســتهالك جميــع العينــات املرســلة يف التحليــل ا‪.‬ه ـ فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة وإقــرار املدعــى عليــه بترويــج قطعــة مــن احلشــيش‬\n\n\n                                                                                        ‫‪370‬‬\n\f      ‫املخــدر تــزن (‪ )3،4‬ثالثــة جرامــات وأربعــة مــن العشــرة من اجلــرام بقصد‬\n      ‫االجتــار وتعاطيــه لنوعــه يف الســابق وحيــث إن املدعــى عليــه أنكــر‬\n      ‫تســتره علــى مصــدره وحيــث إن املدعــي العــام لــم يحضــر بينــة علــى ذلــك‬\n      ‫وللتقريــر الكيمــاوي الشــرعي ولنهــي النبــي صلــى اهلل عليــه وســلم عــن‬\n      ‫كل مســكر ومفتــر كمــا يف حديــث أم ســلمه رضــي اهلل عنهــا وحيــث‬\n      ‫إن مــا أقــدم عليــه املدعــى عليــه ضــرب مــن ضــروب اإلفســاد بــاألرض‬\n      ‫وحيــث إن احلشــيش يشــترك مــع اخلمــر يف منــاط احلكــم وحيــث إن‬\n      ‫العقوبــة األخــف تدخــل يف العقوبــة األشــد لذلــك كلــه ثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه بترويــج قطعــة مــن احلشــيش املخــدر تــزن (‪ )3،4‬ثالثــة‬\n      ‫جرامــات وأربعــة مــن العشــرة مــن اجلــرام بقصــد االجتــار وتعاطيــه لنوعــه‬\n      ‫يف الســابق ولــم يثبــت لــدي تســتره علــى مصــدر احلشــيش وحكمــت‬\n      ‫عليــه مبــا يلــي ‪ :‬أو ًال ‪ :‬جلــد املدعــى عليــه ثمانــون جلــدة دفعــة واحــدة حــد‬\n      ‫املســكر ثاني ـ ًا ‪ :‬ســجن املدعــى عليــه مــدة ســنتني حتتســب منهــا مــدة‬\n      ‫بقائــه بالســجن بخصــوص هــذه القضيــة وجلــد املدعــى عليــه مائتــن‬\n      ‫جلــدة تعزيــر ًا مفرقــة علــى أربــع دفعــات كل دفعــة خمســن جلــدة بــن‬\n      ‫كل دفعــة واألخــرى مــدة أســبوعني وبغرامــة ماليــة قدرهــا ألفــن ريــال‬\n      ‫وقــد نزلــت عــن العقوبــة املقــررة نظامــا وذلــك مبوجــب املــادة (‪ )60‬مــن‬\n      ‫نظامــا مكافحــة املخــدرات نظــرا لقلــة الكميــة ولعــدم وجــود ســوابق‬\n      ‫علــى املدعــى عليــه ثالثـ ًا ‪ :‬منــع املدعــى عليــه مــن الســفر خــارج اململكــة‬\n      ‫مــدة ســنتني بعــد تنفيــذ مــدة محكوميتــه وذلــك مبوجــب املــادة ‪ 56‬مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة رابع ـ ًا ‪ :‬مصــادرة جهــاز‬\n      ‫اجلــوال الــذي يحمــل الرقــم (‪ )....‬اســتناد ًا للفقــرة رقــم (‪ )1‬مــن املــادة‬\n      ‫(‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وإيــداع املبالــغ‬\n\n\n‫‪371‬‬\n\f‫ـاء علــى تعميــم وزيــر‬\n                       ‫يف حســاب اإلدارة العامــة ملكافحــة املخــدرات بنـ ً‬\n‫الداخليــة رقــم (‪ )47‬وتاريــخ ‪1421/2/18‬ه ـ خامس ـ ًا ‪ :‬إلغــاء شــريحة‬\n‫هاتــف اجلــوال املنــوه عنهــا رقــم ‪ ....‬لقــاء اســتخدامها يف التنســيق لعمليــة‬\n‫ال اســتناد ًا لتعميــم صاحــب‬   ‫الترويــج وعــدم تزويــده بــذات الرقــم مســتقب ً‬\n‫الســمو امللكــي وزيــر الداخليــة رقــم ‪ 9798‬وتاريــخ ‪1428/02/10‬ه ـ‬\n‫سادسـ ًا ‪ :‬إلــزام املدعــى عليــه بإعــادة اجلــزء املتبقــي مــن املبلــغ احلكومــي‬\n‫املرقــم املوصــوف يف القــرار وقــدره (‪ )100‬مائــة ريــال إســتناد ًا لتعميــم‬\n‫صاحــب الســمو امللكــي وزيــر الداخليــة رقــم (‪ )65980‬وتاريــخ ‪-22‬‬\n‫‪1428/10/ 23‬ه ـ ســابع ًا ‪ :‬رد دعــوى املدعــي العــام بخصــوص معاقبــة‬\n‫املدعــى عليــه عقوبــة تعزيريــة لقــاء تســتره علــى مصــدر احلشــيش لعــدم‬\n‫ثبوتهــا وبــه حكمــت وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليــه‬\n‫قــرر املدعــي العــام اعتراضــه علــى احلكــم وطلــب رفــع املعاملــة إلــى‬\n‫محكمــة اإلســتئناف بــدون الئحــة فأجبتــه لطلبــه وأمــا املدعــى عليــه‬\n‫قــرر قناعتــه بــه وبــه ختمــت اجللســة يف متــام الســاعة ‪ 10 : 00‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                    ‫حــرر يف ‪ 1434/04/24‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق‪ 1434/06/26‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09 : 45‬وفيهــا عــادت املعاملــة مــن محكمــة‬\n‫اإلســتئناف باملنطقــة الشــرقية برقــم ‪ 341180477‬يف ‪1434/06/20‬ه ـ‬\n‫واملتعلقــة بدعــوى املدعــي العــام ضــد ‪ ....‬املــدون هويتــه ســابق ًا يف‬\n‫قضيــة مخــدرات وبرفقهــا القــرار الشــرعي برقــم ‪ 34238047‬وتاريــخ‬\n‫‪1434/06/12‬ه ـ الصــادر مــن الدائــرة اجلزائيــة األولــى مبحكمــة‬\n‫االســتئناف باملنطقــة الشــرقية املتضمــن إنــه بدراســة القــرار وصــورة‬\n\n\n                                                                                        ‫‪372‬‬\n\f      ‫ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم قاضــي اســتئناف‬\n      ‫د‪ ......‬ختمــه وتوقيعــه قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n      ‫‪ .....‬ختمــه وتوقيعــه وبــه ختمــت اجللســة يف متــام الســاعة ‪ 09 : 50‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                      ‫حــرر يف ‪ 1434/06/26‬ه ـ‬\n\n\n\n\n‫‪373‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":366,"source_page_end":373,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"351cd508214245a87014c39167f7d1997c3900256af28a013861e942c7704d95","normalized_text_hash":"991002e8bccad54d89788a1d3b541b433d6cc4606ecd55c8e12370e3afa09190","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p366-34197958"},{"id":"de7d84b4-7a01-512e-a44b-a2195061db97","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -تعاطي احلشيش املخدر - تعزير بالسجن واجللد والغرامة -اإلقرار -رجوع عن إقرار -اخذ","document_number":"34201368","case_number":"34172437","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/9","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -تعاطي احلشيش املخدر - تعزير بالسجن واجللد والغرامة -اإلقرار -رجوع عن إقرار -اخذ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34201368 :‬تاريخه ‪1434/04/9 :‬هـ‬\n                    ‫رقم الدعوى ‪34172437 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34210091‬تاريخه‪1434/05/08:‬هـ‬\n\n\n ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬تعاطــي احلشــيش املخــدر ‪-‬‬\n ‫تعزيــر بالســجن واجللــد والغرامــة ‪ -‬اإلقــرار ‪ -‬رجــوع عــن إقــرار ‪ -‬اخــذ‬\n                                                                        ‫تعهــد‪.‬‬\n\n\n\n                  ‫املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام ضــد املدعــى عليــه باتهامه بترويــج احلبوب احملظورة‬\n ‫وتعاطيــه احلشــيش املخــدر واتهامــه باالحتيــال ‪ ،‬وطلــب املدعــي العــام‬\n ‫إثبــات إدانتــه مبــا أســند إليــه و احلكــم عليــه بعقوبــة الســجن و اجللــد‬\n ‫والغرامــة و املنــع مــن الســفر و إثبــات إدانتــه ببيــع مــا أوهــم أنهــا حبــوب‬\n ‫محظــورة احتيــا ًال مبقابــل و إلغــاء الشــريحة الهاتفيــة املســتخدمة يف‬\n ‫اجلرميــة و عــدم صرفهــا لنفــس املشــترك ورد املبلــغ املفقــود و تشــديد‬\n ‫العقوبــة لترويجــه احلبــوب احملظــورة‪ ،‬حيــث إنــه مت القبــض علــى‬\n ‫املدعــى عليــه بعــد إخباريــة مفادهــا أن املدعــى عليــه يقــوم بترويــج‬\n ‫احلبــوب احملظــورة و مت التنســيق مــع أحــد املصــادر الســرية لإليقــاع‬\n ‫باملدعــى عليــه متلبس ـ ًا و تقابــل املصــدر مــع املدعــى عليــه و متــت عمليــة‬\n ‫االســتالم و التســليم و مت القبــض علــى املدعــى عليــه بعــد مــدة و مت‬\n ‫تعــرف أعضــاء الفرقــة القابضــة علــى املدعــى عليــه ‪ ،‬كمــا أقــر املدعــى‬\n                                                                                         ‫‪374‬‬\n\f      ‫عليــه بالدعــوى وأنكــر تعاطــي احلشــيش‪ ،‬بنــاء علــى مــا تقــدم حكمــت‬\n      ‫احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد والغرامــة واملنــع مــن‬\n      ‫الســفر ومصــادرة الهاتــف اجلــوال وإلغــاء الشــريحة وأخــذ التعهــد القــوي‬\n      ‫بعــدم العــودة ملــا بــدر منــه وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫اجلزائيــة بحائــل املكلــف برقــم ‪ 34172437‬وتاريــخ‬       ‫ّ‬         ‫احملكمــة‬\n      ‫‪1434/04/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34906011‬وتاريــخ‬\n      ‫‪1434/04/14‬ه ـ ففــي يــوم اإلثنــن املوافــق ‪1434/04/29‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 10 :00‬وفيهــا قــدم املدعــي العــام ‪ ......‬الئحــة دعــوى‬\n      ‫عامــة يف القضيــة رقــم (‪3402600088‬ح‪ )1‬وفيهــا بصفتــي مدعي ـ ًا‬\n      ‫عام ـ ًا يف دائــرة اإلدعــاء العــام بفــرع الهيئــة مبنطقــة حائــل أدعــي علــى‬\n      ‫‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).......‬قبــض عليــه‬\n      ‫بتاريــخ ‪1434/3/1‬ه ـ فإنــه باالطــاع علــى محضــر البــاغ املعــد مــن‬\n      ‫قبــل مكافحــة املخــدرات مبنطقــة حائــل بتاريــخ ‪1433/12/19‬ه ـ تبــن‬\n      ‫تبلغهــم مــن أحــد مصادرهــم الســرية عــن وجــود شــخص يدعــى ‪، ......‬‬\n      ‫يســكن بحــي (‪ )........‬يقــوم بترويــج احلبــوب احملظــورة واســتعد املصــدر‬\n      ‫لإلطاحــة بــه باجلــرم املشــهود و باالطــاع علــى محضــر البــاغ املعــد‬\n      ‫بتاريــخ ‪1434/1/25‬ه ـ تبــن تبلغهــم مــن أحــد مصادرهــم الســرية عــن‬\n      ‫وجــود شــخص يدعــى ‪ ،....‬يقــوم بترويــج احلبــوب احملظــورة ويســكن‬\n      ‫بحــي (‪ ،)......‬واســتعد املصــدر لالطاحــة بــه باجلــرم املشــهود وباالطــاع‬\n\n‫‪375‬‬\n\f‫علــى محضــر إيضاحــات الواقعــة املتضمــن لعمليــة الشــراء مــن املــروج‬\n‫(املدعــى عليــه) املعــد بتاريــخ ‪1433/12/19‬ه ـ ويف متــام الســاعة الرابعــة‬\n‫ـاء مت متكــن املصــدر مــن االتصــال علــى املدعــى عليه على‬        ‫والنصــف مسـ ً‬\n‫جــوال رقــم (‪ ).....‬وبعــد الســام عليــه طلــب منــه حبــوب محظــورة بقيمــة‬\n‫مائــة ريــال فوافــق علــى ذلــك وطلــب مــن املصــدر احلضــور إلــى منزلــه يف‬\n‫حــي (‪ ).......‬وإنهــاء املكاملــة وكان ذلــك علــى مســمع مــن طاقــم الفرقــة‬\n‫ـراء للذمــة وتزويــده باملبلــغ احلكومــي‬ ‫ومت تفتيــش املصــدر وســيارته إبـ ً‬\n‫املرقــم وحتــرك املصــدر حتــت أنظــار الفرقــة وعنــد وصولــه للموقــع‬\n‫احملــدد شــوهد املدعــى عليــه واقف ـ ًا أمــام منزلــه وعنــد توقــف املصــدر‬\n‫بســيارته ركــب معــه املدعــى عليــه وبعــد أقــل مــن دقيقــة ترجــل مــن‬\n‫الســيارة ودخــل داخــل املنــزل وكان ذلــك أمــام أنظــار الفرقــة القابضــة‪،‬‬\n‫ثــم حتــرك املصــدر بســيارته ولــم يغــب عــن أنظــار الفرقــة حتــى توقــف‬\n‫وقــام بتســليم قائــد الفرقــة مــا قــد اســتلمه هــو ســابق ًا مــن املدعــى عليــه‬\n‫وتبــن أنهــا (‪ )3‬ثــاث حبــات بيضــاء اللــون حتمــل عالمــة الكبتاجــون‬\n‫يشــتبه أن تكــون مــن احلبــوب احملظــورة (ثبــت إيجابيتهــا) وحرص ـ ًا‬\n‫علــى عــدم انكشــاف املصــدر مت تأجيــل القبــض عليــه وباالطــاع‬\n‫علــى محضــر إيضاحــات الواقعــة املتضمــن لعمليــة الشــراء مــن املــروج‬\n‫( املدعــى عليــه) املعــد بتاريــخ ‪1434/1/25‬ه ـ ويف متــام الســاعة الرابعــة‬\n‫والنصــف عصــر ًا مت متكــن املصــدر مــن االتصــال علــى جــوال املدعــى‬\n‫عليــه رقــم (‪ )...‬وبعــد الســام طلــب مــن املصــدر احلضــور ملنزلــه بحــي‬\n‫ال‪ ...‬وأنهــى املكاملــة وكان ذلــك علــى مســمع مــن طاقــم الفرقــة ومت‬\n‫ـراء للذمــة ومت تزويــده باملبلــغ احلكومــي‬ ‫تفتيــش املصــدر وســيارته إبـ ً‬\n‫املرقــم وتكليــف أحــد رجــال األمــن مبرافقــة املصــدر ملشــاهدة عمليــة‬\n\n\n                                                                                         ‫‪376‬‬\n\f      ‫االســتالم والتســليم وحتــرك املصــدر ورجــل األمــن حتــت أنظــار الفرقــة‬\n      ‫وعنــد وصولهمــا للموقــع احملــدد مــن قبــل املدعــى عليــه شــوهد واقف ـ ًا‬\n      ‫أمــام منزلــه وقــام املصــدر بتســليمه املبلــغ احلكومــي املرقــم وقــام‬\n      ‫املدعــى عليــه بتســليمه الكميــة املتفــق عليهــا علــى مــرأى مــن رجــل‬\n      ‫األمــن املرافــق وحتــركا وقــام املصــدر بإعطــاء قائــد الفرقــة (‪ )3‬ثــاث‬\n      ‫حبــات بيضــاء اللــون حتمــل عالمــة الكبتاجــون يشــتبه بــأن تكــون مــن‬\n      ‫احلبــوب احملظــورة (ثبــت ســلبيتها) ومت تأجيــل القبــض عليــه حرص ـ ًا‬\n      ‫علــى عــدم انكشــاف املصــدر وباالطــاع علــى احملضــر املعــد بتاريــخ‬\n      ‫ـاء متــت مشــاهدة‬ ‫‪1434/3/1‬ه ـ ويف متــام الســاعة العاشــرة والنصــف مسـ ً‬\n      ‫املدعــى عليــه عنــد أحــد احملــات التجاريــة يف حــي ‪ ............‬بالقــرب‬\n      ‫مــن منزلــه ومت التوجــه إليــه وعنــد مشــاهدته لرجــال األمــن بانــت عليــه‬\n      ‫عالمــات االرتبــاك وبعــد الســيطرة عليــه وتفتيشــه لــم يعثــر معــه علــى‬\n      ‫أي شــيء مــن املمنوعــات وتبــن أنــه‪ ..... /‬وعثــر معــه علــى جــوال ‪.....‬‬\n      ‫أبيــض ليــس هــو اجلــوال املســتخدم يف عمليــة الترويــج ولــم يعثــر علــى‬\n      ‫املبلــغ احلكومــي املرقــم ومت عــرض املدعــى عليــه علــى العضــو املرافــق‬\n      ‫للمصــدر حــن شــراء املخــدرات مــن هــذا املــروج وأفــاد العضــو بــأن ‪ ...‬هــو‬\n      ‫مــن قــام بعمليــة البيــع يف ‪ 1/25‬و وباالطــاع علــى محضــر التعــرف املعــد‬\n      ‫بتاريــخ ‪1434/3/3‬ه ـ فقــد تعــرف املــازم أول رقــم (‪ )... ..‬والرقيــب رقــم‬\n      ‫(‪ )...‬علــى املدعــى عليــه واتضــح لهمــا بأنــه هــو مــن قــام بعمليــة االســتالم‬\n                                                   ‫والتســليم بتاريــخ ‪1433/12/19‬ه ـ‬\n      ‫وباســتجوابه بشــأن القضيــة رقــم (‪340260088‬ح‪ )1‬أقــر ببيــع ثــاث‬\n      ‫حبــات ولكنــه نفــى أن تكــون محظــورة وإمنــا كانــت حبــوب حساســية‬\n      ‫وقــام بنقــش قوســن متقابلــن علــى كل حبــة ليوهــم مــن يريــد الشــراء‬\n\n\n‫‪377‬‬\n\f‫بأنهــا حبــوب كبتاجــون وأنــه قــام بهــذه العمليــة ثــاث مــرات وأقــر‬\n‫بتعاطيــه للحشــيش املخــدر و أفــاد مبصــدر ماقــام ببيعــه وباســتجوابه‬\n‫بشــأن القضيــة رقــم (‪340260091‬ح‪ )1‬أقــر ببيــع ثــاث حبــات محظــورة‬\n‫وأقــر بــأن اجلــوال ذو الرقــم (‪ )............‬يعــود لــه و أفــاد مبصــدر مــا‬\n‫قــام ببيعــه وق ــد أثب ــت الـتقـريـ ــر الكـيـميائـ ــي أحــراز رقــم (‪)1717‬‬\n‫الص ــادر م ــن املركــز اإلق ــليمي ملراقبــة السم ــوم مب ــنطقة القص ــيم‬\n‫بـرق ــم (‪/2799‬م س‪ )45/65/‬وتاريــخ ‪1433/12/28‬ه ـ إيجابيــة (‪)3‬‬\n‫الثــاث حبــات ملــادة االمفيتامــن وهــو مــن املــواد الكيميائيــة املنبهــة‬\n‫للجهــاز العصبــي املركــزي واملدرجــة بجــدول املؤثــرات العقليــة رقــم‬\n‫(‪ )2‬وفئــة (ب) التــي عناهــا تعميــم وزارة الصحــة رقــم ‪911/27‬س يف‬\n‫‪1427/4/12‬ه ـ واملبنــي علــى تعميــم وزارة الداخليــة رقــم ‪89400/19‬‬\n‫يف ‪1426/10/25‬هـ و أثب ــت الـتقـريـ ــر الكـيـميائـ ــي أحراز رقم (‪)158‬‬\n‫الص ــادر م ــن املركــز اإلق ــليمي ملراقبــة السم ــوم مب ــنطقة القص ــيم‬\n‫بـرق ــم (‪/323‬م س‪ )45/65/‬وتاريــخ ‪1434/2/6‬ه ـ ســلبية (‪ )3‬الثــاث‬\n‫حبــات ألشــباه القلويــدات املخــدرة ومشــتقات حمــض الباربيتوريــك و‬\n‫االمفيتامــن وقــد أســفر التحقيــق معــه عــن إتهامــه بترويــج (‪ )3‬ثــاث‬\n‫حبــات مــن حبــوب االمفيتامــن املنبهــة واحملظــورة عــن طريــق البيــع‬\n‫وتعاطيــه للحشــيش املخــدر‪ . ،‬واتهامــه ببيــع مــا أوهــم أنهــا حبــوب‬\n‫محظــورة احتيــا ًال مبقابــل وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬اعترافــه‬\n‫املــدون علــى الصفحــة رقــم (‪ )2.1‬مــن دفتــر التحقيــق لفــة رقــم (‪، )15‬‬\n‫‪ -2‬اعترافــه املــدون علــى الصفحــة رقــم (‪ )2.1‬مــن دفتــر التحقيــق لفــة‬\n‫رقــم (‪ -3 ، )36‬مــا جــاء يف محضــر الشــراء املســبق املنــوه عنــه واملــدون‬\n‫علــى الصفحــة رقــم (‪ )11‬لفــة رقــم (‪ -4 ، )1‬مــا جــاء يف محضــر الشــراء‬\n\n\n                                                                                    ‫‪378‬‬\n\f      ‫املســبق املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪ )11‬لفــة رقــم (‪، )9‬‬\n      ‫‪ -5‬مــا جــاء يف محضــر القبــض والتفتيــش املنــوه عنــه واملــدون علــى‬\n      ‫الصفحــة رقــم (‪ )12‬لفــة رقــم (‪ -6 ، )1‬مــا جــاء يف محضــر التعــرف‬\n      ‫املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪ )13‬لفــة رقــم (‪ -7 ، )9‬مــا جــاء‬\n      ‫يف التقريريــن الكيميائيــن املشــار إليهمــا لفــة رقــم (‪ ، )13.4‬وحيــث‬\n      ‫إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرعا ونظامـ ًا‬\n      ‫أطلــب إثبــات إدانتــه بترويــج (‪ )3‬ثــاث حبــات مــن حبــوب االمفيتامــن‬\n      ‫املنبهــة واحملظــورة عــن طريــق البيــع وتعاطيــه للحشــيش املخــدر‪،‬‬\n      ‫واحلكــم عليــه مبــا يلــي‪ -1 :‬الســجن و اجللــد و الغرامــة اســتناد ًا للفقــرة‬\n      ‫(‪ )1‬مــن املــادة (‪ -2 .)38‬املنــع مــن الســفر اســتناد ًا للفقــرة (‪ )1‬مــن املــادة‬\n      ‫(‪ -3.)56‬تطبيــق العقوبــة األشــد اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪.)62‬‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬وإثبــات إدانتــه ببيــع‬\n      ‫مــا أوهــم أنهــا حبــوب محظــورة احتيــا ًال مبقابــل واحلكــم عليــه بعقوبــة‬\n      ‫تعزيريــة و إلغــاء الشــريحة الهاتفيــة املســتخدمة يف اجلرمية رقــم (‪)............‬‬\n      ‫وعــدم صرفهــا لنفــس املشــترك وفقـ ًا لبرقيــة ســمو وزيــر الداخليــة رقــم‬\n      ‫(‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ ورد املبلــغ املفقــود اســتناد ًا لتعميــم‬\n      ‫ســمو وزيــر الداخليــة رقــم (‪ )65980/4/5/1‬وتاريــخ ‪1428/10/23‬هــ‪.‬‬\n      ‫وتشــديد العقوبــة عليــه لترويجــه حبــوب االمفيتامــن املنبهــة واحملظــورة‬\n      ‫ملــا لهــا مــن أثــر ســيء علــى الفــرد واملجتمــع أمني ـ ًا واجتماعي ـ ًا وصحي ـ ًا‬\n      ‫وفقـ ًا لتعميــم وزيــر الداخليــة رقــم (‪2/8346/5/1‬ش) يف ‪1427/2/8‬ه ـ‬\n      ‫ا مــا ذكــره املدعــي‬    ‫وبــاهلل التوفيــق وبســؤال املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫ا وقــد بعــت ثــاث حبــات‬      ‫العــام يف دعــواه كلــه صحيــح جملــة وتفصي ـ ً‬\n      ‫مــن احلبــوب املخــدرة وهــذه أول مــرة أقــوم فيهــا ببيــع احلبــوب املخــدرة‬\n\n\n‫‪379‬‬\n\f‫وأمــا املــرة الثانيــة فهــي حبــوب حساســية واجلــوال (‪ ).....‬عائــد لــي‬\n‫شــخصي ًا وأنــا تائــب ونــادم علــى مــا حصــل منــي وأمــا اســتعمال احلشــيش‬\n‫املخــدر فهــو غيــر صحيــح بهــذا أجــاب وبطلــب البينــة مــن املدعــي العــام‬\n‫علــى قيــام املدعــى عليــه بتعاطــي احلشــيش قــال بينتــي اعترافــه حتقيقـ ًا‬\n‫املــدون علــى صفحــة (‪ )2-1‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪)31‬‬\n‫وليــس لــدي بينــة ســواه وبعــرض هــذا اإلقــرار علــى املدعــى عليــه قــال‬\n‫مــا تضمنــه اإلقــرار مــن قيامــي باســتخدام احلشــيش املخــدر فهــذا غيــر‬\n‫صحيــح بهــذا أجــاب فبعــد الدعــوى واإلجابــة واإلطــاع علــى أوراق‬\n‫املعاملــة ومنهــا التقريريــن الكيميائيــن املشــار إليهمــا يف الدعــوى‬\n‫العامــة واملوافقــن ملــا فيهــا ولرجــوع املدعــى عليــه عــن إقــراره لــدى جهــة‬\n‫التحقيــق بتعاطــي احلشــيش املخــدر وليــس للمدعــي العــام بينــة ســوى‬\n‫إقــراره وإلقــرار املدعــى عليــه مبــا نســب إليــه دون مراوغــة ولصغــر ســنه‬\n                                                    ‫وخلــو ســجله مــن الســوابق‬\n‫وملــا جــاء يف املــادة الســتني مــن نظــام مكافحــة املخــدرات مــن أنــه‬\n‫للمحكمــة النــزول عــن احلــد األدنــى مــن الســجن إذا رأت يف القضيــة مــا‬\n‫يبعــث علــى االعتقــاد بــأن املتهــم لــن يعــود ملخالفــة أحــكام هــذا النظــام‬\n‫لذلــك كلــه فإنــه لــم يثبــت لــدي قيــام املدعــى عليــه بتعاطــي احلشــيش‬\n‫املخــدر وثبــت لــدي إدانتــه ببيــع عــدد (‪ )3‬ثــاث حبــات مــن حبــوب‬\n‫اإلمفيتامــن املنبهــة واحملظــورة بقصــد الترويــج وهــذا الترويــج للمــرة‬\n‫األولــى وإدانتــه ببيــع مــا أوهــم أنهــا حبــوب محظــورة احتيــا ًال مبقابــل‬\n‫وحكمــت بتعزيــره مبــا يلــي أو ًال ‪ :‬ســجنه ثــاث ســنوات مــن حــن إيداعه‬\n‫التوقيــف علــى ذمــة هــذه القضيــة ‪ ،‬ثانيـ ًا ‪ :‬جلــده ثالثمائــة جلــدة مفرقــة‬\n‫علــى ســت دفعــات يف مــكان عــام وأن يكــون بــن الدفعــة واألخــرى‬\n\n\n                                                                                       ‫‪380‬‬\n\f      ‫مــا ال يقــل عــن أســبوع ‪ ،‬ثالث ـ ًا ‪ :‬تغرميــه ألــف ريــال تــودع يف بيــت مــال‬\n      ‫املســلمني بحســاب إدارة مكافحــة املخــدرات ‪ ،‬رابعـ ًا ‪ :‬إلزامــه بإعــادة‬\n      ‫املبلــغ احلكومــي وقــدره (‪ )200‬مائتــن ريــال ملكافحــة املخــدرات ‪،‬‬\n      ‫خامس ـ ًا ‪ :‬إلغــاء شــريحة اجلــوال رقــم (‪ )...‬املضبوطــة مــن املدعــى عليــه‬\n      ‫وعــدم صرفهــا لنفــس املشــترك ‪ ،‬سادس ـ ًا ‪ :‬مصــادرة اجلــوال املســتخدم‬\n      ‫يف عمليــة الترويــج ‪ ،‬ســابع ًا ‪ :‬أخــذ التعهــد القــوي عليــه بعــدم العــودة ملثــل‬\n      ‫مــا نســب إليــه ‪ ،‬ثامن ـ ًا ‪ :‬منعــه مــن الســفر خلــارج اململكــة بعــد انتهــاء‬\n      ‫محكوميتــه مــدة ثــاث ســنوات هــذا مــا ظهــر لــي وبــه حكمــت واهلل‬\n      ‫أعلــم وأحكــم وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة وقــرر‬\n      ‫املدعــي العــام االعتــراض دون تقــدمي الئحــة اعتراضيــة فأجبتــه لطلبــه‬\n      ‫وأمــرت برفــع كامــل املعاملــة حملكمــة االســتئناف إلكمــال الزمهــا‬\n      ‫حســب املتبــع وبــاهلل التوفيــق ومت قفــل اجللســة الســاعة (‪ )11.00‬وصلــى‬\n      ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪ .‬حــرر يف‬\n                                                                        ‫‪1434/04/29‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n      ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة حائــل‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بحائــل‬\n      ‫املكلــف برقــم ‪34906011‬وتاريــخ ‪1434/5/4‬هــ؛ واملقيــدة لدينــا برقــم‬\n      ‫‪34906011‬وتاريــخ ‪1434/5/6‬هــ؛ املرفــق بهــا القــرار الشــرعي رقــم‬\n      ‫(‪ )34201368‬وتاريــخ ‪1434/4/29‬هــ؛ الصــادر مــن فضيلــة الشــيخ ‪/‬‬\n      ‫‪ ....‬القاضــي باحملكمــة اجلزائيــة بحائــل؛ اخلــاص بدعــوى املدعــي العــام‬\n      ‫ضــد ‪ .... /‬ســعودي اجلنســية ســجل مدنــي رقــم (‪)....‬؛ التهامــه بقضيــة‬\n      ‫ترويــج مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه علــى املدعــى عليــه‬\n\n\n‫‪381‬‬\n\f‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر علــى النحــو املفصــل فيــه؛‬\n‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة ‪:‬جــرت املصادقــة علــى‬\n‫مــا حكــم بــه فضيلتــه علــى املدعــى عليــه مــن تعزيــر مــع تنبيــه فضيلتــه‬\n‫أن ختــم صــورة الضبــط بصــورة طبــق األصــل بــدون توقيــع ال يكفــي‬\n‫ملالحظــة ذلــك مســتقبالً‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل وســلم علــى نبينــا‬\n                                         ‫محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n\n\n\n\n                                                                                    ‫‪382‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":374,"source_page_end":382,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"01d45a0049b325da86ddb65474a07d93012d9cfb34ac89f32e831019bc8db59d","normalized_text_hash":"4f5f3353c00097675b130dd05c8c91e9e64518282a57f7eac141ff62fadd1e10","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p374-34201368"},{"id":"b082a8e2-4739-5e4d-b58f-b4e75695edbf","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج حبوب محظورة -حيازة احلبوب احملظورة بقصد التعاطي -تعزير بالسجن واجللد -تعزير باملنع من السفر -تعزير بالغرامة -تعزير باملصادرة -إسقاط شريحة جوال.","document_number":"34194415","case_number":"34176361","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/22","year":"1434","subject":"مخدرات -ترويج حبوب محظورة -حيازة احلبوب احملظورة بقصد التعاطي -تعزير بالسجن واجللد -تعزير باملنع من السفر -تعزير بالغرامة -تعزير باملصادرة -إسقاط شريحة جوال.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34194415 :‬تاريخه ‪1434/04/22 :‬هـ‬\n                          ‫رقم الدعوى ‪34176361 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34317446‬تاريخه‪1434/09/13:‬هـ‬\n\n\n        ‫مخــدرات ‪ -‬ترويــج حبــوب محظــورة ‪ -‬حيــازة احلبــوب احملظــورة بقصــد‬\n        ‫التعاطــي ‪ -‬تعزيــر بالســجن واجللــد ‪ -‬تعزيــر باملنــع مــن الســفر ‪ -‬تعزيــر‬\n                          ‫بالغرامــة ‪ -‬تعزيــر باملصــادرة ‪ -‬إســقاط شــريحة جــوال‪.‬‬\n\n\n\n\n            ‫‪-1‬املادة ‪ 56‬واملادة ‪ 62‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n                 ‫‪ -2‬تعميم سمو وزير الداخلية رقم ‪ 65980‬يف ‪1428/10/23‬هـ‬\n\n\n\n\n        ‫ادعــى املدعــي العــام ضــد املدعــى عليــه ترويــج احلبــوب احملظــورة بقصــد‬\n        ‫االجتــار والترويــج وحيازتهــا بقصــد الترويــج والتعاطــي وتعاطيــه لهــا‪،‬‬\n        ‫وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة‬\n        ‫الســجن واجللــد والغرامــة املاليــة واملنــع مــن الســفر ومصــادرة الهاتــف‬\n        ‫اجلــوال وإلغــاء شــريحته املســتخدمة يف اجلرميــة وإلــزام املدعــى عليــه بــرد‬\n        ‫املبلــغ املرقــم ‪ ،‬حيــث إنــه مت القبــض علــى املدعــى عليــه بعــد إخباريــة‬\n        ‫مفادهــا أن املدعــى عليــه يقــوم بترويــج احلبــوب احملظــورة ومت التنســيق‬\n        ‫مــع أحــد املصــادر الســرية لإليقــاع بــه متلبسـ ًا ومت ذلــك وتقابــل املصــدر‬\n        ‫مــع املدعــى عليــه يف املوقــع احملــدد ومت القبــض علــى املدعــى عليــه بعــد‬\n        ‫عمليــة التســليم واالســتالم وأقــر املدعــى عليــه بالدعــوى ‪ ،‬بنــاء علــى‬\n\n‫‪383‬‬\n\f‫مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد‬\n‫والغرامــة واملنــع مــن الســفر ومصــادرة الهاتــف اجلــوال وإســقاط شــريحته‬\n‫املســتخدمان يف اجلرميــة و رد املبلــغ احلكومــي وصــدق احلكــم مــن‬\n                                                  ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 34176361‬وتاريــخ ‪ 1434/04/16‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34940643‬وتاريــخ ‪ 1434/04/16‬ه ـ ففــي يــوم‬\n‫األحــد املوافــق‪ 1434/04/21‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 15‬‬\n‫وفيهــا حضــر املدعــي العــام و أدعــي علــى ‪ ....../‬البالــغ مــن العمــر(‪)24‬‬\n‫عام ـ ًا ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬حيــث أنــه‬\n‫بتاريــخ ‪1434/3/10‬ه ـ قبــض علــى املذكــور مــن قبــل إحــدى فــرق‬\n‫ادارة العميــات التابعــة إلدارة مكافحــة املخــدرات مبنطقــة الريــاض‬\n‫ـاء علــى املعلومــات الــواردة لهــم مــن أحــد مصادرهــم الســرية عــن قيــام‬\n                                                                             ‫بنـ ً‬\n‫املذكــور بترويــج احلبــوب احملظــورة ويســتخدم هاتفــه اجلــوال رقــم( ‪)...‬‬\n‫واســتعد املصــدر لالطاحــه بــه باجلــرم املشــهود عليــه مت االيعــاز للمصــدر‬\n‫لالتصــال علــى الهاتــف جــوال املــروج وطلــب منــه حبوبـ ًا محظــوره بقيمــة‬\n‫(‪ )200‬مائتــي ريــال فوافــق املــروج املذكــور ومت تكليــف احــد افــراد‬\n‫الفرقــه ملرافقــة املصــدر ليكــون شــاهد علــى عمليــة الترويــج ومت تزويــد‬\n‫املصــدر باملبلــغ املرقــم وقــدرة (‪ )200‬مائتــي ريــال وحــدد املــروج مــكان‬\n‫االســتالم والتســليم وباإلنتقــال إلــى املوقــع مت مقابلــة املــروج وركــب يف‬\n\n                                                                                     ‫‪384‬‬\n\f      ‫ســيارة املصــدر والفــرد املكلــف وحضــرت ســيارة لــم تتمكــن الفرقــه‬\n      ‫مــن تســجيل رقــم لوحتهــا بســبب الظــام واســتلم املــروج املذكــور املبلــغ‬\n      ‫املرقــم قبــل نزولــه واجتــه إلــى الســياره واحتــك بصاحبهــا ثــم عــاد وســلم‬\n      ‫للمصــدر ماعــدده (‪ )7‬ســبع حبــات حتمــل عالمــة الكبتاجــون احملظــور‬\n      ‫وبعــد متــام العمليــه مت ضبطــه وبتفتيشــه عثــر علــى ماعــدده (‪ )1‬حبــه‬\n      ‫حتمــل عالمــة الكبتاجــون احملظــور يف جيــب بنطالــه األميــن ولــم يعثــر‬\n      ‫معــه علــى املبلــغ املرقــم ‪.‬وقد أثبت التقرير الكيميائي الشــرعي الصادر‬\n      ‫مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بالريــاض‬\n      ‫املرفــق رقــم (‪/2982‬س) لعــام ‪1434‬ه ـ احتــواء احلبــوب املروجــه واحلبــه‬\n      ‫املضبوطــه لالمفيتامــن وهــو مــن املــواد املنبهــه واملدرجــة باجلــدول رقــم‬\n      ‫(‪ )2‬فئــة (ب) مــن نظــام مكافحــه املخــدرات واملؤثرات العقلية ‪.‬وبســماع‬\n      ‫أقوالــه األوليــة واســتجوابه اعتــرف بالترويــج واعتــرف بضبــط احلبــه‬\n      ‫احملظــوره معــه بقصــد التعاطــي واعتــرف بتعاطــي احلبــوب احملظــوره‬\n      ‫وأنــه حصــل علــى احلبــوب املخــدره مــن املدعــو ‪ .... /‬حيــث أنــه اتصل عليه‬\n      ‫لطلــب احلبــوب احملظــوره فأعطــاه رقــم املدعــو ‪ ... /‬وهــو الــذي احضــر‬\n      ‫احلبــوب احملظــوره وقــد أســفرت إجــراءات التحقيــق عــن توجيــه االتهــام‬\n      ‫لــ‪ .... /‬ببيــع مــا عــدده (‪ )7‬ســبع حبــات مــن حبــوب االمفيتامــن املنبــه‬\n      ‫احملظــورة بقصــد األجتــار والترويــج وحيــازة ماعــدده (‪ )1‬حبــه واحــده‬\n      ‫مــن حبــوب االمفيتامــن املنبــه احملظــورة بقصــد الترويــج و التعاطــي‬\n      ‫وتعاطيــه احلبــوب احملظــوره املجــرم مبوجــب املــادة (الثالثــة) مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n            ‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ‪.‬وذلــك لألدلــة والقرائــن التاليــة ‪-:‬‬\n                                                                ‫‪ -1‬ماتضمنه اعترافه‪.‬‬\n\n\n‫‪385‬‬\n\f                                                     ‫‪ -2‬ما تضمنه محضر القبض) ‪.‬‬\n‫‪ -3‬مــا تضمنــه التقريــر الكيميائــي وببحــث ســوابقه العشــرية لــم عثــر‬\n‫علــى ســابقه مســجله بحقــه حتــى تاريخــه ‪.‬وحيــث إن مــا أقــدم عليــه‬\n‫املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا ‪ ،‬لــذا اطلــب إثبــات‬\n                         ‫إدانتــه مبــا أســند إليهمــا واحلكــم عليهمــا باآلتــي‪-:‬‬\n‫‪-1‬بعقوبــة الســجن واجللــد والغرامــه املاليــة بحقــة وفقـ ًا للفقــرة (األولــى)‬\n‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثرات العقلية املشــار‬\n‫إليــه وتشــديد العقوبــه عليــه وفقـ ًا للفقــرة (ج) البنــد ثانيـ ًا مــن نفــس املــادة‬\n         ‫وإعمــال الفقــره ( االولــى) مــن املــاده ( ‪ )62‬مــن نفــس النظــام بحقــه‪.‬‬\n‫‪ -2‬منعــه مــن الســفر إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة‬\n‫ســجنه وفقـ ًا للفقــرة (االولــى) مــن املــادة (‪ )56‬مــن النظــام املشــار إليــه ‪.‬‬\n‫‪-3‬مصــادرة الهاتــف النقــال مــن نــوع ‪ .....‬املســتخدم يف اجلرميــه اســتناد ًا‬\n‫للفقــرة (األولــى) مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات‬\n                                                                  ‫واملؤثــرات العقليــة ‪.‬‬\n‫‪-4‬إلغــاء الشــريحة املســتخدمة يف اجلرميــة ذات الرقــم (‪ )....‬وعدم صرفها‬\n‫لنفــس املشــترك يف حــال صــدور احلكــم باإللغــاء وإبــاغ الشــركة‬\n                                       ‫م ـص ـ ــدرة الشــري ـح ــة بـذل ــك استن ــاد ًا إلى‬\n         ‫تعميم سمو وزير الداخلية رقم (‪ )9798‬وتاريخ ‪ 9‬ــ‪1428/2/10‬هـ‪.‬‬\n‫‪-5‬إلــزام املذكــور بــرد املبلــغ املرقــم وقــدره ( ‪ )200‬مائتــي ريــال اســتناد ًا‬\n‫لبرقيــة ســمو ولــي العهــد وزيــر الداخليــة رقــم (‪ )65980‬وتاريــخ ‪-22‬‬\n                                                                     ‫‪1428/10/23‬ه ـ ‪.‬‬\n‫وبعــرض ذلــك علــى املدعــى عليــه اجــاب مــا ذكــره املدعــي العــام صحيح‬\n‫مــن ناحيــة ترويــج ســبع حبــات محظورة بالبيع وحيــازة حبة واحدة لقصد‬\n\n\n                                                                                               ‫‪386‬‬\n\f      ‫االســتعمال وقــرر انــه تائــب ونــادم علــى فعلــه كمــا قــرر انــه يســتعمل‬\n      ‫احلبــوب احملظــورة فبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــه وحيــث‬\n      ‫اعتــرف املدعــى عليــه ببيــع ســبع حبــات محظــورة وحيــازة حبــة واحــدة‬\n      ‫لقصــد االســتعمال وحيــث جــرى االطــاع علــى التقريــر الكيمــاوي رقــم‬\n      ‫‪/2982‬س لعــام ‪1434‬ه ـ املتضمــن ايجابيــة العينــة للحبــوب احملظــورة‬\n      ‫وحيــث جــرى التأمــل لــذا قــررت مــا يلــي اوال ثبــت لــدي ترويــج املدعــى‬\n      ‫عليــه لســبع حبــات محظــورة عــن طريــق البيــع وحكمــت عليــه للمــادة‬\n      ‫‪ 38‬بســجنه ســنة ونصــف اعتبــارا مــن توقيفــه وجلــده مائتــي جلــده مفرقة‬\n      ‫علــى اربــع فتــرات بينهــم عشــرة ايــام وبغرامــة ماليــه قدرهــا عشــرة االف‬\n      ‫ريــال تؤخــذ منــه وتــودع بيــت املــال ثانيــا حكمــت مبنعــه مــن الســفر‬\n      ‫للمــادة ‪ 56‬بعــد انتهــاء محكوميتــه ثالثــا ثبــت لــدي حيازتــه حلبــة واحــدة‬\n      ‫لقصــد االســتعمال وتكــون عقوبتــه داخلــة يف اوال اســتنادا للمــادة ‪62‬‬\n      ‫مــن النظــام رابعــا حكمــت عليــه بــرد مبلــغ مائتــي ريــال اســتنادا لبرقيــة‬\n      ‫ســمو ولــي العهــد ووزيــر الداخيــه رقــم ‪ 65980‬يف ‪1428/10/23-22‬ه ـ‬\n      ‫خامســا حكمــت مبصــادرة الهاتــف اعــاه نــوع نوكيــا اســتنادا للمــادة‬\n      ‫‪ 56‬مــن النظــام سادســا حكمــت بالغــاء الشــريحه املســتخدمه رقــم ‪.....‬‬\n      ‫وعــدم صرفهــا للمشــترك اســتنادا لتعميــم وزيــر الداخليــه رقــم ‪9798‬‬\n      ‫يف ‪1428/2/-10-9‬ه ـ وبعرضــه عليــه قنــع بــه وقنــع بــه املدعــي العــام‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                   ‫وســلم ‪ .‬حــرر يف ‪ 1434/04/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافــق ‪1434/4/22‬ه ـ حضــر‬\n      ‫املدعــي العــام وقــرر عــدم قناعتــه باحلكــم وطلــب التمييــز بــدون الئحــه‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n\n\n‫‪387‬‬\n\f                                          ‫وســلم ‪ .‬حــرر يف ‪ 1434/04/22‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء املوافــق ‪1434/8/9‬ه ـ وردت‬\n‫املعاملــة مــن محكمــة االســتئناف وبطيهــا القــرار رقــم ‪ 34249949‬يف‬\n‫‪1434/6/24‬ه ـ ونــص احلاجــه منــه ان فضيلتــه ناظــر القضيــه اثبــت‬\n‫ترويــج املدعــى عليــه لســبع حبــات عــن طريــق البيــع وحكــم بســجنه‬\n‫ســنة ونصــف مبوجــب املــادة ‪ 38‬مــن نظــام مكافحــة املخــدرات واملــادة‬\n‫املذكــورة اقــل عقوبــة خمــس ســنوات ولــم يبــن ناظــر القضيــة ســبب‬\n‫النــزول عــن احلــد االدنــى وحكــم فضيلتــه ناظــر القضيــة مبنــع املدعــى‬\n‫عليــه مــن الســفر ولــم يبــن مقــدراه واجيــب اصحــاب الفضيلــة ان النــزول‬\n‫بســبب قــل الكميــة وصغرهــا وامــا املنــع مــن الســفر فلمــدة ســنتني وبــه‬\n‫حكمــت وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/09‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫األولــى مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن رئيــس‬\n‫احملكمــة اجلزائيــة بالريــاض املكلــف برقــم ‪ 341842596‬وتاريــخ‬\n‫‪1434/8/13‬ه ـ واملرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ‪ /‬د‪ ........‬برقــم ‪ 34194415‬وتاريــخ ‪1434/4/22‬ه ـ‬\n‫واخلــاص بدعــوى املدعــي العــام ضــد ‪ ، ............ /‬وموضوعهــا مخــدرات‬\n‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وبعــد التدقيــق يف‬\n‫إجابــة فضيلــة ناظــر القضيــة وفقــه اهلل علــى قــرار محكمــة االســتئناف‬\n‫الســابق تقــرر املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر لعــدم موجــب‬\n‫املالحظــة‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلى آله وصحبه‬\n                                                                         ‫وســلم‪.‬‬\n\n\n                                                                                   ‫‪388‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":383,"source_page_end":388,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a5cdd333a2acbe32d8a675c093dd3a1b5c8f04803fbe1e014edc7273d700da04","normalized_text_hash":"4bf181efa41798bbaa472211b97e45cc84aa03c14a1e75a62319f17a58632fe6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p383-34194415"},{"id":"f6ba3670-4a99-5d9a-bb7e-e2b973918121","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -حيازة احلبوب احملظورة بقصد التعاطي -اعتراف حتقيق ا -ثبوت إدانه -رد دعوى -تعزير بالسجن واجللد والغرامة -تعزير باملصادرة -إلغاء شريحة جوال املواد 60 - 53 - 56 - 38من نظام مكافحة املخدرات واملؤثرات العقلية","document_number":"34204202","case_number":"34177257","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/4","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -حيازة احلبوب احملظورة بقصد التعاطي -اعتراف حتقيق ا -ثبوت إدانه -رد دعوى -تعزير بالسجن واجللد والغرامة -تعزير باملصادرة -إلغاء شريحة جوال املواد 60 - 53 - 56 - 38من نظام مكافحة املخدرات واملؤثرات العقلية","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34204202:‬تاريخه ‪1434/5/4 :‬هـ‬\n                       ‫رقم الدعوى ‪34177257 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34263965‬تاريخه‪1434/09/15:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬حيــازة احلبــوب احملظــورة‬\n      ‫بقصــد التعاطــي ‪ -‬اعتــراف حتقيقـ ًا ‪ -‬ثبــوت إدانــه ‪ -‬رد دعــوى ‪ -‬تعزيــر‬\n      ‫بالســجن واجللــد والغرامــة ‪ -‬تعزيــر باملصــادرة ‪ -‬إلغــاء شــريحة جــوال‬\n\n\n\n\n      ‫املواد ‪ 60 - 53 - 56 - 38‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج احلبــوب احملظــورة‬\n      ‫وتعاطيــه لهــا وطلــب املدعــي العــام إثبــات إدانتــه مبــا أســند إليــه‬\n      ‫واحلكــم عليــه بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة‬\n      ‫الســيارة واجلــوال املســتخدمان يف اجلرميــة وإلغــاء الشــريحة املســتخدمة‬\n      ‫يف اجلرميــة حيــث إنــه قــد وردت معلومــات مفادهــا أن هنــاك شــخص ًا‬\n      ‫يقــوم بترويــج احلبــوب احملظــورة فتــم التنســيق مــع املصــدر لالتفــاق‬\n      ‫معــه علــى شــراء احلبــوب احملظــورة ومت حتديــد املوعــد وحضــر املتهــم‬\n      ‫يف املــكان احملــدد ومتــت مشــاهدة االســتالم والتســليم وأقــر املدعــى‬\n      ‫عليــه بالدعــوى‪ ،‬ملــا كان مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى‬\n      ‫عليــه بالســجن واجللــد و املنــع مــن الســفر والغرامــة ومصــادرة اجلــوال‪،‬‬\n      ‫وإلغــاء شــريحته وعــدم ثبــوت طلــب املدعــي العــام مبصــادرة الســيارة‬\n\n‫‪389‬‬\n\f   ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n                                          ‫املســتخدمة يف اجلرميــة ُ‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .................‬القاضــي يف احملكمــة‬\n‫اجلزائيــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمة اجلزائية بالرياض برقم ‪ 34177257‬وتاريخ ‪1434/04/17‬هـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 34946693‬وتاريــخ ‪ 1434/04/17‬ه ـ ففــي‬\n‫يوم األربعاء املوافق ‪1434/04/24‬هـ افتتحت اجللســة الســاعة ‪08 : 45‬‬\n‫وفيها حضر املدعي العام ‪....‬وقرر قائال أدعي على ‪ ....................‬البالغ‬\n‫مــن العمــر(‪ )..‬عامـ ًا ســعودي اجلنســية مبوجــب بطاقة الهويــة الوطنية رقم‬\n‫(‪ )................‬أعــزب ‪ ،‬متعلــم ‪ ،‬عاطــل ‪ -‬يقيــم يف مدينــة الريــاض أوقــف‬\n‫بتاريــخ ‪1434/3/1‬ه ـ وأحيــل إلى شــعبة ســجن امللــز مبوجب أمر اإلحالة‬\n‫ومتديــد التوقيــف رقــم (ه ـ را‪ )......../5/‬وتاريــخ ‪1434/3/7‬ه ـ اســتناد ًا‬\n‫للقــرار الــوزاري رقــم (‪ )1900‬وتاريخ‪1428/7/9‬ه ـ املبنــي علــى املــادة‬\n‫(‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة ‪ .‬حيــث أنــه بتاريــخ ‪1434/3/1‬ه ـ‬\n‫قبــض علــى املذكــور مــن قبــل إحــدى فــرق املســاندة القابضــة للمديريــة‬\n‫ـاء علــى املعلومــات الــواردة لهــم مــن أحــد‬‫العامــه ملكافحــة املخــدرات بنـ ً‬\n‫مصادرهــم الســرية عــن وجــود شــخص يقــوم بترويــج احلبــوب احملظــورة‬\n‫ومت متكــن املصــدر مــن االتصــال علــى املــروج علــى هاتفــه جــوال رقــم‬\n‫( ‪ )...................‬وطلــب منــه حبوبـ ًا محظــوره بقيمــة (‪ )650‬ســتمائة مائــه‬\n‫وخمســن ريال فوافق املروج ومت االتفاق على موعد االســتالم والتســليم‬\n‫وعليــه مت تزويــد املصــدر باملبلــغ املرقــم (‪ )650‬ســت مائــه وخمســون ريــال‬\n‫وعليــه مت االنتقــال مــع املصــدر ويرافقــه احــد افــراد الفرقــه الـ ــى امل ــوقع‬\n\n                                                                                         ‫‪390‬‬\n\f      ‫امل ـتـفـق عليه وبـعـد خـمــس دقـائـق ح ـضـرت سـيـارة مـن نـوع ‪ .....‬تـحـمـل‬\n      ‫اللــوح ــة(؟؟؟‪ )...-‬وقــام مبقابلــة املصــدر والفــرد املرافــق واحتــك بهمــا‬\n      ‫وســلمهما شــئ وبعدهــا تفرقــا ومبتابعــة الســيارة ‪ ....‬وعنــد توقفهــا عنــد‬\n      ‫أحــد احملــات التجاريــة مت األقفــال عليه وحــاول الهرب فتم أطالق عيار‬\n      ‫نــاري علــى اإلطــار اخللفــي األميــن ومت القبــض عليــه وأتضــح انــه املذكــور‬\n      ‫وبتفتيشــه شــخصي ًا عثــر علــى املبلــغ املرقــم يف جيبــه وبتفتيــش الســياره‬\n      ‫عثــر علــى ماعــدده (‪ )4‬أربــع حبــات حتمــل عالمــة الكبتاجــون احملظــور‬\n      ‫كمــا عثــر علــى هاتــف جــوال مــن نــوع ‪ .....‬وهــو اجلــوال املســتخدم يف‬\n      ‫اجلرميــه ويحمــل الرقــم املصنعــي (‪ )......................‬وعنــد مقابلــة املصــدر‬\n      ‫والفــرد املرافــق ســلمهما مــا عــدده (‪ )20‬عشــرون حبــه حتمــل عالمــة‬\n                                      ‫الكبتاجــون احملظــور وهــي الكميــة املشــتراه ‪.‬‬\n      ‫وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة‬\n      ‫الســموم والكيميــاء الطبيــة الشــرعية بالريــاض املرفــق رقــم (‪2700‬‬\n      ‫‪/‬س) لعــام ‪1434‬ه ـ احتــواء احلبــوب املضبوطــه وعينــة احلبــوب املروجــه‬\n      ‫لالمفيتامــن وهــو مــن املــواد املنبهــه واملدرجــة باجلــدول رقــم (‪ )2‬فئــة (ب)‬\n                               ‫مــن نظــام مكافحــه املخــدرات واملؤثــرات العقليــة ‪.‬‬\n      ‫وبســماع أقوالــه األوليــه اعتــرف بحيــازة احلبــوب احملظــورة يف ســيارته‬\n      ‫وعددهــا (‪ )4‬أربــع حبــات بقصــد التعاطــي وبأســتجوابه أعتــرف أن‬\n      ‫الهاتــف اجلــوال الــذي يحمــل رقــم الشــريحة (‪ )...................‬عائــد لــه‬\n      ‫واعتــرف بتعاطــي احلبــوب احملظــوره وأن املبلــغ املضبــوط معــه وقــدره‬\n      ‫(‪ )2100‬ألفــان ريــال مصــدره مــن حافــز ومصروفــه الشــخصي (جــرى‬\n      ‫تســليمه املبلــغ املالــي اســتناد ًا الــى املادتني(‪ )88-86‬مــن نظام اإلجراءات‬\n      ‫ا للمصــادره مبوجــب اخلطــاب رقــم (‪)34968‬‬            ‫اجلزائيــة كونــه ليــس محـ ً‬\n\n\n‫‪391‬‬\n\f                                                              ‫وتاريــخ ‪1434/4/7‬هـ‬\n‫وقد أسفرت إجراءات التحقيق عن توجيه االتهام لـ‪ .................. /‬ببيع‬\n‫مــا عــدده (‪ )20‬عشــرون حبــه مــن حبــوب االمفيتامــن املنبــه احملظــورة‬\n‫بقصــد اإلجتــار و الترويــج وحيازتــه ماعــدده (‪ )4‬أربــع حبــات مــن نفــس‬\n‫النــوع بقصــد الترويــج والتعاطــي وتعاطيــه احلبــوب احملظــوره املجــرم‬\n‫مبوجــب املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫وتســتره علــى مصــدر مــا مت ضبطــه معــه ومــا مت ترويجــه املعاقــب علــى‬\n                                                                       ‫ذلــك شــرعا ‪.‬‬\n                                                 ‫وذلك لألدلة والقرائن التالية ‪-:‬‬\n‫‪ -1‬اعترافه حتقيق ًا أن اجلوال الذي يحمل رقم الشريحة (‪).....................‬‬\n                                                                            ‫عائــد له ‪.‬‬\n             ‫‪ -2‬ما تضمنه محضر القبض املنوه عنه املرفق لفه رقم ( ) ‪.‬‬\n‫‪ -3‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــه‬\n                                                                      ‫رقــم (‪. )........‬‬\n                                                   ‫‪-4‬ضبط املبلغ املرقم بحوزته ‪.‬‬\n‫وببحــث ســوابقه العشــرية عثــر لــه علــى ســابقة ســرقة جــواالت مســجله‬\n                                                            ‫يف حقــه حتــى تاريخــه ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫ونظامـ ًا ‪ ،‬لــذا اطلــب إثبــات إدانتــه مبــا أســند إليهمــا واحلكــم عليهمــا‬\n                                                                             ‫باآلتــي‪-:‬‬\n‫‪-1‬بعقوبــة الســجن واجللــد والغرامــه املاليــة بحقــة وفقـ ًا للفقــرة (األولــى)‬\n‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثرات العقلية املشــار‬\n\n\n                                                                                           ‫‪392‬‬\n\f      ‫إليــه وتشــديد العقوبــه عليــه وفقـ ًا للفقــرة (ج) البنــد ثانيـ ًا مــن نفــس املــادة‬\n      ‫واعمــال الفقــره (األولــى ) مــن املــادة (‪ )62‬مــن نفــس النظــام بحقــه لقــاء‬\n                                                                                ‫مــا أســند إليــه‪.‬‬\n      ‫‪ -2‬منعــه مــن الســفر إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة‬\n      ‫ســجنه وفقـ ًا للفقــرة (الثانيــة) مــن املــادة (‪ )56‬مــن النظــام املشــار إليــه ‪.‬‬\n      ‫‪-3‬مصــادرة الســياره مــن نــوع ( ‪ ) .....‬حتمــل اللوحــه رقــم (‪).......‬‬\n      ‫املســتخدمه يف اجلرميــه اســتناد ًا للفقــره ( األولــى ) مــن املــادة (‪ )53‬مــن‬\n                                                                              ‫نفــس النظــام ‪.‬‬\n      ‫‪-4‬مصــادرة الهاتــف النقــال مــن نــوع ‪ ......‬املســتخدم يف اجلرميــه حامــل‬\n      ‫الرقــم املصنعــي (‪ ).......................‬اســتناد ًا للفقــرة (األولــى) مــن املــادة‬\n                         ‫(‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n      ‫‪-5‬إلغــاء الشــريحة املســتخدمة يف اجلرميــة ذات الرقــم (‪)..................‬‬\n      ‫وعــدم صرفهــا لنفــس املشــترك يف حــال صــدور احلكــم باإللغــاء وإبــاغ‬\n      ‫الشــركة مصــدرة الشــريحة بذلــك اســتناد ًا إلــى تعميــم ســمو وزيــر‬\n                                  ‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪ 9‬ــ‪1428/2/10‬هــ‪.‬‬\n      ‫‪-6‬بعقوبــة تعزيريــة بحقــه لقــاء تســتره علــى مصــدر مــا ضبــط ومــامت‬\n      ‫ترويجــه ‪ .‬وبــاهلل التوفيــق وبســؤال املدعــى عليــه أجــاب بقولــه مــا ذكــره‬\n      ‫املدعــي العــام صحيــح جملــة وتفصيــا وقــد قمــت ببيــع عشــرين حبــة‬\n      ‫وهــذه احلبــوب هــي لــي الســتخدامها واتصــل علي متعاون وطلب شــراؤها‬\n      ‫وقمــت ببيــع عشــرين حبــة حلاجتــي للمــال وبقــي معــي اربــع حبــات وهــي‬\n      ‫للتعاطــي وقــد تعاطيــت احلبــوب احملظــورة قبــل القبــض علــي بخمســة‬\n      ‫عشــر يومــا وعلــي ســابقة ســرقة جــواالت فقــط وقــد اشــتريت احلبــوب‬\n      ‫احملظــورة مــن شــخص اثيوبــي يف حــي ‪ ............‬أمــا الســيارة فهــي ليســت‬\n\n\n‫‪393‬‬\n\f‫لــي وإمنــا لعمــي ولــدي البينــة هــذه اجابتــي لــذا رفعــت اجللســة حلضــور بينــة‬\n‫املدعــى عليــه ألن الســيارة ليســت ملــكا لــه وعليــه جــرى التوقيــع وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                    ‫حــرر يف ‪ 1434/04/24‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض ففــي يــوم اإلثنــن املوافــق‪ 1434/04/29‬ه ـ افتتحــت اجللســة‬\n‫الســاعة العاشــرة صباحــا وفيهــا حضــر ســعودي بالســجل املدنــي رقــم‬\n‫‪..................‬وكيــا عــن بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n‫بجنــوب الريــاض برقــم ‪ 34522524‬يف ‪ 1434/4/27‬واملخــول فيهــا‬\n‫باملرافقــة واملدافعــة وســماع الدعــاوى والــرد عليهــا واإلقــرار واإلنــكار‬\n‫وقــرر بقولــه بــأن الســيارة التــي قبضــت مــع املدعــى عليــه أنهــا ملوكلــي‬\n‫وليســت لــه وقــد أخذهــا يف ذلــك اليــوم الــذي قبــض عليــه فيــه عاريــة‬\n‫ليذهــب بهــا إلــى مــكان ثــم يعيدهــا وال زالــت مســجلة باســم موكلــي‬\n‫وأحضــر معــه أصــل اإلســتمارة وبياناتهــا كالتالــي اســم املالــك بالهويــة‬\n‫رقــم ‪ ..................‬رقــم الهيــكل ‪ ..............‬حتمــل اللوحــة رقــم (‪)........‬‬\n‫طــراز املركبــة ‪ .......‬اللــون ذهبــي ســنة الصنــع ‪2001‬م وقــد جــرى‬\n‫االطــاع عليهــا وإرفــاق صــورة منهــا باملعاملــة وعليــه جــرى التوقيــع وباهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫حــرر يف ‪ 1434/04/29‬ه ـ ويف يــوم األربعــاء املوافــق ‪ 1434/05/01‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11 : 45‬وفيهــا حضــر املدعــي العــام واملدعــى‬\n‫عليــه وبعــرض بينــة املدعــى عليــه علــى أن الســيارة ليســت ملــكا لــه علــى‬\n‫املدعــي العــام أجــاب بقولــه ليــس لــدي ســوى مــا يف املعاملــة وبتصفــح‬\n‫املعاملــة لــم أجــد فيهــا مــا يثبــت أن الســيارة ملــكا للمدعــى عليــه ولــم‬\n\n\n                                                                                          ‫‪394‬‬\n\f      ‫يقــر املدعــى عليــه أن الســيارة ملــكا لــه فبنــاء علــى ما تقدم مــن الدعوى‬\n      ‫واالجابــة وحيــث صــادق املدعــى عليــه علــى قيامــه ببيــع ما عدده عشــرين‬\n      ‫حبــة مــن حبــوب الكبتاجــون وتعاطيــه لنوعهــا وحيازتــه ألربــع حبــات من‬\n      ‫نفــس النوعيــة للتعاطــي وحيــث جــرى االطــاع علــى محضــر التحقيــق‬\n      ‫وعلــى التقريــر الكيميائــي واذا هــو كمــا ذكــره املدعــي العــام وحيــث‬\n      ‫ان املدعــى عليــه أنكــر ان الســيارة املســتخدمة يف اجلرميــة انهــا لــه‬\n      ‫واحضــر مــا يثبــت ذلــك وأنهــا ملــك لعمــه واملرفــق صــورة وثيقــة امللكيــة‬\n      ‫باملعاملــة وحيــث أن املدعــى عليــه ليــس عليــه ســابقة مماثلــة جلرميتــه وإمنــا‬\n      ‫ســابقته يف ســرقة جــواالت لــذا ثبــت لــدي قيــام املدعــى عليــه ببيــع مــا‬\n      ‫عــدده عشــرون حبــة مــن حبــوب الكبتاجــون بقصــد االجتــار والترويــج‬\n      ‫وحيازتــه لعــدد أربــع حبــات مــن حبــوب الكبتاجــون بقصــد التعاطــي‬\n      ‫وتعاطيــه لنوعهــا وتســتره علــى مصــدر مــا ضبــط وحكمــت عليــه باالتــي‬\n      ‫أوال ســجنه ثــاث ســنوات تبــدأ مــن تاريــخ دخولــه الســجن يف هــذه‬\n      ‫القضيــة وبغرامــة ماليــة قدرهــا ثالثــة االف ريــال وجلــده ثالثمائــة جلــدة‬\n      ‫مفرقــة علــى دفعــات كل دفعــة خمســون جلــدة بــن الدفعــة واالخــرى‬\n      ‫عشــرة ايــام داخــا يف هــذا اجللــد تســتره علــى مصــدر مــا ضبــط وذلــك‬\n      ‫بنــاء علــى املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات وقــد نزلــت عــن‬\n      ‫العقوبــة املقــررة بهــذه املــادة لقلــة الكميــة ولعــدم وجــود ســوابق عليــه‬\n      ‫مماثلــة وذلــك بنــاء علــى املــادة (‪ )60‬مــن النظــام نفســه ثانيــا منعــه مــن‬\n      ‫الســفر ملــدة ثــاث ســنوات تبــدأ بعــد تنفيــذه عقوبــة الســجن بنــاء علــى‬\n      ‫املــادة رقــم (‪ )56‬مــن النظــام نفســه ثالثــا مصــادرة هاتفــه اجلــوال مــن نــوع‬\n      ‫‪ ......‬يف اجلرميــة رقمــه املصنعــي (‪ )............‬وإلغــاء الشــريحة املســتخدمة‬\n      ‫يف اجلرميــة ذات الرقــم وذلــك بنــاء علــى املــادة رقــم (‪ )53‬مــن النظــام‬\n\n\n‫‪395‬‬\n\f‫نفســه رابعــا جلــده ثمانيــة وســبعون جلــدة دفعــة واحــدة لتعاطيــه احلبــوب‬\n‫احملظــورة ويكــون بينهــا وبــن اجللــد التعزيــري يف أوال خمســة عشــر‬\n‫يومــا خامســا لــم يثبــت لــدي مــا يطالــب بــه املدعــي العــام مــن مصــادرة‬\n‫الســيارة املســتخدمة يف اجلرميــة وحكمــت بــرد دعــواه وبعــرض احلكــم‬\n‫علــى املدعــى عليــه قــرر القناعــة وطلــب املدعــي العــام التمييــز وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                 ‫حــرر يف ‪ 1434/05/01‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض ففــي يــوم األحــد املوافــق‪ 1434/08/07‬ه ـ افتتحــت اجللســة‬\n‫الســاعة التاســعة والنصــف صباحــا بنــاء علــى قــرار أصحــاب الفضيلــة‬\n‫قضــاة الدائــرة الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة اإلســتئناف‬\n          ‫بالريــاض رقــم ‪ 34263965‬يف ‪1434/7/10‬ه ـ والــذي جــاء فيــه‬\n‫( لوحــظ لألكثريــة مــا يلــي ‪ -1‬املدعــي العــام طلــب متييــز احلكــم ولــم‬\n‫جنــد يف املعاملــة الئحــة اعتراضيــة أو أنــه يطلــب رفــع احلكــم بــدون‬\n‫الئحــة ‪ -2‬صــورة الوكالــة وصــورة ملكيــة الســيارة لــم يشــرح عليهــا‬\n‫مبطابقتهــا ألصلهــا فعلــى فضيلتــه مالحظــة مــا ذكــر واكمــال مــا يلــزم‬\n‫واهلل املوفــق) فعليــه حضــر املدعــي العــام وجــرى ســؤاله عــن املالحظــة‬\n‫األولــى فقــرر بأنــه ليــس لديــه الئحــة إعتراضيــة مكتفيــا مبــا جــاء يف‬\n‫أوراق املعاملــة وبالنســبة للمالحظــة الثانيــة فقــد جــرى الشــرح علــى‬\n‫صــورة الوكالــة وصــورة ملكيــة الســيارة مبطابقتهــا ألصلهــا لــذا جــرى‬\n‫تدوينــه وعليــه جــرى التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n             ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/08/07‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n\n\n                                                                                    ‫‪396‬‬\n\f      ‫الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n      ‫خطــاب فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪341854258‬‬\n      ‫وتاريــخ ‪1434/8/25‬ه ـ املرفــق بهــا القــرار الصادرمــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ‪ /‬املســجل برقــم ‪ 34204202‬وتاريــخ ‪1434/5/4‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ضــد ‪ /‬يف قضيــة مخــدرات علــى النحــو‬\n      ‫املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‬\n      ‫وحيــث ســبق دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباإلطــاع‬\n      ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه‬\n      ‫بنــاء علــى القــرار رقــم ‪ 34263965‬وتاريــخ ‪1434/7/10‬ه ـ لــم يظهــر‬\n      ‫لألكثريــة مــا يوجــب نقــض احلكــم بعــد اإلجــراء األخيرمــع تنبيــه‬\n      ‫فضيلتــه إلــى توقيــع املوظــف املختــص علــى ختــم طبــق األصــل بصــورة‬\n      ‫الضبــط فيالحــظ ذلــك مســتقبآل واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                                      ‫محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪397‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":389,"source_page_end":397,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c39651cb653a5ade40d8ae125af74b11903df7a5cc536ff37b774ba1bb69a763","normalized_text_hash":"655c45033f2d37b6c7ad8d4d51e171cefa530e54d7ff3692f20f1119bb3f8e29","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p389-34204202"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"58ccffea-0008-58ff-a948-47aecf281352","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج حشيش -حيازة حشيش -حيازة حبوب محظورة- حيازة هيروين مخدر -تعاطي الهيروين واحلشيش -احلبوب احملظورة -اشتراك يف حيازة لغرض الترويج -تستر -إقرار حتقيق ا- تعزير بالسجن واجللد والغرامة -تعزير باملنع من السفر -تعزير باملصادرة -إلغاء شريحة جوال -إقامة حد املسكر على متعاطي","document_number":"34197957","case_number":"34171886","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/24","year":"1434","subject":"مخدرات -ترويج حشيش -حيازة حشيش -حيازة حبوب محظورة- حيازة هيروين مخدر -تعاطي الهيروين واحلشيش -احلبوب احملظورة -اشتراك يف حيازة لغرض الترويج -تستر -إقرار حتقيق ا- تعزير بالسجن واجللد والغرامة -تعزير باملنع من السفر -تعزير باملصادرة -إلغاء شريحة جوال -إقامة حد املسكر على متعاطي","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34197957:‬تاريخه‪1434/04/24:‬هـ‬\n                    ‫رقم الدعوى‪34171886:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n    ‫‪/34227641‬ج‪/2‬ب تاريخه‪1434/05/29:‬هـ‬\n\n\n‫مخــدرات‪ -‬ترويــج حشــيش‪ -‬حيــازة حشــيش ‪ -‬حيــازة حبــوب محظــورة‪-‬‬\n‫حيــازة هيرويــن مخــدر‪ -‬تعاطــي الهيرويــن واحلشــيش‪ -‬احلبــوب‬\n‫احملظــورة ‪ -‬اشــتراك يف حيــازة لغــرض الترويــج‪ -‬تســتر‪ -‬إقــرار حتقيق ًا‪-‬‬\n‫تعزيــر بالســجن واجللــد والغرامــة‪ -‬تعزيــر باملنــع مــن الســفر‪ -‬تعزيــر‬\n‫باملصــادرة‪ -‬إلغــاء شــريحة جــوال‪ -‬إقامــة حــد املســكر علــى متعاطــي‬\n                                                                ‫احلشــيش ‪.‬‬\n\n\n\n      ‫‪ -1‬نهي النبي ‪ -‬صلى اهلل عليه وسلم ‪ -‬عن كل مسكر ومفتر ‪.‬‬\n                          ‫‪ -2‬القاعدة الفقهية ‪ :‬املرء مؤاخذ بإقراره ‪.‬‬\n‫‪ -3‬املــواد ‪ -56 -38‬الفقــرة األولــى مــن املــادة ‪ 53‬مــن نظــام مكافحــة‬\n                                         ‫املخــدرات واملؤثــرات العقليــة ‪.‬‬\n             ‫‪ -4‬تعميم سمو وزير الداخلية رقم ‪ 47‬يف ‪1421/3/18‬هـ ‪.‬‬\n          ‫‪ -5‬تعميم سمو وزير الداخلية رقم ‪ 9798‬يف ‪1428/2/10‬هـ ‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا بترويــج األول للحشــيش‬\n‫املخــدر بقصــد االجتــار وحيــازة احلشــيش بقصــد الترويــج وحيــازة‬\n‫احلبــوب احملظــورة والهيرويــن بقصــد التعاطــي وتعاطيــه ســابقا لهــا‬\n‫واتهــام الثانــي بنقــل احلشــيش املخــدر وإحــرازه بقصــد الترويــج وحيــازة‬\n                                                                                 ‫‪344‬‬\n\f      ‫احلبــوب احملظــورة والهيرويــن بقصــد التعاطــي وتعاطيــه الســابق لهــا‪،‬‬\n      ‫وطلــب املدعــي العــام إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بالعقوبــة‬\n      ‫الــواردة يف الفقــرة األولــى مــن املــادة (‪ )38‬مــن نظــام مكافحة املخدرات‬\n      ‫واملؤثــرات العقليــة وتشــديد العقوبــة لقــاء ســوابقهما ومصــادرة اجلوالــن‬\n      ‫املضبوطــن يف اجلرميــة وتعزيرهمــا لتســترهما‪ ،‬حيــث إنــه مت القبــض‬\n      ‫علــى املدعــى عليهمــا بعــد ورود بــاغ مفــاده أن املدعــى عليــه األول لديــه‬\n      ‫كميــة مــن احلشــيش املخــدر ويريــد بيعــه ومت التنســيق معــه علــى شــراء‬\n      ‫الكميــة ومت ذلــك وتبــن أن املدعــى عليــه الثانــي هــو الــذي ســلم املدعــى‬\n      ‫عليه األول الكمية التي مت بيعها وقام بنقلها ‪ ،‬أقر املدعى عليهما مبا‬\n      ‫أســند إليهمــا ‪ ،‬بنــاء علــى مــا ســبق حكمــت احملكمــة بتعزيــر املدعــى‬\n      ‫عليهمــا بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة اجلوالــن‬\n      ‫وإلغــاء الشــريحتني املســتخدمتني يف اجلرميــة ‪ ،‬إقامــة حــد املســكر علــى‬\n                     ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬      ‫املدعــى عليهمــا ُ‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..............‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n                                                                                 ‫ّ‬\n      ‫احملكمــة اجلزائيــة يف محافظــة االحســاء املكلــف برقــم ‪34171886‬‬\n      ‫وتاريــخ ‪ 1434/04/15‬ه ـ املقيــدة باحملكمــة برقــم ‪34917252‬‬\n      ‫وتاريــخ ‪ 1434/04/15‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1434/04/24‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 10 : 30‬وفيهــا حضــر املدعــي العــام ‪..............‬‬\n      ‫املعمــد بالترافــع أمــام هــذه احملكمــة مبوجــب خطــاب ســعادة رئيــس‬\n      ‫دائــرة التحقيــق واالدعــاء العــام مبحافظــة االحســاء ذي الرقــم ‪..............‬‬\n\n‫‪345‬‬\n\f‫والتاريــخ ‪ 1433/12/01‬ه ـ وادعــى ضــد احلاضريــن معــه ‪..............‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..............‬و‪..............‬‬\n‫ال يف دعواه‬    ‫ســعودي اجلنســية مبوجب الســجل املدني رقم (‪ )..............‬قائ ً‬\n‫فباالطــاع علــى محضــر القبــض املعــد مــن قبــل مكافحــة املخــدرات‬\n‫مبحافظــة األحســاء تبــن أنــه بتاريــخ ‪1434/1/7‬ه ـ توفــرت معلومــات‬\n‫لــدى ادارة مكافحــة املخــدرات مبحافظــة األحســاء مــن أحــد املصــادر‬\n‫الســرية لــدى مكافحــة املخــدرات مبنطقــة مكــة املكرمــة تفيــد بــأن‬\n‫املتهــم األول لديــه كميــة كبيــرة مــن احلشــيش املخــدر ويبحــث عــن‬\n‫مشــتري لتلــك الكميــة فتــم إعــداد اخلطــة الالزمــة لإلطاحــة باملتهــم‬\n‫ومت التنســيق مــع املتهــم األول مــن قبــل مكافحــة املخــدرات مبنطقــة‬\n‫مكــة املكرمــة بــأن هنالــك مشــتري مبحافظــة األحســاء يرغــب بشــراء‬\n‫تلــك الكميــة فوافــق املتهــم األول علــى ذلــك ومت تكليــف أحــد أفــراد‬\n‫فرقــة مكافحــة املخــدرات مبحافظــة األحســاء للقيــام بــدور املشــتري‬\n‫ويف يــوم األربعــاء ‪1434/1/7‬ه ـ مت االتصــال علــى املتهــم األول علــى‬\n‫جوالــه رقــم(‪ )..............‬علــى مســمع مــن الفرقــة القابضــة وطلــب منــه‬\n‫بيعــه (‪ )35‬كيلــو مــن احلشــيش املخــدر فوافــق املتهــم األول علــى ذلــك‬\n‫ومت ترقيــم مبلــغ حكومــي وقــدره (‪ )18000‬ثمانيــة عشــر ألــف ريــال‬\n‫ويف يــوم اخلميــس اتصــل املشــتري رجــل األمــن باملتهــم األول وطلــب منــه‬\n‫الكميــة املطلوبــة وأفــاد بــأن الكميــة يف محافظــة رأس تنــورة وأن‬\n‫هنالــك شــخص آخــر ســوف يقــوم بإحضارهــا ويف يــوم اخلميــس تقابــل‬\n‫املشــتري رجــل األمــن باملتهــم األول وســلمه قطعتــن مــن احلشــيش املخــدر‬\n‫بلــغ وزنهمــا (‪ )9‬تســعة جــرام كعينــة للكميــة أحيلت عينــه منها للتحليل‬\n‫برقــم (‪ )..............‬املتفــق عليــه ويف يــوم الثالثــاء اتصــل املشــتري رجــل‬\n\n\n                                                                                      ‫‪346‬‬\n\f      ‫األمــن علــى املتهــم األول وأخبــره بــأن العينــة مناســبة وطلــب إحضــار(‪)35‬‬\n      ‫كيلــو مــن احلشــيش واتفــق علــى مــكان وموعــد اســتالم الكميــة‬\n      ‫وقــد ورد للعمليــات أن املتهــم األول اســتلم الكميــة مــن املتهــم الثانــي‬\n      ‫الــذي نقــل الكميــة مــن محافظــة رأس تنــورة إلــى األحســاء بســيارة‬\n      ‫مــن نــوع ‪ ....‬موديــل ‪2009‬م حتمــل اللوحــة رقــم (‪ )..............‬ويف يــوم‬\n      ‫األربعاء‪1434/1/14‬ه ـ ويف املــكان املتفــق عليــه حضــر املتهــم األول‬\n      ‫علــى ســيارة مــن نــوع ‪ .......‬موديــل (‪ )2004‬حتمــل اللوحــة دبــي رقمهــا‬\n      ‫(‪ )..............‬وقابــل املشــتري رجــل األمــن وســلمه حقيبــة بهــا خمســة عشــر‬\n      ‫كيلــو مــن احلشــيش املخــدر وأحيلــت للتحليــل برقــم (‪ )..............‬وأثنــاء‬\n      ‫شــروع املتهــم يف اســتالم املبلــغ شــك يف األمــر وحــاول الفــرار فتــم القبض‬\n      ‫عليــه وأفــاد بأنــه يوجــد كميــة مــن املخــدرات يف منــزل املتهــم الثانــي‬\n      ‫وبتفتيشــه عثــر بحوزتــه علــى قطعتــن ســوداء يشــتبه أن تكــون مــن‬\n      ‫احلشــيش املخــدر تــزن (‪)95‬خمســة وتســعون جرام ـ ًا أحيلــت عينــه منهــا‬\n      ‫برقــم (‪)..............‬وعدد(‪)5‬خمســة حبــات يشــتبه أن تكــون مــن حبــوب‬\n      ‫األمفيتامــن أحيلــت برقــم (‪)..............‬وعــدد(‪ )7‬حبــات يشــتبه أن تكون‬\n      ‫محظــورة أحيلــت برقــم (‪)..............‬وكيســن نايلــون بهــا آثــار الهرويــن‬\n      ‫بلــغ وزنهــا (‪)3،2‬ثالثــة جــرام واثنــن مــن العشــرة مــن اجلــرام أحيلــت‬\n      ‫كاملــة للتحليــل برقــم (‪ )..............‬كمــا ضبــط بحوزتــه جهــاز جــوال‬\n      ‫يحمــل الرقــم التسلســلي (‪ )..............‬وشــريحة اتصــال رقــم(‪)..............‬‬\n      ‫املســتخدم يف عمليــة الترويــج وباالنتقــال إلــى شــقة املتهــم الثانــي الواقعــة‬\n      ‫يف محافظــة رأس تنــورة مت القبــص علــى املتهــم ‪( ..............‬فــرزت لــه‬\n      ‫أوراق) بداخــل الشــقة وبتفتيــش الشــقه عثــر علــى (‪ )9‬تســعة كيلــو مــن‬\n      ‫احلشــيش املخــدر أحيلــت للتحليــل برقــم (‪ )..............‬ومجموعــة مــن قطــع‬\n\n\n‫‪347‬‬\n\f‫احلشــيش املخــدر تزن(‪)180‬جــرام معــدة للترويــج أحيلــت عينــه منهــا‬\n‫للتحليــل برقــم (‪ )..............‬وعــدد(‪ )72‬اثنــان وســبعون حبــة مــن احلبــوب‬\n‫احملظــورة أحيلــت عينــه منهــا للتحليــل برقــم (‪ )..............‬وعــدد(‪ )3‬حبات‬\n‫مــن حبــوب الكبتاجــون أرســلت كاملــة للتحليــل برقــم (‪)..............‬‬\n‫وعــدد (‪ )20‬حبــة زهريــة اللــون مــن احلبــوب احملظــورة أرســلت عينــه‬\n‫منهــا للتحليــل برقــم (‪ )..............‬وعــدد (‪ )8‬ثمانيــة أكيــاس نايلــون بهــا‬\n‫آثــار الهرويــن املخــدر تــزن مبجموعهــا (‪ )3،6‬ثالثــة جــرام وســتة مــن‬\n‫العشــرة مــن اجلــرام أحيلــت كاملــة للتحليــل برقــم (‪ )..............‬وســاح‬\n‫مــن نــوع مســدس (مت فــرز أوراق مســتقلة للســاح)‪ .‬وقــد أثبــت التقريــر‬\n‫الكيمــاوي الشــرعي رقــم (‪ )..............‬لعــام ‪1434‬ه ـ إيجابيــة عينــات‬\n‫رقم(‪..............‬ورقــم (‪ )..............‬ورقــم (‪ )..............‬ورقــم (‪)..............‬‬\n‫ورقــم (‪ )..............‬للحشــيش املخــدر املــدرج علــى اجلــدول رقــم (‪ )1‬فئة (أ)‬\n‫كمــا أثبــت التقريــر ايجابيــة العينتــن رقــم (‪ )..............‬ورقــم (‪)..............‬‬\n‫ملــادة األمفيتامــن املــدرج باجلــدول رقــم (‪ )2‬فئــة (ب) امللحــق بنظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة كمــا أثبــت التقريــر إيجابيــة‬\n‫العينتــن رقــم (‪ )..............‬ورقــم (‪ )..............‬لعقــار البــرازوالم املــدرج‬\n‫باجلــدول رقــم (‪ )2‬فئــة (د) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة وباســتجواب األول ‪ :‬اقــر بواقعــة القبــض والضبــط وأفــاد بأنــه‬\n‫ورد إليــه اتصــال مــن املكلــف بالشــراء علــى جوالــه املذكــور أعــاه‬\n‫وطلــب منــه شــراء خمســة عشــر كيلــو مــن احلشــيش املخــدر فوافــق‬\n‫علــى ذلــك وقابلــه يف يــوم األثنــن ‪1434/1/12‬ه ـ وســلمه (‪ )9‬تســعة‬\n‫جــرام مــن احلشــيش املخــدر كعينــة لباقــي الكميــة ويف يــوم اخلميــس‬\n‫‪1434/1/14‬ه ـ قابــل املكلــف وســلمه حقيبــة بهــا (‪ )15‬خمســة عشــر‬\n\n\n                                                                                            ‫‪348‬‬\n\f      ‫كيلــو مــن احلشــيش املخــدر كمــا أقــر بحيــازة قطعتــن مــن احلشــيش‬\n      ‫املخــدر تــزن مبجموعهمــا(‪ )95‬خمســة وتســعون جرام ـ ًا وعــدد(‪)5‬‬\n      ‫خمــس حبــات مــن حبــوب األمفيتامــن وعــدد (‪ )7‬ســبع حبــات مــن‬\n      ‫حبــوب البــرازوالم وكيســن بهــا آثــار الهرويــن املخــدر بقصــد التعاطــي‬\n      ‫والترويــج كمــا أقــر بإيداعــه احلشــيش املخــدر املضبــوط لــدى املتهــم‬\n      ‫الثانــي بقصــد الترويــج كمــا أقــر بتعاطيــه للحشــيش املخــدر والهرويــن‬\n      ‫املخــدر ونفــى معرفتــه باملتهــم ‪ ...............‬وباســتجواب الثاني‪:‬أقــر بنقــل‬\n      ‫احلشــيش املخــدر مــن محافظــة رأس تنــورة إلــى األحســاء بقصــد الترويــج‬\n      ‫كمــا أقــر بحيازتــه ملــا ضبــط يف شــقته مــن احلشــيش املخــدر بقصــد‬\n      ‫تخزينهــا لــأول لغــرض يبعهــا أو اســتعمالها كمــا أقــر بحيازتــه حلبــوب‬\n      ‫األمفيتامــن احملظــورة والهرويــن املخــدر وحبــوب البــرازوالم املضبوطــة‬\n      ‫يف شــقته بقصــد التعاطــي ونفــى عالقــة املتهــم ‪..............‬باملضبوطــات أو‬\n      ‫علمــه بعمليــة الترويــج أقــر باســتخدام جوالــه مــن نــوع ‪ .....‬يحمــل شــريحة‬\n                 ‫اتصــال رقــم (‪ )..............‬يف عمليــة التنســيق للنقــل الكميــة‪.‬‬\n      ‫وقــد أســفر التحقيــق عــن توجيــه االتهــام لــ‪ .............. /‬ببيــع (‪)15،9‬‬\n      ‫خمســة عشــر كيلــو وتســعة جــرام مــن احلشــيش املخــدر بقصــد االجتــار‬\n      ‫وحيــازة (‪ )9،180‬تســعة كيلــو ومائــة وثمانــون جرام ـ ًا مــن احلشــيش‬\n      ‫املخــدر بقصــد الترويــج وحيــازة قطعتــن من احلشــيش املخــدر بلغ وزنهما‬\n      ‫(‪ )95‬خمســة وتســعون جرام ـ ًا وعــدد (‪ )5‬خمــس حبــات مــن حبــوب‬\n      ‫األمفيتامــن احملظــور وعــدد (‪ )7‬ســبع حبــات مــن حبــوب البــرازوالم‬\n      ‫احملظــور وحيــازة عــدد (‪ )2‬كيســن نايلــون بهمــا آثــار الهرويــن بلــغ‬\n      ‫وزنهمــا (‪ )3،2‬ثالثــة جرامــات واثنــن مــن العشــرة مــن اجلــرام بقصــد‬\n                                           ‫التعاطــي وتعاطيــه ألنواعهــا يف الســابق‬\n\n\n‫‪349‬‬\n\f‫واتهــام ‪.............. /‬بنقــل (‪ )15‬خمســة عشــر كيلــو مــن احلشــيش املخــدر‬\n‫بقصــد الترويــج ‪ ،‬واحــراز (‪ )9،180‬تســعة كيلــو ومائــة وثمانــون جــرام‬\n‫مــن احلشــيش املخــدر بقصــد الترويــج باالشــتراك مــع األول وحيــازة عــدد‬\n‫(‪ )20‬عشــرون حبــة مــن حبــوب البــرازوالم احملظــورة وعــدد (‪)3‬ثــاث‬\n‫حبــات مــن حبــوب األمفيتامــن احملظــور وعــدد (‪ )8‬ثمــان أكيــاس‬\n‫حتــوي آثــار الهرويــن بلــغ وزن مجموعهــا (‪ )3،6‬ثالثــة جــرام وســتة مــن‬\n‫العشــرة مــن اجلــرام بقصــد التعاطــي وحيــازة عــدد (‪ )72‬حبــة مــن حبــوب‬\n‫الكونازيبــام بقصــد التعاطــي وتعاطيــه ألنواعهــا يف الســابق‪،‬املجرم‬\n‫مبوجــب املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫وتســتر همــا علــى مصــدر املخــدرات‪ .‬كمــا أثبــت التقريــر ايجابيــة‬\n‫العينــة رقــم (‪ )..............‬لعقــار الكونازيبــام املــدرج باجلــدول رقــم (‪)2‬‬\n‫فئــة (د) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة كمــا‬\n‫أثبــت التقريــر ايجابيــة العينتــن رقــم (‪..............‬ورقــم (‪ )..............‬ملــادة‬\n                             ‫الهرويــن املخــدر‪ .‬وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ -1‬ماجــاء يف اقــرار املتهــم األول املدونــة علــى الصفحــات رقــم‬\n‫(‪ )10،9،6،5‬مــن دفتــر التحقيــق املرفــق لفــه رقــم(‪ )34‬داخــل الطــرد‪.‬‬\n‫‪ -2‬ماجــاء يف اقــرار املتهــم الثانــي املدونــة علــى الصفحــات رقــم‬\n‫(‪ )8،7،2،1‬مــن دفتــر التحقيــق املرفــق لفــه رقــم(‪ )34‬داخــل الطــرد‪.‬‬\n‫‪-4‬ماجــاء يف محضــر القبــض املــدون علــى الصفحــات رقــم‬\n‫(‪ )17،16،15،14،13،12‬مــن دفتــر االســتدالل املرفــق لفــه(‪)15‬‬\n                                                                       ‫داخــل الطــرد‪.‬‬\n    ‫‪-5‬ما جاء يف التقرير الكيماوي املرفق لفة (‪ )42،41‬داخل الطرد ‪.‬‬\n\n\n                                                                                            ‫‪350‬‬\n\f      ‫وبالبحــث عــن ســوابقهم تبــن وجــود ثــاث عشــرة ســابقة للمتهــم األول‬\n      ‫األولــى معاكســة والثانيــة ســرقة والثالثــة دخــول منــزل لغــرض ســيء‬\n      ‫والرابعــة شــرب املســكرات وفعــل فاحشــة اللــواط واخلامســة شــرب‬\n      ‫املســكرات ودخــول املنــازل لغــرض ســيء والسادســة مخــدرات وحيــازة‬\n      ‫ســاح بــدون ترخيــص وشــرب املســكرات والســابعة تكــرار دخــول‬\n      ‫مستشــفى األمــل مــن اإلدمــان والثامنــة والتاســعة حيــازة واســتعمال‬\n      ‫مخــدرات والعاشــرة واحلاديــة عشــر حيــازة مخــدرات داخــل الســجن‬\n      ‫والثانيــة عشــر حيــازة وســتعمال مخــدرات والثالثــة عشــر حيــازة‬\n      ‫مخــدرات داخــل الســجن وحيــازة واســتعمال مخــدرات وتســتر على مروج‬\n      ‫املخــدرات وتبــن وجــود ثمــان ســوابق للمتهــم الثانــي األولــى أخالقيــة‬\n      ‫والثانيــة شــرب املســكرات والثالثــة حيــازة مخــدرات والرابعــة حيــازة‬\n      ‫واســتعمال مخــدرات وقيــادة الســيارة وهــو بحالــة ســكر واخلامســة‬\n      ‫شــرب املســكرات والتســبب يف حــادث مــروري والسادســة شــرب‬\n      ‫مســكرات واســتعمال مخــدرات والســابعة حيــازة واســتعمال مخــدرات‬\n      ‫وحيــازة أدوات اســتعمال املخــدرات وتكــرار ســوابقة والثامنــة اســتعمال‬\n                                                      ‫مخــدرات ‪ .‬إجــراءات أخــرى‪:‬‬\n      ‫ورد خطــاب مكافحــة املخــدرات رقــم (‪ )..............‬يف ‪1434/2/17‬ه ـ‬\n      ‫املتضمــن تعــاون املتهــم األول مــع املكافحــة يف ضبــط عــدد مــن‬\n      ‫مروجــي املخــدرات‪ .‬وحيــث إن مــا أقــدم عليــه املذكــوران ‪ ،‬وهمــا‬\n      ‫بكامــل أهليتهمــا املعتبــرة شــرع ًا ‪ ،‬فعــل مجــرم ومعاقــب عليــه نظام ـ ًا‬\n      ‫يف ضــوء نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n      ‫باملرســوم امللكــي الكــرمي (م‪ )39/‬وتاريــخ ‪1426/87‬ه ـ ممــا يتعــن‬\n      ‫معــه إحالتهمــا للمحكمــة اجلزائيــة اســتناد ًا علــى املادتــن(‪)128-126‬‬\n\n\n‫‪351‬‬\n\f‫مــن نظــام اإلجــراءات اجلزائيــة لطلــب إثبــات إدانتهمــا مبــا اســند إليهمــا‬\n                                                ‫واحلكــم عليهمــا مبــا يلــي ‪- :‬‬\n‫‪ -1‬احلكــم علــى األول والثانــي بالعقوبــة الــواردة يف الفقــرة األولــى مــن‬\n‫املــادة (‪ )38‬مــن النظــام املشــار إليــه لقــاء مــا أســند إليهمــا ‪ ،‬لكونهــا‬\n‫العقوبــة األشــد بنــاء علــى الفقــرة األولــى مــن املــادة (‪ )62‬مــن ذات النظــام‬\n‫وتشــديد العقوبــة عليهمــا لقــاء تعــدد ســوابقهما اســتناد ًا لبرقيــة نائــب‬\n                 ‫وزيــر الداخليــة رقــم (‪ )93958/5/5/1‬يف ‪1429/8/23‬هــ‪..‬‬\n‫‪ -2‬مصــادرة اجلوالــن املضبوطــن مــع املتهــم األول والثانــي واملســتخدم‬\n‫يف اجلرميــة املوصوفــان يف القــرار وفقـ ًا للفقــرة (األولــى) مــن املــادة (‪)53‬‬\n‫مــن نظــام املشــار إليــه وإيــداع املبالــغ يف حســاب إدارة املخــدرات بنــاء‬\n            ‫علــى تعميــم وزيــر الداخليــة رقــم (‪)47‬وتاريخ‪1421/2/18‬هــ‪. .‬‬\n‫‪ -3‬إلغــاء شــريحتي االتصــال املســتخدمة يف اجلرميــة وعــدم صرفهمــا‬\n‫للمتهمــن اســتناد ًا لتعميــم وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪9‬‬\n                                                               ‫‪1428/2/10-‬ه ـ‬\n‫‪ -4‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )56‬مــن النظــام‬\n                                                            ‫مبنعهــم مــن الســفر‪.‬‬\n           ‫‪ -5‬معاقبتهما بعقوبة تعزيرية لتسترهما على مصدر املخدرات‪.‬‬\n‫ا مــا‬‫هــذه دعــواي وبســؤال املدعــى عليــه األول ‪..............‬أجــاب قائ ـ ً‬\n‫ذكــره املدعــي العــام مــن بتاريــخ ‪1434/1/14‬ه ـ مت القبــض علــي مــن‬\n‫قبــل احــدى فــرق مكافحــة املخــدرات التابعــة حملافظــة األحســاء فهــذا‬\n‫صحيــح وكذلــك مــا ذكــره املدعــي العــام مــن أنــه مت االتصــال بــي علــى‬\n‫هاتفــي اجلــوال رقــم ‪..............‬وطلــب منــي (‪ )35‬كيلــو مــن احلشــيش‬\n                      ‫املخــدر مببلــغ وقــدره ‪ 18000‬ريــال فهــذا كلــه صحيــح‬\n\n\n                                                                                        ‫‪352‬‬\n\f      ‫وكذلــك مــا ذكــره املدعــي العــام مــن أننــي قمــت ببيــع (‪ )15،9‬خمســة‬\n      ‫عشــر كيلــو وتســعة جــرام مــن احلشــيش املخــدر وأنــه ُعثــر معــي قطعتــن‬\n      ‫مــن احلشــيش املخــدر تــزن مبجموعهمــا(‪ )95‬خمســة وتســعون جرام ـ ًا‬\n      ‫وعــدد(‪ )5‬خمــس حبــات مــن حبــوب األمفيتامــن وعــدد (‪ )7‬ســبع حبــات‬\n      ‫مــن حبــوب البــرازوالم وكيســن بهــا آثــار الهرويــن املخــدر قصــدي مــن‬\n                                  ‫حيازتهــا التعاطــي والترويــج فهــذا كلــه صحيــح‬\n      ‫وكذلــك مــا ذكــره املدعــي العــام مــن أننــي أتعاطــى احلشــيش املخــدر‬\n      ‫والهرويــن املخــدر فهــذا صحيــح وكذلــك مــا ذكــره املدعــي العــام مــن‬\n      ‫وجــود ثالثــة عشــر ســابقة علــي فصحيــح أيض ـ ًا وقــد خدعنــي فيهــا‬\n      ‫شــخص يدعــى ‪..............‬ســبق أن تعرفــت عليــه يف ســجن احلايــر وكان‬\n      ‫لــي عنــده مبلــغ وقــدره خمســة عشــر ألــف ريــال قيمــة ســيارة وأخبرنــي‬\n      ‫بأننــي إن ذهبــت بهــذه احلقيبــة التــي حتتــوي حشــيش فســوف يســلم لــي‬\n      ‫مبلغــي الــذي عنــده وأمــا مــا ذكــره املدعــي العــام مــن أننــي تســترت‬\n      ‫علــى مصدرهــا فغيــر صحيــح حيــث إننــي أخبرتهــم بأننــي اســتلمتها مــن‬\n                       ‫شــخص يدعــى ‪..............‬وأنــا تائــب ونــادم هكــذا أجــاب‬\n      ‫ا مــا ذكــره املدعــي‬ ‫وبســؤال املدعــى عليــه الثانــي ‪..............‬أجــاب قائ ـ ً‬\n      ‫العــام مــن أننــي قمــت بنقــل (‪ )15‬خمســة عشــر كيلــو مــن احلشــيش‬\n      ‫املخــدر بقصــد الترويــج وإحــراز (‪ )9،180‬تســعة كيلــو ومائــة وثمانــون‬\n      ‫جــرام مــن احلشــيش املخــدر بقصــد الترويــج باالشــتراك مــع األول فهــذا‬\n      ‫كلــه صحيــح وكذلــك مــا ذكــره املدعــي العــام مــن أنــه وجــد بشــقتي‬\n      ‫بعــد تفتيشــها عــدد (‪ )20‬عشــرون حبــة مــن حبــوب البــرازوالم احملظــورة‬\n      ‫وعــدد (‪)3‬ثــاث حبــات مــن حبــوب األمفيتامني احملظــور وعدد (‪ )8‬ثمان‬\n      ‫أكيــاس حتــوي آثــار الهرويــن بلــغ وزن مجموعهــا (‪ )3،6‬ثالثــة جــرام‬\n\n\n‫‪353‬‬\n\f‫وســتة مــن العشــرة مــن اجلــرام قصــدي وحيــازة عــدد (‪ )72‬حبــة من حبوب‬\n‫الكونازيبــام مــن حيازتهــا التعاطــي ووكذلــك مــا ذكــره املدعــي العــام‬\n‫مــن أننــي تعاطيــت ألنواعهــا يف الســابق فهــذا صحيــح أيض ـ ًا وكذلــك‬\n‫مــا ذكــره املدعــي العــام مــن وجــود ثمــان ســوابق علــي فهــذا صحيــح‬\n‫وأمــا مــا ذكــره املدعــي العــام مــن أننــي تســترت علــى مصــدر احلشــيش‬\n‫فغيــر صحيــح حيــث ذكــرت لهــم أن املدعــى عليــه األول هــو مــن وضعهــا‬\n‫عنــدي مــن أجــل حفظهــا هكــذا أجــاب وبســؤال املدعــي العــام عــن هــل‬\n‫ا ليــس لــدي ســوى مــا ذكرتــه يف أوراق املعاملــة‬            ‫لديــه بينــة أجــاب قائ ـ ً‬\n‫هكــذا أجــاب وباالطــاع علــى دفاتــر التحقيــق وجــد أن املدعــى عليهمــا‬\n‫أفــادا عــن مصــدر هــذا احلشــيش وباإلطــاع علــى املعاملــة وجــد فيهــا‬\n‫علــى لفــة رقــم ‪ 25‬التقريــر الكيمــاوي الشــرعي رقــم (‪ )..............‬لعــام‬\n‫‪1434‬ه ـ املتضمــن إيجابيــة عينــات رقــم(‪ ..............‬ورقــم (‪ ..............‬ورقــم‬\n‫(‪..............‬ورقــم (‪ )..............‬ورقــم (‪ )..............‬للحشــيش املخــدر املــدرج‬\n‫علــى اجلــدول رقــم (‪ )1‬فئــة (أ) كمــا أثبــت التقريــر ايجابيــة العينتــن رقم‬\n‫(‪/42‬هــ) ورقــم (‪ )..............‬ملــادة األمفيتامــن املــدرج باجلــدول رقــم (‪)2‬‬\n‫فئــة (ب) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة كمــا‬\n‫أثبــت التقريــر إيجابيــة العينتــن رقــم (‪ )..............‬ورقــم (‪ )..............‬لعقــار‬\n‫البــرازوالم املــدرج باجلــدول رقــم (‪ )2‬فئــة (د) امللحــق بنظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة كمــا أثبــت التقريــر ايجابيــة العينــة رقــم‬\n‫(‪ )..............‬لعقــار الكونازيبــام املــدرج باجلــدول رقــم (‪ )2‬فئــة (د) امللحــق‬\n‫بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة كمــا أثبــت التقريــر‬\n‫ايجابيــة العينتــن رقــم (‪ )..............‬ورقــم (‪ )..............‬ملــادة الهرويــن‬\n                                                                               ‫املخــدر ا‪.‬هـ‬\n\n\n                                                                                               ‫‪354‬‬\n\f      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإقــرار املدعــى عليهمــا‬\n      ‫وحيــث إن املــرء مؤاخــذ بإقــراره والتقريــر الكيمــاوي الشــرعي ولنهــي‬\n      ‫النبــي صلــى اهلل عليــه وســلم عــن كل مســكر ومفتــر كمــا يف حديــث‬\n      ‫أم ســلمه رضــي اهلل عنهــا وحيــث إن املدعــى عليهمــا أقــرا بالترويــج‬\n      ‫واحليــازة بقصــد التعاطــي وحيــث إن مــا أقــدم عليــه املدعــى عليهمــا‬\n      ‫ضــرب مــن ضــروب اإلفســاد بــاألرض لذلــك كلــه ثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه ‪ ..............‬ببيــع (‪ )15،9‬خمســة عشــر كيلــو وتســعة جــرام‬\n      ‫مــن احلشــيش املخــدر بقصــد االجتــار وحيــازة (‪ )9،180‬تســعة كيلــو‬\n      ‫ومائــة وثمانــون جرام ـ ًا مــن احلشــيش املخــدر بقصــد الترويــج وحيــازة‬\n      ‫قطعتــن مــن احلشــيش املخــدر بلــغ وزنهمــا (‪ )95‬خمســة وتســعون جرامـ ًا‬\n      ‫وعــدد (‪ )5‬خمــس حبــات مــن حبــوب األمفيتامــن احملظــور وعــدد (‪)7‬‬\n                                     ‫ســبع حبــات مــن حبــوب البــرازوالم احملظــور‬\n      ‫وحيــازة عــدد (‪ )2‬كيســن نايلــون بهمــا آثــار الهرويــن بلــغ وزنهمــا‬\n      ‫(‪ )3،2‬ثالثــة جرامــات واثنــن مــن العشــرة مــن اجلــرام بقصــد التعاطــي‬\n      ‫وتعاطيــه ألنواعهــا يف الســابق وكذلــك ثبــت لــدي إدانــة املدعــى عليــه ‪/‬‬\n      ‫‪ ..............‬بنقــل (‪ )15‬خمســة عشــر كيلــو مــن احلشــيش املخــدر بقصــد‬\n      ‫الترويــج ‪ ،‬واحــراز (‪ )9،180‬تســعة كيلــو ومائــة وثمانــون جــرام مــن‬\n      ‫احلشــيش املخــدر بقصــد الترويــج باالشــتراك مــع األول وحيــازة عــدد‬\n      ‫(‪ )20‬عشــرون حبــة مــن حبــوب البــرازوالم احملظــورة وعــدد (‪)3‬ثــاث‬\n      ‫حبــات مــن حبــوب األمفيتامــن احملظــور وعــدد (‪ )8‬ثمــان أكيــاس‬\n      ‫حتــوي آثــار الهرويــن بلــغ وزن مجموعهــا (‪ )3،6‬ثالثــة جــرام وســتة مــن‬\n      ‫العشــرة مــن اجلــرام بقصــد التعاطــي وحيــازة عــدد (‪ )72‬حبــة مــن حبــوب‬\n      ‫الكونازيبــام بقصــد التعاطــي وتعاطيــه ألنواعهــا يف الســابق ولــم يثبــت‬\n\n\n‫‪355‬‬\n\f‫لــدي تســترهما علــى مصــدر املخــدرات وحكمــت عليهمــا مبــا يلــي ‪:‬‬\n‫أو ًال ‪ :‬جلــد كل مــن املدعــى عليــه األول والثانــي ثمانــن جلــدة دفعــة‬\n‫واحــدة حــد املســكر ثاني ـ ًا ‪ :‬ســجن كل واحــد مــن املدعــى عليهمــا‬\n‫مــدة عشــر ســنوات حتتســب منهــا مــدة بقائهمــا بالســجن بخصــوص‬\n‫هــذه القضيــة وجلــد كل واحــد منهمــا ألــف جلــدة تعزيــر ًا مفرقــة علــى‬\n‫عشــرين دفعــة كل دفعــة خمســن جلــدة بــن كل دفعــة واألخــرى مــدة‬\n‫أســبوعني وإلــزام كل واحــد مــن املدعــى عليــه األول والثانــي بغرامــة‬\n‫ماليــة قدرهــا عشــرة آالف ريــال وذلــك مبوجــب املــادة ‪ 38‬مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة ثالث ـ ًا ‪ :‬منــع كل مــن املدعــى‬\n‫عليــه األول والثانــي مــن الســفر خــارج اململكــة مــدة عشــر ســنوات بعــد‬\n‫تنفيــذ مــدة محكوميتــه وذلــك مبوجــب املــادة ‪ 56‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة رابعـ ًا ‪ :‬مصــادرة اجلوالــن املضبوطــن مــع‬\n‫املدعى عليه األول الذي يحمل الرقم التسلســلي (‪ )..............‬و وكذلك‬\n‫اجلــوال املضبــوط مــع املدعــى عليــه الثانــي مــن نــوع ‪ .....‬واملســتخدمان يف‬\n‫اجلرميــة املوصوفــان يف القــرار وفقـ ًا للفقــرة (األولــى) مــن املــادة (‪ )53‬مــن‬\n‫نظــام املشــار إليــه وإيــداع املبالــغ يف حســاب إدارة املخــدرات بنــاء علــى‬\n                     ‫تعميــم وزيــر الداخليــة رقــم (‪)47‬وتاريخ‪1421/2/18‬هــ‪.‬‬\n‫خامس ـ ًا ‪ :‬إلغــاء شــريحة االتصــال رقــم (‪ )..............‬و رقــم (‪)..............‬‬\n‫املســتخدمتان يف اجلرميــة وعــدم صرفهمــا للمتهمــن اســتناد ًا لتعميــم‬\n                  ‫وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10- 9‬ه ـ‬\n‫سادسـ ًا ‪ :‬رد دعــوى املدعــي العــام بخصــوص معاقبــة املدعــى عليــه األول‬\n‫والثانــي عقوبــة تعزيريــة لقــاء تســترهما علــى مصــدر املواد املخــدرة لعدم‬\n‫ثبوتهــا وبــه حكمــت وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليــه‬\n\n\n                                                                                        ‫‪356‬‬\n\f      ‫قــرر املدعــي العــام االعتــراض علــى احلكــم وطلــب رفــع املعاملــة إلــى‬\n      ‫محكمــة االســتئناف بــدون الئحــة فأجبتــه لطلبــه وأمــا املدعــى عليهمــا‬\n           ‫قــررا قناعتهمــا بــه وبــه ختمــت اجللســة يف متــام الســاعة احلاديــة عشــر‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                 ‫وســلم ‪ .‬حــرر يف ‪ 1434/04/24‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪ 1434/06/27‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 08 : 15‬وفيهــا عــادت املعاملــة مــن محكمــة‬\n      ‫اإلســتئناف باملنطقــة الشــرقية برقــم ‪ 341215707‬يف ‪1434/06/19‬ه ـ‬\n      ‫واملتعلقــة بدعــوى املدعــي العــام ضــد ‪..............‬و ‪..............‬املدون هويتهما‬\n      ‫ســابق ًا يف قضيــة مخــدرات وبرفقهــا القــرار الشــرعي برقــم ‪34227641‬‬\n      ‫وتاريــخ ‪1434/05/29‬ه ـ الصــادر مــن الدائــرة اجلزائيــة الثالثيــة الثانيــة‬\n      ‫مبحكمــة االســتئناف باملنطقــة الشــرقية املتضمــن إنــه بدراســة‬\n      ‫القــرار وصــورة ضبطــه وباالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي‬\n      ‫وأحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى قرارنــا رقــم ‪ 34197957‬يف‬\n      ‫نصــه ‪:‬وبدراســة القــرار وصــورة ضبطــة‬      ‫‪1434/04/24‬ه ـ املتضمــن مــا ُّ‬\n      ‫وأوراق املعاملــة لوحــظ أن مــا حكــم بــه فضيلتــه علــى املدعــى عليهمــا‬\n      ‫مــن جــزاء وغرامــة قليــل جــدا نظــرا لســوابقهما وكثــرة الكميــة املباعة‬\n      ‫واحملــازه وكذلــك لــم يحكــم فضيلتــه مبصــادرة الســيارة املســتعملة يف‬\n      ‫نقــل احلشــيش ملالحظــة ذلــك واعــادة املعاملــة الكمــال الزمهــا واهلل‬\n      ‫املوفــق وعليــه أجيــب أصحــاب الفضيلــة قضــاة محكمــة االســتئناف‬\n      ‫وفقهــم اهلل لــكل خيربأننــي عدلــت عمــا حكمــت بــه علــى املدعــى‬\n      ‫عليهمــا فيمــا يخــص الســجن والغرامــة وحكمــت علــى كل واحــد مــن‬\n      ‫املدعــى عليهمــا وذلــك بســجنه مــدة اثنــا عشــر ســنة حتتســب منهــا مــده‬\n\n\n‫‪357‬‬\n\f‫بقائهــا بالســجن بخصــوص هــذه القضيــة وبغرامــة ماليــة قدرهــا اثنــا‬\n‫عشــر ألــف ريــال علــى كل واحــد منهمــا وأمــا فيمــا يخــص مصــادرة‬\n‫الســيارات فــإن املدعــي العــام لــم يطالــب بهــا واملدعــى عليهمــا ال ميلــكان‬\n‫هــذه الســيارات هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض ذلــك املدعــي‬\n‫العــام واملدعــى عليهمــا قــرروا جميعــا اعتراضهــم عليــه وطلبــوا رفــع‬\n‫املعاملــة الــى محكمــة االســتئاف بــدون الئحــة فأجبتهــم لطلبهــم وبــه‬\n‫ختمــت اجللســة يف متــام الســاعة ‪ 08 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/27‬هـ‬\n‫احلمد هلل وحده وبعد ‪ . . .‬فقد اطلعن ــا نحن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/1638844‬ج‪ 2‬وتاريــخ ‪1434/7/8‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n‫املكلــف برقــم ‪ 34/1215707‬وتاريــخ ‪1434/7/3‬ه ـ املرفــق بهــا القــرار‬\n‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪.............. /‬املســجل‬\n‫برقــم ‪ 34197957‬وتاريــخ ‪1434/4/24‬ه ـ اخلــاص بدعوى‪/‬املدعــي‬\n‫ـد‪/‬كل مــن‪............../1‬و‪............../2‬يف قضيــة مخــدرات وقــد‬\n                                                                ‫ٍ‬        ‫العــام ضـ‬\n‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه‬\n‫فضيلتــه علــى قرارنــا رقــم ‪/34227641‬ج‪/2‬ب وتاريــخ ‪1434/5/29‬ه ـ‬\n‫قررنــا املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى‬\n ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/7/22‬هــ‪.‬‬\n\n\n\n\n                                                                                      ‫‪358‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":344,"source_page_end":358,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"dace94d7b19925fbcd06c993cd6f206755aaf0ca57a935cba81c46d186c1488c","normalized_text_hash":"641627917d78aa7ce34fd8f5f7e4a0e3be61e94f3032b423f73fd89d3df96199","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p344-34197957"},{"id":"7903f98c-5b29-57af-a2b6-b13072a312f6","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج حبوب محظورة -تعزير بالسجن واجللد واملنع من السفر وتعزير باملصادرة وبإلغاء شريحة جوال -وبإعادة مبلغ مرقم -شهادة موصلة -ثبوت إدانة.","document_number":"34246013","case_number":"34171979","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/19","year":"1434","subject":"مخدرات -ترويج حبوب محظورة -تعزير بالسجن واجللد واملنع من السفر وتعزير باملصادرة وبإلغاء شريحة جوال -وبإعادة مبلغ مرقم -شهادة موصلة -ثبوت إدانة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34246013 :‬تاريخه‪1434/6/19 :‬هـ‬\n                          ‫رقم الدعوى‪34171979 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34293815‬تاريخه‪1434/08/10:‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬ترويــج حبــوب محظــورة ‪ -‬تعزيــر بالســجن واجللــد واملنــع‬\n       ‫مــن الســفر وتعزيــر باملصــادرة وبإلغــاء شــريحة جــوال ‪ -‬وبإعــادة مبلــغ‬\n                                         ‫مرقــم ‪ -‬شــهادة موصلــة ‪ -‬ثبــوت إدانــة‪.‬‬\n\n\n\n\n       ‫املــواد ( ‪ ) 60 - 56 - 53 - 38‬مــن نظــام مكافحــة املخــدرات و املؤثــرات‬\n                                                                      ‫العقليــة‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بيــع احلبــوب احملظــورة بقصــد‬\n       ‫اإلجتــار ‪ -‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه‬\n       ‫بالعقوبــة الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة‬\n       ‫املخــدرات واملؤثــرات العقليــة واملنــع مــن الســفر ومصــادرة اجلــوال وإلغــاء‬\n       ‫الشــريحة املســتخدمة يف اجلرميــة ‪ ،‬حيــث إنــه مت القبــض علــى املدعــى‬\n       ‫عليــه بعــد ورود معلومــات مفادهــا أن املدعــى عليــه يعمــل يف محــل بيــع‬\n       ‫التمــور ويــروج احلبــوب احملظــورة ومت التنســيق مع أحــد املصادر ومتكينه‬\n       ‫مــن االتصــال علــى املدعــى عليــه علــى جوالــه وطلــب شــراء كميــة مــن‬\n       ‫احلبــوب فوافــق علــى ذلــك فتــم ترقيــم املبلــغ احلكومــي وتوجــه املصــدر‬\n       ‫إلــى مقــر املدعــى عليــه وتقابــل املصــدر مــع املدعــى عليــه حتــت أنظــار‬\n\n‫‪359‬‬\n\f‫الفرقــة القابضــة ثــم دخــا أحــد املكاتــب وبعــد أكثــر مــن دقيقتــن‬\n‫خــرج املصــدر وأعطــى اإلشــارة الدالــة علــى االســتالم والتســليم فتــم‬\n‫القبــض علــى املدعــى عليــه وضبــط املبلــغ احلكومــي معــه كمــا ضبــط‬\n‫معــه اجلــوال املســتخدم يف عمليــة التنســيق وقــد ســلم املصــدر احلبتــن‬\n‫التــي اســتلمها مــن املدعــى عليــه ‪ ،‬إنــكار املدعــى عليــه ‪ ،‬فأحضــر‬\n‫املدعــي العــام بينــة موصلــة وهــم أعضــاء الفرقــة القابضــة ‪ ،‬فثبتــت إدانــة‬\n‫املدعــى عليــه ‪ .‬بنــاء علــى مــا تقــدم حكمــت احملكمــة تعزيــر املدعــى‬\n‫عليــه بالســجن واجللــد واملنــع مــن الســفر ومصــادرة الهاتــف اجلــوال وإلغــاء‬\n‫شــريحته وإعــادة املبلــغ املرقــم ‪ُ .‬صــدق احلكــم من محكمة االســتئناف‪.‬‬\n\n\n\n\n‫اجلزائيــة‬\n   ‫ّ‬         ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة‬\n‫باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة يف محافظــة االحســاء املكلــف برقــم ‪ 34171979‬وتاريــخ‬\n‫‪ 1434/04/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34917746‬وتاريــخ‬\n‫‪ 1434/04/15‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/04/28‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 12 : 00‬وفيهــا حضــر املدعــي العــام وادعــى ضــد‬\n‫احلاضــر معــه ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪............‬‬\n‫قائــا يف دعــواه باالطــاع علــى محضــر القبــض و الضبــط والتفتيــش‬\n‫ا ُملعــد مــن قبــل مكافحــة املخــدرات مبحافظــة األحســاء املــؤرخ يف‬\n‫‪1434/3/8‬ه ـ تبــن أنــه مت القبــض علــى املدعــى عليــه إثــر معلومــات مــن‬\n‫أحــد مصادرهــم الســرية تفيــد بــأن املدعــى عيلــه يعمــل يف مصنــع ‪.....‬‬\n‫و يــروج احلبــوب احملظــورة وقــد مت متكــن املصــدر مــن االتصــال علــى‬\n\n                                                                                       ‫‪360‬‬\n\f      ‫جــوال املدعــى عليــه رقــم (‪ )..........‬وطلــب منــه شــراء حبــوب محظــورة‬\n      ‫مببلــغ مئــة ريــال فوافــق علــى ذلــك ‪ ،‬و أخبــره بــأن احلبــوب موجــودة لديــه‬\n      ‫يف مقــر عملــه فتــم ترقيــم املبلــغ احلكومــي وتفتيــش املصــدر وتوجــه‬\n      ‫املصــدر إلــى داخــل املصنــع حتــت أنظــار الفرقــة وتقابــل املصــدر مــع‬\n      ‫املدعــى عليــه ودخــا أحــد املكاتــب وبعــد أكثــر مــن دقيقتــن خــرج‬\n      ‫املصــدر وأعطــى اإلشــارة الدالــة علــى االســتالم والتســليم فتــم القبــض‬\n      ‫علــى املدعــى عليــه وضبــط املبلــغ احلكومــي بجيــب قميصــه العلــوي وهو‬\n      ‫املبلــغ املعــد لكشــف القضيــة كمــا ضبــط بحيازتــه اجلــوال املســتخدم‬\n      ‫يف عمليــة التنســيق نــوع (‪ )......‬يحمــل الرقــم املصنعــي (‪ )............‬ولــم‬\n      ‫يعثــر معــه علــى أي مــن احملظــورات يف ســيارته وقــد ســلم املصــدر احلبتني‬\n      ‫التــي اســتلمها مــن املدعــى عليــه وباســتجواب املدعــى عليــه أقــر بعائديــة‬\n      ‫اجلــوال املشــار إليــه لــه و ال يســتخدمه أحــد غيــره وقــد أثبــت التقريــر‬\n      ‫الكيماوي الشرعي رقم (‪ ).....‬لعام ‪1434‬هـ إيجابية ما مت ضبطه ملادة‬\n      ‫اإلمفيتامــن املنبــه احملظــور املدرجــة يف اجلــدول (‪ )2‬فئــة (ب) مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة وانتهــى التحقيــق مــع املدعــى‬\n      ‫عليــه إلــى توجيــه االتهــام لــه ببيــع حبتــن مــن حبــوب األمفيتامــن املنبــه‬\n      ‫احملظــور بقصــد االجتــار و املجــرم نظام ـ ًا يف ضــوء الفقــرة الثانيــة مــن‬\n      ‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n               ‫باملرســوم امللكــي الكــرمي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n                                                      ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n      ‫‪ -1‬إقــراره بعائديــة اجلــوال املســتخدم يف اجلرميــة لــه املــدون علــى‬\n          ‫الصفحتــن رقــم (‪ )2.1‬مــن ملــف التحقيــق املرفــق لفــة (‪.)10‬‬\n      ‫‪ -2‬محضــر القبــض والضبــط والتفتيــش املــدون علــى الصفحتــن رقــم‬\n\n\n‫‪361‬‬\n\f                                    ‫(‪ )11‬مــن ملــف االســتدالل املرفــق لفــة (‪.)5‬‬\n                           ‫‪ -3‬التقرير الكيماوي الشرعي املرفق لفة (‪.)20‬‬\n‫ـرعا‬\n   ‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شـ ً‬\n‫نظامــا ؛ لــذا اطلــب إثبــات مــا أسن ــد‬\n                                         ‫ً‬      ‫ـب عليــه‬\n                                                        ‫فعــل محــرم ومجــرم ومعاقـ ٌ‬\n                                                      ‫إليــه و احلكــم عليــه بالتالــي ‪:‬‬\n‫‪.1‬بالعقوبــة الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة‬\n                            ‫املخــدرات واملؤثــرات العقليــة لقــاء مــا أســند إليــه‪.‬‬\n‫‪.2‬منعــه مــن الســفر خــارج اململكــة بعــد تنفيــذ العقوبــة اســتناد ًا للفقــرة‬\n                                            ‫(‪ )1‬مــن املــادة (‪ )56‬مــن ذات النظــام‪.‬‬\n‫‪.3‬مصــادرة جــوال املتهــم نــوع (‪ ).....‬يحمــل الرقــم املصنعــي (‪)............‬‬\n‫املســتخدم يف اجلرمية اســتناد ًا للفقرة (‪ )1‬من املادة (‪ )53‬من ذات النظام‬\n‫‪ ،‬وايــداع األمــوال املتحصلــة مــن األعيــان يف حســاب إدارة املخــدرات‬\n‫اســتناد ًا لقــرار مجلــس الــوزراء رقــم (‪ )47‬وتاريــخ ‪1421/2/18‬هــ‪4.‬ـ‪.‬‬\n‫إلغاء شــريحة االتصال العائدة للمتهم املســتخدمة يف اجلرمية و املوصوفة‬\n‫يف القــرار وعــدم صرفهــا لــه مــرة أخــرى وفــق برقيــة وزيــر الداخليــة رقــم‬\n‫(‪ )9798/4/5/1‬وتاريــخ ‪1428/2/10-9‬ه ـ هــذه دعــواي وبعــرض‬\n‫الدعــوى علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام‬\n‫يف دعــواه مــن قيامــي ببيــع احلبــوب احملظــورة غيــر صحيــح والصحيــح‬\n‫أن زميلــي يف العمــل طلــب منــي أن اقــوم بحفــظ مبلــغ مائــة ‪ 100‬ريــال‬\n‫لكونــة وقــت غســيل التمــر فقمــت بأخــذ هــذا املبلــغ ثــم قبــض علينــا مــن‬\n‫املباحــث بعــد ذلــك هــذه إجابتــي وبعــرض ذلــك علــى املدعــي العــام قــال‬\n‫الصحيــح مــا ذكرتــه وبســؤاله البينــة علــى دعــواه قــال لــدي البينــه علــى‬\n‫ذلــك وســأحضرها يف اجللســة القادمــة لــذا قــررت رفــع اجللســة إلحضــار‬\n\n\n                                                                                            ‫‪362‬‬\n\f      ‫الشــهود يف القضيــة اهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                        ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/28‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق‪ 1434/05/27‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 11.30‬للنظــر بدعــوى املدعــي العــام ضــد‬\n      ‫وفيهــا حضــر وفيهــا حضــر الطرفــان كمــا يف اجللســة الســابقة وبســؤال‬\n      ‫املدعــي العــام عــن بينتــه قــال أنهــا لــم حتضــر يف هــذه اجللســة رغــم‬\n      ‫تبلغهــم بخطــاب هيئــة التحقيــق واالدعــاء العــام رقــم ‪ 341125574‬يف‬\n      ‫‪1434/5/7‬ه ـ وأطلــب اإلمهــال إلــى جلســة أخــرى إلحضــار الشــهود‬\n      ‫يف القضيــة لــذا قــررت رفــع اجللســة إلحضــار بينــة املدعــي العــام واهلل‬\n      ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                   ‫‪ 1434/05/27‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االثنــن املوافــق ‪1434/6/19‬ه ـ‬\n      ‫افتتحــت اجللســة للنظــر بدعــوى املدعــي العــام ضــد وفيهــا حضــر‬\n      ‫ال مــن‬\n            ‫الطرفــان كمــا يف اجللســة الســابقة واحضــر معــه للشــهادة ك ً‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....................‬و ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..........................‬وبســؤالهما‬\n      ‫ا اشــهد‬  ‫عمــا لديهمــا مــن شــهادة شــهد كل واحــد منهمــا مبفــرده قائ ـ ً‬\n      ‫بــأن أحــد املصــادر لدينــا بلــغ بــأن املدعــى عليــه يقــوم بترويــج احلبــوب‬\n      ‫احملظــورة يف مصنــع ‪ ......‬فقمنــا بالتنســيق مــع املصــدر واتصــل باملدعــى‬\n      ‫عليــه علــى أن يقــوم بشــراء احلبــوب منــه فوافــق املدعــى عليــه علــى ذلــك‬\n      ‫وطلــب منــه حبتــن مببلــغ مئــة ‪ 100‬ريــال واجتهنــا إلــى مصنــع التمــور‬\n      ‫وقمنــا بتفتيــش املصــدر وســلم املبلــغ احلكومــي ثــم اجتــه إلــى املدعــى‬\n      ‫عليــه وكلمــه ثــم دخــل معــه يف أحــد املكاتــب وعنــد خروجــه اعطانــا‬\n\n\n‫‪363‬‬\n\f‫اإلشــارة فتــم القبــض علــى املدعــى عليــه ويف جيبــه العلــوي املبلــغ‬\n‫احلكومــي وســلمنا املصــدر احلبتــن التــي مت شــرائها هــذا مــا رأينــا وبــه‬\n‫نشــهد وبعــرض ذلــك علــى املدعــى عليــه قــال مــا ذكــره الشــهود غيــر‬\n‫صحيــح وهــؤالء الشــهود ال اعرفهــم بعــد ذلــك جــرى ســؤال املدعــى عليــه‬\n‫عــن رقــم جوالــه فذكــر أن رقــم اجلــوال هــو املذكــور يف دعــوى املدعــي‬\n‫العــام وبالرجــوع إلــى التقريــر الكيمــاوي وجــدت فيــه إيجابيــة العينــة‬\n‫املضبوطــة لإلمفيتامــن بعــد ذلــك جــرى تزكيــة الشــاهدين مــن قبــل‬\n‫‪ ........‬ســعودي بالســجل املدنــي رقــم ‪ ........‬ســعودي بالســجل املدنــي رقــم‬\n‫‪ ...........‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبنــاء علــى شــهادة‬\n‫الشــاهدين املذكــورة أعــاه املعدلــن وفــق األصــول والقواعــد الشــرعية‬\n‫وفيهــا تفصيــل االتصــال علــى املدعــى عليــه وســماع صوتــه واإلتفــاق معــه‬\n‫علــى البيــع وحيــث أقــر املدعــى عليــه بــان اجلــوال املســتخدم معــه هــو‬\n‫اجلــوال الــذي ذكــره املدعــي العــام وبنــاء علــى قلــة الكميــة التــي قــام‬\n‫بترويجهــا املدعــى عليــه ولعــدم وجــود ســوابق مماثلــه لــه ونــزو ًال عــن‬\n‫احلــد األدنــى للمــادة ‪ 38‬مــن نظــام املخــدرات وبنــاء علــى املــادة ‪56 ، 53‬‬\n‫وبنــاء علــى املــادة ‪ 60‬وبنــاء علــى التقريــر الكيمــاوي وبنــاء علــى ذلــك‬\n‫كلــه فقــد حكمــت مبــا يلــي أو ًال ـ ثبــت لــدي قيــام املدعــى عليــه بترويــج‬\n‫حبتــن محظــورة وحكمــت بســجنه ملــدة ســنة وأربعــة أشــهر وجلــده مائــة‬\n‫وخمســن جلــده مفرقــة علــى ثــاث مــرات كل مــره خمســون جلــده‬\n‫بينهمــا عشــرة أيــام ودفعــه غرامــة ماليــة قدرهــا ثمانيــة آالف ‪8000‬‬\n‫ريــال ثانيـ ًا ـ منعــه مــن الســفر ملــدة ســنتني بعــد انتهــاء محكوميتــه ثالثـ ًا ـ‬\n‫مصــادرة الهاتــف اجلــوال وإلغــاء شــريحة االتصــال العائــدة للمدعــى عليــه‬\n‫وإعــادة املبلــغ احلكومــي الــذي اســتلمه املدعــى عليــه إلــى مكافحــة‬\n\n\n                                                                                            ‫‪364‬‬\n\f      ‫املخــدرات وبعــرض ذلــك عليــه وعلــى املدعــي العــام قــرر املدعــى عليــه‬\n      ‫عــدم قناعتــه وطلــب االســتئناف فأجبتــه لطلبــه وقــد ســلم نســخه مــن‬\n      ‫قــرار احلكــم يف نفــس اليــوم لتقــدمي الالئحــة االعتراضيــة وقــد أفهــم‬\n      ‫بــأن لــه مــدة ثالثــن يومـ ًا مــن تاريــخ االســتالم بعــد ذلــك يســقط حقــه يف‬\n      ‫طلــب االســتئناف وقــرر املدعــي العــام عــدم قناعتــه وطلــب االســتئناف‬\n      ‫فأجبتــه لطلبــه وقــرر بأنــه لــن يقــدم الئحــة اعتراضيــه وإمنــا يكتفــي‬\n      ‫بــأوراق املعاملــة والئحــة الدعــوى عــن واالعتــراض واهلل املوفــق اثبتــه‬\n                                                     ‫وللبيــان حــرر يف ‪1434/6/19‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد‪ ....‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n      ‫برقــم ‪ 34917746‬وتاريــخ ‪1434/7/25‬ه ـ املقيــدة لــدى احملكمــة‬\n      ‫برقــم ‪ 34/1877429‬وتاريــخ ‪1434/8/3‬ه ـ املرفــق بهــا القــرار الصــادر‬\n      ‫مــن فضيلــة القاضــي الشــيخ املســجل برقــم ‪ 34246013‬وتاريــخ‬\n      ‫‪1434/6/19‬ه ـ اخلــاص بدعوى‪/‬املدعــى العــام ضــد ‪ ..........‬يف قضيــة‬\n      ‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n      ‫فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n      ‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                        ‫وســلم حــرر يف ‪1434/8/9‬ه ـ‬\n\n\n\n\n‫‪365‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":359,"source_page_end":365,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d2d8527a5436db66b72d3fc5f50654a1eaf4770553ee3eb91739bac97c21eacc","normalized_text_hash":"b829a519d746669be447bca19c571c773632769bbca58b58d18341222bad2be2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p359-34246013"},{"id":"d2b90692-e8af-5a97-bc94-0240aa44532e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر - تستر -حتقيق ا -تعزير بالسجن واجللد والغرامة -إقامة حد املسكر على متعاطي احلشيش -تعزير باملنع والسفر -1املواد ( -الفقرة 1من املادة 53واملادة 56واملادة 60من نظام مكافحة املخدرات واملؤثرات العقلية .","document_number":"34197958","case_number":"34171997","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/24","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -تعاطي احلشيش املخدر - تستر -حتقيق ا -تعزير بالسجن واجللد والغرامة -إقامة حد املسكر على متعاطي احلشيش -تعزير باملنع والسفر -1املواد ( -الفقرة 1من املادة 53واملادة 56واملادة 60من نظام مكافحة املخدرات واملؤثرات العقلية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34197958:‬تاريخه ‪1434/4/24 :‬هـ‬\n                   ‫رقم الدعوى ‪34171997 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34238047‬تاريخه‪1434/06/12:‬هـ‬\n\n\n ‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر ‪ -‬تعاطــي احلشــيش املخــدر ‪-‬‬\n ‫تســتر ‪ -‬حتقيق ـ ًا ‪ -‬تعزيــر بالســجن واجللــد والغرامــة ‪ -‬إقامــة حــد‬\n              ‫املســكر علــى متعاطــي احلشــيش‪ -‬تعزيــر باملنــع والســفر‬\n\n\n\n\n ‫‪ -1‬املــواد ‪ ( -‬الفقــرة ‪ 1‬مــن املــادة ‪ 53‬واملــادة ‪ 56‬واملــادة ‪ 60‬مــن نظــام‬\n                                ‫مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n            ‫‪ -2‬تعميم سمو وزير الداخلية رقم ‪ 9798‬يف ‪1428/2/10‬هـ ‪.‬‬\n         ‫‪ -3‬تعميم سمو وزير الداخلية رقم ‪ 65980‬يف ‪1428/10/22‬هـ ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام ضــد املدعــى عليــه علــى شــراء و بيــع احلشــيش‬\n ‫املخــدر بقصــد االجتــار وتعاطيــه لــه‪ -‬وطلــب املدعــي العــام إثبــات مــا‬\n ‫أســند إليــه واحلكــم عليــه بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة‬\n ‫(‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ومصــادرة‬\n ‫اجلــوال املســتخدم يف اجلرميــة وإلغــاء شــريحة االتصــال وإلــزام املدعــى‬\n ‫عليــه بــرد املبلــغ احلكومــي وتعزيــره لقــاء تســتره علــى مصــدر احلشــيش‪،‬‬\n ‫حيــث إنــه مت القبــض علــى املدعــى عليــه متلبس ـ ًا بعــد ورود معلومــات‬\n ‫عنــه مفادهــا أنــه يقــوم بترويــج احلشــيش املخــدر ‪ ،‬صــادق املدعــى عليــه‬\n\n                                                                                         ‫‪366‬‬\n\f      ‫مبــا هــو منســوب إليــه ‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــر‬\n      ‫املدعــى عليــه بالســجن واجللــد واملنــع مــن الســفر والغرامــة ومصــادرة‬\n      ‫اجلــوال وإلغــاء شــريحته وإقامــة حــد املســكر ‪ .‬صــدق احلكــم مــن‬\n                                                          ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫اجلزائيــة‬\n         ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة‬\n      ‫باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة يف محافظــة االحســاء املكلــف برقــم ‪ 34171997‬وتاريــخ‬\n      ‫‪ 1434/04/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34917867‬وتاريــخ‬\n      ‫‪ 1434/04/15‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1434/04/24‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر املدعــي العــام ‪....‬‬\n      ‫املعمــد بالترافــع أمــام هــذه احملكمــة مبوجــب خطــاب ســعادة رئيــس‬\n      ‫دائــرة التحقيــق واالدعــاء العــام مبحافظــة االحســاء ذي الرقــم ‪13415‬‬\n      ‫والتاريــخ ‪ 1433/12/01‬ه ـ وادعــى ضــد احلاضــر معــه ‪ ....‬ســعودي‬\n      ‫ا يف دعــواه فباإلطــاع‬  ‫اجلنســي مبوجــب الســجل املدنــي رقــم ‪ ......‬قائ ـ ً‬\n      ‫علــى محضــر القبــض املعــد مــن قبــل إدارة مكافحــة املخــدرات تبــن‬\n      ‫أنــه بتاريــخ ‪1434/2/17‬ه ـ توفــرت معلومــات لــدى مكافحــة املخــدرات‬\n      ‫مــن مصادرهــا الســرية عــن قيــام املدعــى عليــه بترويــج احلشــيش املخــدر‬\n      ‫ومت عمــل اخلطــة الالزمــة لإلطاحــة باملدعــى عليــه باجلــرم املشــهود ومت‬\n      ‫متكــن املصــدر مــن االتصــال باملدعــى عليــه علــى جوالــه رقــم (‪)....‬‬\n      ‫وطلــب منــه بيعــه احلشــيش املخــدر فوافــق املدعــى عليــه علــى ذلــك وطلــب‬\n      ‫منــه احلضــور إليــه يف حــي ‪ .........‬ويف الوقــت واملــكان املتفــق عليــه ذهــب‬\n\n‫‪367‬‬\n\f‫املصــدر وركــب املدعــى عليــه معــه واجتهــوا إلــى حــي ‪ ............‬ومــن ثــم‬\n‫الرجوع حلي ‪ ............‬ثم نزل املدعى عليه من السيارة يف أحد األماكن‬\n‫بحــي ‪ ............‬ثــم عــاد املدعــى عليــه وســلم املصــدر قطعــة مــن احلشــيش‬\n‫املخــدر تــزن (‪ )3،4‬ثالثــة جرامــات وأربعــة مــن العشــرة مــن اجلــرام وبعــد‬\n‫القبــض علــى املدعــى عليــه أقــر بصحــة واقعــة الضبــط واســتالمه للمبلــغ‬\n‫احلكومــي املرقــم وبتفتيشــه لــم يعثــر علــى املبلــغ احلكومــي املرقــم ولــم‬\n‫يعثــر معــه علــى أي شــي مــن املمنوعــات وعثــر علــى جــوال مــن نــوع ‪......‬‬\n‫وشــريحة اتصــال رقــم (‪ )...‬واملســتخدم يف عمليــة الترويــج (صــدر أمــر‬\n                              ‫بحجــز اجلــوال والشــريحة متهيــد ًا ملصادرتهمــا)‪.‬‬\n‫وباســتجواب املدعــى عليــه ‪ /‬أقــر بتلقيــه اتصــا ًال مــن املصــدر علــى جواله‬\n‫املذكــور أعــاه وطلــب منــه قطعــة مــن احلشــيش املخــدر فطلــب منــه‬\n‫احلضــور إليــه وســلمه قطعــة مــن احلشــيش املخــدر كان قــد اشــتراها‬\n‫مــن شــخص لــم يذكــر أســمه‪ ،‬كمــا أقــر بتعاطيــه للحشــيش املخــدر‬\n                                                                       ‫يف الســابق ‪.‬‬\n‫وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪ 959‬ك ش) لعــام‬\n‫‪1434‬ه ـ ايجابيــة عينــة القطعــة املضبوطــة ملــادة احلشــيش احلشــيش‬\n‫املخــدر احملظــور واملــدرج يف اجلــدول (‪ )1‬فئــة (أ) مــن نظــام مكافحــة‬\n                                                  ‫املخــدرات واملؤثــرات العقليــة‪.‬‬\n‫وقــد أســفر التحقيــق عــن توجيــه االتهــام ل ـ ‪ .... /‬بشــراء وبيــع قطعــة‬\n‫مــن احلشــيش املخــدر تــزن (‪ )3،4‬ثالثــة جرامــات وأربعــة مــن العشــرة‬\n‫مــن اجلــرام بقصــد االجتــار وتعاطيــه لنوعــه يف الســابق ‪ ،‬وتســتره علــى‬\n                                                         ‫مصــدر احلشــيش املخــدر‪.‬‬\n                                                   ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n\n\n                                                                                       ‫‪368‬‬\n\f      ‫‪ -1‬مــا جــاء يف أقوالــه املدونــة علــى الصفحــة رقــم (‪ )2-1‬مــن دفتــر‬\n                                                                             ‫التحقيــق لفــه ‪.‬‬\n      ‫‪ -2‬محضــر القبــض املنــوه عنــه املــدون علــى الصفحــة رقــم (‪ )12‬املرفــق‬\n                                                                               ‫لفــة رقــم (‪. )9‬‬\n                                            ‫‪ -3‬التقرير الكيماوي املرفق على اللفة‪.‬‬\n      ‫وحيث إن ما أقدم عليه املذكور ‪ ،‬وهو بكامل أهليته املعتبرة شرعاً‪،‬‬\n      ‫فعــل محــرم ومعاقــب علي ــه شــرع ًا ونظامـ ًا يف ضــوء الفقــرة الثانيــة م ــن‬\n      ‫املــادة الثالثــة م ــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n      ‫باملرســوم امللكــي الكــرمي (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ أطلــب إثبــات‬\n                                            ‫مــا اســند إليــه واحلكــم عليــه مبــا يلــي ‪- :‬‬\n      ‫‪-1‬العقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )38‬مــن النظــام املشــار‬\n      ‫إليــه لقــاء مــا أســند إليــه ‪ ،‬لكونهــا العقوبــة األشــد اســتناد ًا للفقــرة‬\n                                            ‫األولــى مــن املــادة (‪ )62‬مــن ذات النظــام‪.‬‬\n      ‫‪-2‬احلكــم مبصــادرة جهــاز اجلــوال املوصــوف يف القــرار املســتخدمة يف‬\n      ‫اجلرميــة وفــق املــادة (‪ )53‬مــن نفــس النظــام وإيــداع املبالــغ يف حســاب‬\n      ‫ـاء علــى تعميــم وزيــر الداخليــة رقــم (‪ )74‬وتاريــخ‬         ‫إدارة املخــدرات بنـ ً‬\n                                                                          ‫‪1421/2/18‬ه ـ ‪.‬‬\n      ‫‪-3‬إلغــاء شــرائح االتصــال املوصوفــة يف القرار وفــق برقية وزير الداخلية‬\n                                ‫رقم (‪ )9798/4/5/1‬وتاريخ ‪1428/2/10-9‬هـ‪.‬‬\n      ‫‪-4‬إلزامــه بــرد املبلــغ احلكومــي العائــد ملكافحــة املخــدرات باألحســاء‬\n      ‫وقــدره (‪ )100‬مائــة ريــال اســتناد َا لتعميــم وزيــر الداخليــة رقــم (‪)65980‬‬\n                                                           ‫وتاريــخ ‪1422/10/23-22‬هـ‪.‬‬\n      ‫‪-5‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )56‬مــن النظــام مبنعــه‬\n\n\n‫‪369‬‬\n\f                                                                        ‫مــن الســفر‪.‬‬\n             ‫‪ _6‬بعقوبة تعزيرية لقاء تستره على مصدر احلشيش املخدر ‪.‬‬\n                                                                        ‫هذه دعواي‬\n‫ا مــا ذكــره املدعــي العــام مــن أننــي‬  ‫وبســؤال املدعــى عليــه أجــاب قائ ـ ً‬\n‫قمــت ببيــع قطعــة مــن احلشــيش املخــدر تــزن (‪ )3،4‬ثالثــة جرامــات‬\n‫وأربعــة مــن العشــرة مــن اجلــرام مببلــغ وقــدره مائــة ريــال بقصــد الترويــج‬\n‫فهــذا صحيــح حيــث إنــه مت االتصــال بــي علــى جوالــي رقــم ‪ ....‬واتفقــت‬\n‫معهــم علــى أن يحضــروا إلــي يف حــي ‪ ............‬وكذلــك مــا ذكــره‬\n‫املدعــي العــام مــن أنــه بتاريــخ ‪1434/2/17‬ه ـ قبــض علــي فهــذا صحيــح‬\n‫وكذلــك مــا ذكــره املدعــي العــام مــن أننــي أتعاطــى احلشــيش املخــدر‬\n‫فصحيــح وأمــا مــا ذكــره املدعــي العــام مــن أننــي تســترت علــى مصــدر‬\n‫احلشــيش فهــذا غيــر صحيــح حيــث إننــي أخبرتهــم بأننــي اشــتريتها مــن‬\n‫شــخص ال أعرفــه وأنــا تائــب ونــادم هكــذا أجــاب وبســؤال املدعــي‬\n‫العــام هــل لديــه بينــة علــى أن املدعــى عليــه تســتر علــى مصــدر احلشــيش‬\n‫ا ليــس لــدي ســوى مــا ذكرتــه يف املعاملــة هكــذا أجــاب‬          ‫أجــاب قائ ـ ً‬\n‫وبالرجــوع إلــى املعاملــة وجــد فيهــا علــى لفــة رقــم ‪ 12‬صحيفــة رقــم ‪2‬‬\n‫أقــوال املدعــى عليــه تبــن أنــه أخبرهــم بــأن مــن أعطــاه احلشــيش هــو‬\n‫شــخص مينــي ال يعــرف اســمه وهــي نفــس اإلجابــة التــي ذكرهــا لدينــا‬\n‫يف مجلــس احلكــم كمــا جــرى اإلطــاع علــى املعاملــة وجــد فيهــا‬\n‫علــى لفــة رقــم ‪ 24‬التقريــر الكيمــاوي الشــرعي رقــم ( ‪ 959‬ك ش )‬\n‫لعــام ‪1434‬ه ـ املتضمــن إيجابيــة العينــة املرســلة ملــادة احلشــيش املخــدر‬\n‫واســتهالك جميــع العينــات املرســلة يف التحليــل ا‪.‬ه ـ فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة وإقــرار املدعــى عليــه بترويــج قطعــة مــن احلشــيش‬\n\n\n                                                                                        ‫‪370‬‬\n\f      ‫املخــدر تــزن (‪ )3،4‬ثالثــة جرامــات وأربعــة مــن العشــرة من اجلــرام بقصد‬\n      ‫االجتــار وتعاطيــه لنوعــه يف الســابق وحيــث إن املدعــى عليــه أنكــر‬\n      ‫تســتره علــى مصــدره وحيــث إن املدعــي العــام لــم يحضــر بينــة علــى ذلــك‬\n      ‫وللتقريــر الكيمــاوي الشــرعي ولنهــي النبــي صلــى اهلل عليــه وســلم عــن‬\n      ‫كل مســكر ومفتــر كمــا يف حديــث أم ســلمه رضــي اهلل عنهــا وحيــث‬\n      ‫إن مــا أقــدم عليــه املدعــى عليــه ضــرب مــن ضــروب اإلفســاد بــاألرض‬\n      ‫وحيــث إن احلشــيش يشــترك مــع اخلمــر يف منــاط احلكــم وحيــث إن‬\n      ‫العقوبــة األخــف تدخــل يف العقوبــة األشــد لذلــك كلــه ثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه بترويــج قطعــة مــن احلشــيش املخــدر تــزن (‪ )3،4‬ثالثــة‬\n      ‫جرامــات وأربعــة مــن العشــرة مــن اجلــرام بقصــد االجتــار وتعاطيــه لنوعــه‬\n      ‫يف الســابق ولــم يثبــت لــدي تســتره علــى مصــدر احلشــيش وحكمــت‬\n      ‫عليــه مبــا يلــي ‪ :‬أو ًال ‪ :‬جلــد املدعــى عليــه ثمانــون جلــدة دفعــة واحــدة حــد‬\n      ‫املســكر ثاني ـ ًا ‪ :‬ســجن املدعــى عليــه مــدة ســنتني حتتســب منهــا مــدة‬\n      ‫بقائــه بالســجن بخصــوص هــذه القضيــة وجلــد املدعــى عليــه مائتــن‬\n      ‫جلــدة تعزيــر ًا مفرقــة علــى أربــع دفعــات كل دفعــة خمســن جلــدة بــن‬\n      ‫كل دفعــة واألخــرى مــدة أســبوعني وبغرامــة ماليــة قدرهــا ألفــن ريــال‬\n      ‫وقــد نزلــت عــن العقوبــة املقــررة نظامــا وذلــك مبوجــب املــادة (‪ )60‬مــن‬\n      ‫نظامــا مكافحــة املخــدرات نظــرا لقلــة الكميــة ولعــدم وجــود ســوابق‬\n      ‫علــى املدعــى عليــه ثالثـ ًا ‪ :‬منــع املدعــى عليــه مــن الســفر خــارج اململكــة‬\n      ‫مــدة ســنتني بعــد تنفيــذ مــدة محكوميتــه وذلــك مبوجــب املــادة ‪ 56‬مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة رابع ـ ًا ‪ :‬مصــادرة جهــاز‬\n      ‫اجلــوال الــذي يحمــل الرقــم (‪ )....‬اســتناد ًا للفقــرة رقــم (‪ )1‬مــن املــادة‬\n      ‫(‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وإيــداع املبالــغ‬\n\n\n‫‪371‬‬\n\f‫ـاء علــى تعميــم وزيــر‬\n                       ‫يف حســاب اإلدارة العامــة ملكافحــة املخــدرات بنـ ً‬\n‫الداخليــة رقــم (‪ )47‬وتاريــخ ‪1421/2/18‬ه ـ خامس ـ ًا ‪ :‬إلغــاء شــريحة‬\n‫هاتــف اجلــوال املنــوه عنهــا رقــم ‪ ....‬لقــاء اســتخدامها يف التنســيق لعمليــة‬\n‫ال اســتناد ًا لتعميــم صاحــب‬   ‫الترويــج وعــدم تزويــده بــذات الرقــم مســتقب ً‬\n‫الســمو امللكــي وزيــر الداخليــة رقــم ‪ 9798‬وتاريــخ ‪1428/02/10‬ه ـ‬\n‫سادسـ ًا ‪ :‬إلــزام املدعــى عليــه بإعــادة اجلــزء املتبقــي مــن املبلــغ احلكومــي‬\n‫املرقــم املوصــوف يف القــرار وقــدره (‪ )100‬مائــة ريــال إســتناد ًا لتعميــم‬\n‫صاحــب الســمو امللكــي وزيــر الداخليــة رقــم (‪ )65980‬وتاريــخ ‪-22‬‬\n‫‪1428/10/ 23‬ه ـ ســابع ًا ‪ :‬رد دعــوى املدعــي العــام بخصــوص معاقبــة‬\n‫املدعــى عليــه عقوبــة تعزيريــة لقــاء تســتره علــى مصــدر احلشــيش لعــدم‬\n‫ثبوتهــا وبــه حكمــت وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليــه‬\n‫قــرر املدعــي العــام اعتراضــه علــى احلكــم وطلــب رفــع املعاملــة إلــى‬\n‫محكمــة اإلســتئناف بــدون الئحــة فأجبتــه لطلبــه وأمــا املدعــى عليــه‬\n‫قــرر قناعتــه بــه وبــه ختمــت اجللســة يف متــام الســاعة ‪ 10 : 00‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                    ‫حــرر يف ‪ 1434/04/24‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق‪ 1434/06/26‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09 : 45‬وفيهــا عــادت املعاملــة مــن محكمــة‬\n‫اإلســتئناف باملنطقــة الشــرقية برقــم ‪ 341180477‬يف ‪1434/06/20‬ه ـ‬\n‫واملتعلقــة بدعــوى املدعــي العــام ضــد ‪ ....‬املــدون هويتــه ســابق ًا يف‬\n‫قضيــة مخــدرات وبرفقهــا القــرار الشــرعي برقــم ‪ 34238047‬وتاريــخ‬\n‫‪1434/06/12‬ه ـ الصــادر مــن الدائــرة اجلزائيــة األولــى مبحكمــة‬\n‫االســتئناف باملنطقــة الشــرقية املتضمــن إنــه بدراســة القــرار وصــورة‬\n\n\n                                                                                        ‫‪372‬‬\n\f      ‫ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم قاضــي اســتئناف‬\n      ‫د‪ ......‬ختمــه وتوقيعــه قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n      ‫‪ .....‬ختمــه وتوقيعــه وبــه ختمــت اجللســة يف متــام الســاعة ‪ 09 : 50‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                      ‫حــرر يف ‪ 1434/06/26‬ه ـ‬\n\n\n\n\n‫‪373‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":366,"source_page_end":373,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"351cd508214245a87014c39167f7d1997c3900256af28a013861e942c7704d95","normalized_text_hash":"991002e8bccad54d89788a1d3b541b433d6cc4606ecd55c8e12370e3afa09190","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p366-34197958"},{"id":"de7d84b4-7a01-512e-a44b-a2195061db97","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -تعاطي احلشيش املخدر - تعزير بالسجن واجللد والغرامة -اإلقرار -رجوع عن إقرار -اخذ","document_number":"34201368","case_number":"34172437","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/9","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -تعاطي احلشيش املخدر - تعزير بالسجن واجللد والغرامة -اإلقرار -رجوع عن إقرار -اخذ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34201368 :‬تاريخه ‪1434/04/9 :‬هـ‬\n                    ‫رقم الدعوى ‪34172437 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34210091‬تاريخه‪1434/05/08:‬هـ‬\n\n\n ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬تعاطــي احلشــيش املخــدر ‪-‬‬\n ‫تعزيــر بالســجن واجللــد والغرامــة ‪ -‬اإلقــرار ‪ -‬رجــوع عــن إقــرار ‪ -‬اخــذ‬\n                                                                        ‫تعهــد‪.‬‬\n\n\n\n                  ‫املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام ضــد املدعــى عليــه باتهامه بترويــج احلبوب احملظورة‬\n ‫وتعاطيــه احلشــيش املخــدر واتهامــه باالحتيــال ‪ ،‬وطلــب املدعــي العــام‬\n ‫إثبــات إدانتــه مبــا أســند إليــه و احلكــم عليــه بعقوبــة الســجن و اجللــد‬\n ‫والغرامــة و املنــع مــن الســفر و إثبــات إدانتــه ببيــع مــا أوهــم أنهــا حبــوب‬\n ‫محظــورة احتيــا ًال مبقابــل و إلغــاء الشــريحة الهاتفيــة املســتخدمة يف‬\n ‫اجلرميــة و عــدم صرفهــا لنفــس املشــترك ورد املبلــغ املفقــود و تشــديد‬\n ‫العقوبــة لترويجــه احلبــوب احملظــورة‪ ،‬حيــث إنــه مت القبــض علــى‬\n ‫املدعــى عليــه بعــد إخباريــة مفادهــا أن املدعــى عليــه يقــوم بترويــج‬\n ‫احلبــوب احملظــورة و مت التنســيق مــع أحــد املصــادر الســرية لإليقــاع‬\n ‫باملدعــى عليــه متلبس ـ ًا و تقابــل املصــدر مــع املدعــى عليــه و متــت عمليــة‬\n ‫االســتالم و التســليم و مت القبــض علــى املدعــى عليــه بعــد مــدة و مت‬\n ‫تعــرف أعضــاء الفرقــة القابضــة علــى املدعــى عليــه ‪ ،‬كمــا أقــر املدعــى‬\n                                                                                         ‫‪374‬‬\n\f      ‫عليــه بالدعــوى وأنكــر تعاطــي احلشــيش‪ ،‬بنــاء علــى مــا تقــدم حكمــت‬\n      ‫احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد والغرامــة واملنــع مــن‬\n      ‫الســفر ومصــادرة الهاتــف اجلــوال وإلغــاء الشــريحة وأخــذ التعهــد القــوي‬\n      ‫بعــدم العــودة ملــا بــدر منــه وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫اجلزائيــة بحائــل املكلــف برقــم ‪ 34172437‬وتاريــخ‬       ‫ّ‬         ‫احملكمــة‬\n      ‫‪1434/04/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34906011‬وتاريــخ‬\n      ‫‪1434/04/14‬ه ـ ففــي يــوم اإلثنــن املوافــق ‪1434/04/29‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 10 :00‬وفيهــا قــدم املدعــي العــام ‪ ......‬الئحــة دعــوى‬\n      ‫عامــة يف القضيــة رقــم (‪3402600088‬ح‪ )1‬وفيهــا بصفتــي مدعي ـ ًا‬\n      ‫عام ـ ًا يف دائــرة اإلدعــاء العــام بفــرع الهيئــة مبنطقــة حائــل أدعــي علــى‬\n      ‫‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).......‬قبــض عليــه‬\n      ‫بتاريــخ ‪1434/3/1‬ه ـ فإنــه باالطــاع علــى محضــر البــاغ املعــد مــن‬\n      ‫قبــل مكافحــة املخــدرات مبنطقــة حائــل بتاريــخ ‪1433/12/19‬ه ـ تبــن‬\n      ‫تبلغهــم مــن أحــد مصادرهــم الســرية عــن وجــود شــخص يدعــى ‪، ......‬‬\n      ‫يســكن بحــي (‪ )........‬يقــوم بترويــج احلبــوب احملظــورة واســتعد املصــدر‬\n      ‫لإلطاحــة بــه باجلــرم املشــهود و باالطــاع علــى محضــر البــاغ املعــد‬\n      ‫بتاريــخ ‪1434/1/25‬ه ـ تبــن تبلغهــم مــن أحــد مصادرهــم الســرية عــن‬\n      ‫وجــود شــخص يدعــى ‪ ،....‬يقــوم بترويــج احلبــوب احملظــورة ويســكن‬\n      ‫بحــي (‪ ،)......‬واســتعد املصــدر لالطاحــة بــه باجلــرم املشــهود وباالطــاع‬\n\n‫‪375‬‬\n\f‫علــى محضــر إيضاحــات الواقعــة املتضمــن لعمليــة الشــراء مــن املــروج‬\n‫(املدعــى عليــه) املعــد بتاريــخ ‪1433/12/19‬ه ـ ويف متــام الســاعة الرابعــة‬\n‫ـاء مت متكــن املصــدر مــن االتصــال علــى املدعــى عليه على‬        ‫والنصــف مسـ ً‬\n‫جــوال رقــم (‪ ).....‬وبعــد الســام عليــه طلــب منــه حبــوب محظــورة بقيمــة‬\n‫مائــة ريــال فوافــق علــى ذلــك وطلــب مــن املصــدر احلضــور إلــى منزلــه يف‬\n‫حــي (‪ ).......‬وإنهــاء املكاملــة وكان ذلــك علــى مســمع مــن طاقــم الفرقــة‬\n‫ـراء للذمــة وتزويــده باملبلــغ احلكومــي‬ ‫ومت تفتيــش املصــدر وســيارته إبـ ً‬\n‫املرقــم وحتــرك املصــدر حتــت أنظــار الفرقــة وعنــد وصولــه للموقــع‬\n‫احملــدد شــوهد املدعــى عليــه واقف ـ ًا أمــام منزلــه وعنــد توقــف املصــدر‬\n‫بســيارته ركــب معــه املدعــى عليــه وبعــد أقــل مــن دقيقــة ترجــل مــن‬\n‫الســيارة ودخــل داخــل املنــزل وكان ذلــك أمــام أنظــار الفرقــة القابضــة‪،‬‬\n‫ثــم حتــرك املصــدر بســيارته ولــم يغــب عــن أنظــار الفرقــة حتــى توقــف‬\n‫وقــام بتســليم قائــد الفرقــة مــا قــد اســتلمه هــو ســابق ًا مــن املدعــى عليــه‬\n‫وتبــن أنهــا (‪ )3‬ثــاث حبــات بيضــاء اللــون حتمــل عالمــة الكبتاجــون‬\n‫يشــتبه أن تكــون مــن احلبــوب احملظــورة (ثبــت إيجابيتهــا) وحرص ـ ًا‬\n‫علــى عــدم انكشــاف املصــدر مت تأجيــل القبــض عليــه وباالطــاع‬\n‫علــى محضــر إيضاحــات الواقعــة املتضمــن لعمليــة الشــراء مــن املــروج‬\n‫( املدعــى عليــه) املعــد بتاريــخ ‪1434/1/25‬ه ـ ويف متــام الســاعة الرابعــة‬\n‫والنصــف عصــر ًا مت متكــن املصــدر مــن االتصــال علــى جــوال املدعــى‬\n‫عليــه رقــم (‪ )...‬وبعــد الســام طلــب مــن املصــدر احلضــور ملنزلــه بحــي‬\n‫ال‪ ...‬وأنهــى املكاملــة وكان ذلــك علــى مســمع مــن طاقــم الفرقــة ومت‬\n‫ـراء للذمــة ومت تزويــده باملبلــغ احلكومــي‬ ‫تفتيــش املصــدر وســيارته إبـ ً‬\n‫املرقــم وتكليــف أحــد رجــال األمــن مبرافقــة املصــدر ملشــاهدة عمليــة‬\n\n\n                                                                                         ‫‪376‬‬\n\f      ‫االســتالم والتســليم وحتــرك املصــدر ورجــل األمــن حتــت أنظــار الفرقــة‬\n      ‫وعنــد وصولهمــا للموقــع احملــدد مــن قبــل املدعــى عليــه شــوهد واقف ـ ًا‬\n      ‫أمــام منزلــه وقــام املصــدر بتســليمه املبلــغ احلكومــي املرقــم وقــام‬\n      ‫املدعــى عليــه بتســليمه الكميــة املتفــق عليهــا علــى مــرأى مــن رجــل‬\n      ‫األمــن املرافــق وحتــركا وقــام املصــدر بإعطــاء قائــد الفرقــة (‪ )3‬ثــاث‬\n      ‫حبــات بيضــاء اللــون حتمــل عالمــة الكبتاجــون يشــتبه بــأن تكــون مــن‬\n      ‫احلبــوب احملظــورة (ثبــت ســلبيتها) ومت تأجيــل القبــض عليــه حرص ـ ًا‬\n      ‫علــى عــدم انكشــاف املصــدر وباالطــاع علــى احملضــر املعــد بتاريــخ‬\n      ‫ـاء متــت مشــاهدة‬ ‫‪1434/3/1‬ه ـ ويف متــام الســاعة العاشــرة والنصــف مسـ ً‬\n      ‫املدعــى عليــه عنــد أحــد احملــات التجاريــة يف حــي ‪ ............‬بالقــرب‬\n      ‫مــن منزلــه ومت التوجــه إليــه وعنــد مشــاهدته لرجــال األمــن بانــت عليــه‬\n      ‫عالمــات االرتبــاك وبعــد الســيطرة عليــه وتفتيشــه لــم يعثــر معــه علــى‬\n      ‫أي شــيء مــن املمنوعــات وتبــن أنــه‪ ..... /‬وعثــر معــه علــى جــوال ‪.....‬‬\n      ‫أبيــض ليــس هــو اجلــوال املســتخدم يف عمليــة الترويــج ولــم يعثــر علــى‬\n      ‫املبلــغ احلكومــي املرقــم ومت عــرض املدعــى عليــه علــى العضــو املرافــق‬\n      ‫للمصــدر حــن شــراء املخــدرات مــن هــذا املــروج وأفــاد العضــو بــأن ‪ ...‬هــو‬\n      ‫مــن قــام بعمليــة البيــع يف ‪ 1/25‬و وباالطــاع علــى محضــر التعــرف املعــد‬\n      ‫بتاريــخ ‪1434/3/3‬ه ـ فقــد تعــرف املــازم أول رقــم (‪ )... ..‬والرقيــب رقــم‬\n      ‫(‪ )...‬علــى املدعــى عليــه واتضــح لهمــا بأنــه هــو مــن قــام بعمليــة االســتالم‬\n                                                   ‫والتســليم بتاريــخ ‪1433/12/19‬ه ـ‬\n      ‫وباســتجوابه بشــأن القضيــة رقــم (‪340260088‬ح‪ )1‬أقــر ببيــع ثــاث‬\n      ‫حبــات ولكنــه نفــى أن تكــون محظــورة وإمنــا كانــت حبــوب حساســية‬\n      ‫وقــام بنقــش قوســن متقابلــن علــى كل حبــة ليوهــم مــن يريــد الشــراء‬\n\n\n‫‪377‬‬\n\f‫بأنهــا حبــوب كبتاجــون وأنــه قــام بهــذه العمليــة ثــاث مــرات وأقــر‬\n‫بتعاطيــه للحشــيش املخــدر و أفــاد مبصــدر ماقــام ببيعــه وباســتجوابه‬\n‫بشــأن القضيــة رقــم (‪340260091‬ح‪ )1‬أقــر ببيــع ثــاث حبــات محظــورة‬\n‫وأقــر بــأن اجلــوال ذو الرقــم (‪ )............‬يعــود لــه و أفــاد مبصــدر مــا‬\n‫قــام ببيعــه وق ــد أثب ــت الـتقـريـ ــر الكـيـميائـ ــي أحــراز رقــم (‪)1717‬‬\n‫الص ــادر م ــن املركــز اإلق ــليمي ملراقبــة السم ــوم مب ــنطقة القص ــيم‬\n‫بـرق ــم (‪/2799‬م س‪ )45/65/‬وتاريــخ ‪1433/12/28‬ه ـ إيجابيــة (‪)3‬‬\n‫الثــاث حبــات ملــادة االمفيتامــن وهــو مــن املــواد الكيميائيــة املنبهــة‬\n‫للجهــاز العصبــي املركــزي واملدرجــة بجــدول املؤثــرات العقليــة رقــم‬\n‫(‪ )2‬وفئــة (ب) التــي عناهــا تعميــم وزارة الصحــة رقــم ‪911/27‬س يف‬\n‫‪1427/4/12‬ه ـ واملبنــي علــى تعميــم وزارة الداخليــة رقــم ‪89400/19‬‬\n‫يف ‪1426/10/25‬هـ و أثب ــت الـتقـريـ ــر الكـيـميائـ ــي أحراز رقم (‪)158‬‬\n‫الص ــادر م ــن املركــز اإلق ــليمي ملراقبــة السم ــوم مب ــنطقة القص ــيم‬\n‫بـرق ــم (‪/323‬م س‪ )45/65/‬وتاريــخ ‪1434/2/6‬ه ـ ســلبية (‪ )3‬الثــاث‬\n‫حبــات ألشــباه القلويــدات املخــدرة ومشــتقات حمــض الباربيتوريــك و‬\n‫االمفيتامــن وقــد أســفر التحقيــق معــه عــن إتهامــه بترويــج (‪ )3‬ثــاث‬\n‫حبــات مــن حبــوب االمفيتامــن املنبهــة واحملظــورة عــن طريــق البيــع‬\n‫وتعاطيــه للحشــيش املخــدر‪ . ،‬واتهامــه ببيــع مــا أوهــم أنهــا حبــوب‬\n‫محظــورة احتيــا ًال مبقابــل وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬اعترافــه‬\n‫املــدون علــى الصفحــة رقــم (‪ )2.1‬مــن دفتــر التحقيــق لفــة رقــم (‪، )15‬‬\n‫‪ -2‬اعترافــه املــدون علــى الصفحــة رقــم (‪ )2.1‬مــن دفتــر التحقيــق لفــة‬\n‫رقــم (‪ -3 ، )36‬مــا جــاء يف محضــر الشــراء املســبق املنــوه عنــه واملــدون‬\n‫علــى الصفحــة رقــم (‪ )11‬لفــة رقــم (‪ -4 ، )1‬مــا جــاء يف محضــر الشــراء‬\n\n\n                                                                                    ‫‪378‬‬\n\f      ‫املســبق املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪ )11‬لفــة رقــم (‪، )9‬‬\n      ‫‪ -5‬مــا جــاء يف محضــر القبــض والتفتيــش املنــوه عنــه واملــدون علــى‬\n      ‫الصفحــة رقــم (‪ )12‬لفــة رقــم (‪ -6 ، )1‬مــا جــاء يف محضــر التعــرف‬\n      ‫املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪ )13‬لفــة رقــم (‪ -7 ، )9‬مــا جــاء‬\n      ‫يف التقريريــن الكيميائيــن املشــار إليهمــا لفــة رقــم (‪ ، )13.4‬وحيــث‬\n      ‫إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرعا ونظامـ ًا‬\n      ‫أطلــب إثبــات إدانتــه بترويــج (‪ )3‬ثــاث حبــات مــن حبــوب االمفيتامــن‬\n      ‫املنبهــة واحملظــورة عــن طريــق البيــع وتعاطيــه للحشــيش املخــدر‪،‬‬\n      ‫واحلكــم عليــه مبــا يلــي‪ -1 :‬الســجن و اجللــد و الغرامــة اســتناد ًا للفقــرة‬\n      ‫(‪ )1‬مــن املــادة (‪ -2 .)38‬املنــع مــن الســفر اســتناد ًا للفقــرة (‪ )1‬مــن املــادة‬\n      ‫(‪ -3.)56‬تطبيــق العقوبــة األشــد اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪.)62‬‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬وإثبــات إدانتــه ببيــع‬\n      ‫مــا أوهــم أنهــا حبــوب محظــورة احتيــا ًال مبقابــل واحلكــم عليــه بعقوبــة‬\n      ‫تعزيريــة و إلغــاء الشــريحة الهاتفيــة املســتخدمة يف اجلرمية رقــم (‪)............‬‬\n      ‫وعــدم صرفهــا لنفــس املشــترك وفقـ ًا لبرقيــة ســمو وزيــر الداخليــة رقــم‬\n      ‫(‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ ورد املبلــغ املفقــود اســتناد ًا لتعميــم‬\n      ‫ســمو وزيــر الداخليــة رقــم (‪ )65980/4/5/1‬وتاريــخ ‪1428/10/23‬هــ‪.‬‬\n      ‫وتشــديد العقوبــة عليــه لترويجــه حبــوب االمفيتامــن املنبهــة واحملظــورة‬\n      ‫ملــا لهــا مــن أثــر ســيء علــى الفــرد واملجتمــع أمني ـ ًا واجتماعي ـ ًا وصحي ـ ًا‬\n      ‫وفقـ ًا لتعميــم وزيــر الداخليــة رقــم (‪2/8346/5/1‬ش) يف ‪1427/2/8‬ه ـ‬\n      ‫ا مــا ذكــره املدعــي‬    ‫وبــاهلل التوفيــق وبســؤال املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫ا وقــد بعــت ثــاث حبــات‬      ‫العــام يف دعــواه كلــه صحيــح جملــة وتفصي ـ ً‬\n      ‫مــن احلبــوب املخــدرة وهــذه أول مــرة أقــوم فيهــا ببيــع احلبــوب املخــدرة‬\n\n\n‫‪379‬‬\n\f‫وأمــا املــرة الثانيــة فهــي حبــوب حساســية واجلــوال (‪ ).....‬عائــد لــي‬\n‫شــخصي ًا وأنــا تائــب ونــادم علــى مــا حصــل منــي وأمــا اســتعمال احلشــيش‬\n‫املخــدر فهــو غيــر صحيــح بهــذا أجــاب وبطلــب البينــة مــن املدعــي العــام‬\n‫علــى قيــام املدعــى عليــه بتعاطــي احلشــيش قــال بينتــي اعترافــه حتقيقـ ًا‬\n‫املــدون علــى صفحــة (‪ )2-1‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪)31‬‬\n‫وليــس لــدي بينــة ســواه وبعــرض هــذا اإلقــرار علــى املدعــى عليــه قــال‬\n‫مــا تضمنــه اإلقــرار مــن قيامــي باســتخدام احلشــيش املخــدر فهــذا غيــر‬\n‫صحيــح بهــذا أجــاب فبعــد الدعــوى واإلجابــة واإلطــاع علــى أوراق‬\n‫املعاملــة ومنهــا التقريريــن الكيميائيــن املشــار إليهمــا يف الدعــوى‬\n‫العامــة واملوافقــن ملــا فيهــا ولرجــوع املدعــى عليــه عــن إقــراره لــدى جهــة‬\n‫التحقيــق بتعاطــي احلشــيش املخــدر وليــس للمدعــي العــام بينــة ســوى‬\n‫إقــراره وإلقــرار املدعــى عليــه مبــا نســب إليــه دون مراوغــة ولصغــر ســنه‬\n                                                    ‫وخلــو ســجله مــن الســوابق‬\n‫وملــا جــاء يف املــادة الســتني مــن نظــام مكافحــة املخــدرات مــن أنــه‬\n‫للمحكمــة النــزول عــن احلــد األدنــى مــن الســجن إذا رأت يف القضيــة مــا‬\n‫يبعــث علــى االعتقــاد بــأن املتهــم لــن يعــود ملخالفــة أحــكام هــذا النظــام‬\n‫لذلــك كلــه فإنــه لــم يثبــت لــدي قيــام املدعــى عليــه بتعاطــي احلشــيش‬\n‫املخــدر وثبــت لــدي إدانتــه ببيــع عــدد (‪ )3‬ثــاث حبــات مــن حبــوب‬\n‫اإلمفيتامــن املنبهــة واحملظــورة بقصــد الترويــج وهــذا الترويــج للمــرة‬\n‫األولــى وإدانتــه ببيــع مــا أوهــم أنهــا حبــوب محظــورة احتيــا ًال مبقابــل‬\n‫وحكمــت بتعزيــره مبــا يلــي أو ًال ‪ :‬ســجنه ثــاث ســنوات مــن حــن إيداعه‬\n‫التوقيــف علــى ذمــة هــذه القضيــة ‪ ،‬ثانيـ ًا ‪ :‬جلــده ثالثمائــة جلــدة مفرقــة‬\n‫علــى ســت دفعــات يف مــكان عــام وأن يكــون بــن الدفعــة واألخــرى‬\n\n\n                                                                                       ‫‪380‬‬\n\f      ‫مــا ال يقــل عــن أســبوع ‪ ،‬ثالث ـ ًا ‪ :‬تغرميــه ألــف ريــال تــودع يف بيــت مــال‬\n      ‫املســلمني بحســاب إدارة مكافحــة املخــدرات ‪ ،‬رابعـ ًا ‪ :‬إلزامــه بإعــادة‬\n      ‫املبلــغ احلكومــي وقــدره (‪ )200‬مائتــن ريــال ملكافحــة املخــدرات ‪،‬‬\n      ‫خامس ـ ًا ‪ :‬إلغــاء شــريحة اجلــوال رقــم (‪ )...‬املضبوطــة مــن املدعــى عليــه‬\n      ‫وعــدم صرفهــا لنفــس املشــترك ‪ ،‬سادس ـ ًا ‪ :‬مصــادرة اجلــوال املســتخدم‬\n      ‫يف عمليــة الترويــج ‪ ،‬ســابع ًا ‪ :‬أخــذ التعهــد القــوي عليــه بعــدم العــودة ملثــل‬\n      ‫مــا نســب إليــه ‪ ،‬ثامن ـ ًا ‪ :‬منعــه مــن الســفر خلــارج اململكــة بعــد انتهــاء‬\n      ‫محكوميتــه مــدة ثــاث ســنوات هــذا مــا ظهــر لــي وبــه حكمــت واهلل‬\n      ‫أعلــم وأحكــم وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة وقــرر‬\n      ‫املدعــي العــام االعتــراض دون تقــدمي الئحــة اعتراضيــة فأجبتــه لطلبــه‬\n      ‫وأمــرت برفــع كامــل املعاملــة حملكمــة االســتئناف إلكمــال الزمهــا‬\n      ‫حســب املتبــع وبــاهلل التوفيــق ومت قفــل اجللســة الســاعة (‪ )11.00‬وصلــى‬\n      ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪ .‬حــرر يف‬\n                                                                        ‫‪1434/04/29‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n      ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة حائــل‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بحائــل‬\n      ‫املكلــف برقــم ‪34906011‬وتاريــخ ‪1434/5/4‬هــ؛ واملقيــدة لدينــا برقــم‬\n      ‫‪34906011‬وتاريــخ ‪1434/5/6‬هــ؛ املرفــق بهــا القــرار الشــرعي رقــم‬\n      ‫(‪ )34201368‬وتاريــخ ‪1434/4/29‬هــ؛ الصــادر مــن فضيلــة الشــيخ ‪/‬‬\n      ‫‪ ....‬القاضــي باحملكمــة اجلزائيــة بحائــل؛ اخلــاص بدعــوى املدعــي العــام‬\n      ‫ضــد ‪ .... /‬ســعودي اجلنســية ســجل مدنــي رقــم (‪)....‬؛ التهامــه بقضيــة‬\n      ‫ترويــج مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه علــى املدعــى عليــه‬\n\n\n‫‪381‬‬\n\f‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر علــى النحــو املفصــل فيــه؛‬\n‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة ‪:‬جــرت املصادقــة علــى‬\n‫مــا حكــم بــه فضيلتــه علــى املدعــى عليــه مــن تعزيــر مــع تنبيــه فضيلتــه‬\n‫أن ختــم صــورة الضبــط بصــورة طبــق األصــل بــدون توقيــع ال يكفــي‬\n‫ملالحظــة ذلــك مســتقبالً‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل وســلم علــى نبينــا‬\n                                         ‫محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n\n\n\n\n                                                                                    ‫‪382‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":374,"source_page_end":382,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"01d45a0049b325da86ddb65474a07d93012d9cfb34ac89f32e831019bc8db59d","normalized_text_hash":"4f5f3353c00097675b130dd05c8c91e9e64518282a57f7eac141ff62fadd1e10","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p374-34201368"},{"id":"b082a8e2-4739-5e4d-b58f-b4e75695edbf","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج حبوب محظورة -حيازة احلبوب احملظورة بقصد التعاطي -تعزير بالسجن واجللد -تعزير باملنع من السفر -تعزير بالغرامة -تعزير باملصادرة -إسقاط شريحة جوال.","document_number":"34194415","case_number":"34176361","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/22","year":"1434","subject":"مخدرات -ترويج حبوب محظورة -حيازة احلبوب احملظورة بقصد التعاطي -تعزير بالسجن واجللد -تعزير باملنع من السفر -تعزير بالغرامة -تعزير باملصادرة -إسقاط شريحة جوال.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34194415 :‬تاريخه ‪1434/04/22 :‬هـ‬\n                          ‫رقم الدعوى ‪34176361 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34317446‬تاريخه‪1434/09/13:‬هـ‬\n\n\n        ‫مخــدرات ‪ -‬ترويــج حبــوب محظــورة ‪ -‬حيــازة احلبــوب احملظــورة بقصــد‬\n        ‫التعاطــي ‪ -‬تعزيــر بالســجن واجللــد ‪ -‬تعزيــر باملنــع مــن الســفر ‪ -‬تعزيــر‬\n                          ‫بالغرامــة ‪ -‬تعزيــر باملصــادرة ‪ -‬إســقاط شــريحة جــوال‪.‬‬\n\n\n\n\n            ‫‪-1‬املادة ‪ 56‬واملادة ‪ 62‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n                 ‫‪ -2‬تعميم سمو وزير الداخلية رقم ‪ 65980‬يف ‪1428/10/23‬هـ‬\n\n\n\n\n        ‫ادعــى املدعــي العــام ضــد املدعــى عليــه ترويــج احلبــوب احملظــورة بقصــد‬\n        ‫االجتــار والترويــج وحيازتهــا بقصــد الترويــج والتعاطــي وتعاطيــه لهــا‪،‬‬\n        ‫وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة‬\n        ‫الســجن واجللــد والغرامــة املاليــة واملنــع مــن الســفر ومصــادرة الهاتــف‬\n        ‫اجلــوال وإلغــاء شــريحته املســتخدمة يف اجلرميــة وإلــزام املدعــى عليــه بــرد‬\n        ‫املبلــغ املرقــم ‪ ،‬حيــث إنــه مت القبــض علــى املدعــى عليــه بعــد إخباريــة‬\n        ‫مفادهــا أن املدعــى عليــه يقــوم بترويــج احلبــوب احملظــورة ومت التنســيق‬\n        ‫مــع أحــد املصــادر الســرية لإليقــاع بــه متلبسـ ًا ومت ذلــك وتقابــل املصــدر‬\n        ‫مــع املدعــى عليــه يف املوقــع احملــدد ومت القبــض علــى املدعــى عليــه بعــد‬\n        ‫عمليــة التســليم واالســتالم وأقــر املدعــى عليــه بالدعــوى ‪ ،‬بنــاء علــى‬\n\n‫‪383‬‬\n\f‫مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد‬\n‫والغرامــة واملنــع مــن الســفر ومصــادرة الهاتــف اجلــوال وإســقاط شــريحته‬\n‫املســتخدمان يف اجلرميــة و رد املبلــغ احلكومــي وصــدق احلكــم مــن‬\n                                                  ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 34176361‬وتاريــخ ‪ 1434/04/16‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34940643‬وتاريــخ ‪ 1434/04/16‬ه ـ ففــي يــوم‬\n‫األحــد املوافــق‪ 1434/04/21‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 15‬‬\n‫وفيهــا حضــر املدعــي العــام و أدعــي علــى ‪ ....../‬البالــغ مــن العمــر(‪)24‬‬\n‫عام ـ ًا ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬حيــث أنــه‬\n‫بتاريــخ ‪1434/3/10‬ه ـ قبــض علــى املذكــور مــن قبــل إحــدى فــرق‬\n‫ادارة العميــات التابعــة إلدارة مكافحــة املخــدرات مبنطقــة الريــاض‬\n‫ـاء علــى املعلومــات الــواردة لهــم مــن أحــد مصادرهــم الســرية عــن قيــام‬\n                                                                             ‫بنـ ً‬\n‫املذكــور بترويــج احلبــوب احملظــورة ويســتخدم هاتفــه اجلــوال رقــم( ‪)...‬‬\n‫واســتعد املصــدر لالطاحــه بــه باجلــرم املشــهود عليــه مت االيعــاز للمصــدر‬\n‫لالتصــال علــى الهاتــف جــوال املــروج وطلــب منــه حبوبـ ًا محظــوره بقيمــة‬\n‫(‪ )200‬مائتــي ريــال فوافــق املــروج املذكــور ومت تكليــف احــد افــراد‬\n‫الفرقــه ملرافقــة املصــدر ليكــون شــاهد علــى عمليــة الترويــج ومت تزويــد‬\n‫املصــدر باملبلــغ املرقــم وقــدرة (‪ )200‬مائتــي ريــال وحــدد املــروج مــكان‬\n‫االســتالم والتســليم وباإلنتقــال إلــى املوقــع مت مقابلــة املــروج وركــب يف‬\n\n                                                                                     ‫‪384‬‬\n\f      ‫ســيارة املصــدر والفــرد املكلــف وحضــرت ســيارة لــم تتمكــن الفرقــه‬\n      ‫مــن تســجيل رقــم لوحتهــا بســبب الظــام واســتلم املــروج املذكــور املبلــغ‬\n      ‫املرقــم قبــل نزولــه واجتــه إلــى الســياره واحتــك بصاحبهــا ثــم عــاد وســلم‬\n      ‫للمصــدر ماعــدده (‪ )7‬ســبع حبــات حتمــل عالمــة الكبتاجــون احملظــور‬\n      ‫وبعــد متــام العمليــه مت ضبطــه وبتفتيشــه عثــر علــى ماعــدده (‪ )1‬حبــه‬\n      ‫حتمــل عالمــة الكبتاجــون احملظــور يف جيــب بنطالــه األميــن ولــم يعثــر‬\n      ‫معــه علــى املبلــغ املرقــم ‪.‬وقد أثبت التقرير الكيميائي الشــرعي الصادر‬\n      ‫مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بالريــاض‬\n      ‫املرفــق رقــم (‪/2982‬س) لعــام ‪1434‬ه ـ احتــواء احلبــوب املروجــه واحلبــه‬\n      ‫املضبوطــه لالمفيتامــن وهــو مــن املــواد املنبهــه واملدرجــة باجلــدول رقــم‬\n      ‫(‪ )2‬فئــة (ب) مــن نظــام مكافحــه املخــدرات واملؤثرات العقلية ‪.‬وبســماع‬\n      ‫أقوالــه األوليــة واســتجوابه اعتــرف بالترويــج واعتــرف بضبــط احلبــه‬\n      ‫احملظــوره معــه بقصــد التعاطــي واعتــرف بتعاطــي احلبــوب احملظــوره‬\n      ‫وأنــه حصــل علــى احلبــوب املخــدره مــن املدعــو ‪ .... /‬حيــث أنــه اتصل عليه‬\n      ‫لطلــب احلبــوب احملظــوره فأعطــاه رقــم املدعــو ‪ ... /‬وهــو الــذي احضــر‬\n      ‫احلبــوب احملظــوره وقــد أســفرت إجــراءات التحقيــق عــن توجيــه االتهــام‬\n      ‫لــ‪ .... /‬ببيــع مــا عــدده (‪ )7‬ســبع حبــات مــن حبــوب االمفيتامــن املنبــه‬\n      ‫احملظــورة بقصــد األجتــار والترويــج وحيــازة ماعــدده (‪ )1‬حبــه واحــده‬\n      ‫مــن حبــوب االمفيتامــن املنبــه احملظــورة بقصــد الترويــج و التعاطــي‬\n      ‫وتعاطيــه احلبــوب احملظــوره املجــرم مبوجــب املــادة (الثالثــة) مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n            ‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ‪.‬وذلــك لألدلــة والقرائــن التاليــة ‪-:‬‬\n                                                                ‫‪ -1‬ماتضمنه اعترافه‪.‬‬\n\n\n‫‪385‬‬\n\f                                                     ‫‪ -2‬ما تضمنه محضر القبض) ‪.‬‬\n‫‪ -3‬مــا تضمنــه التقريــر الكيميائــي وببحــث ســوابقه العشــرية لــم عثــر‬\n‫علــى ســابقه مســجله بحقــه حتــى تاريخــه ‪.‬وحيــث إن مــا أقــدم عليــه‬\n‫املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا ‪ ،‬لــذا اطلــب إثبــات‬\n                         ‫إدانتــه مبــا أســند إليهمــا واحلكــم عليهمــا باآلتــي‪-:‬‬\n‫‪-1‬بعقوبــة الســجن واجللــد والغرامــه املاليــة بحقــة وفقـ ًا للفقــرة (األولــى)‬\n‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثرات العقلية املشــار‬\n‫إليــه وتشــديد العقوبــه عليــه وفقـ ًا للفقــرة (ج) البنــد ثانيـ ًا مــن نفــس املــادة‬\n         ‫وإعمــال الفقــره ( االولــى) مــن املــاده ( ‪ )62‬مــن نفــس النظــام بحقــه‪.‬‬\n‫‪ -2‬منعــه مــن الســفر إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة‬\n‫ســجنه وفقـ ًا للفقــرة (االولــى) مــن املــادة (‪ )56‬مــن النظــام املشــار إليــه ‪.‬‬\n‫‪-3‬مصــادرة الهاتــف النقــال مــن نــوع ‪ .....‬املســتخدم يف اجلرميــه اســتناد ًا‬\n‫للفقــرة (األولــى) مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات‬\n                                                                  ‫واملؤثــرات العقليــة ‪.‬‬\n‫‪-4‬إلغــاء الشــريحة املســتخدمة يف اجلرميــة ذات الرقــم (‪ )....‬وعدم صرفها‬\n‫لنفــس املشــترك يف حــال صــدور احلكــم باإللغــاء وإبــاغ الشــركة‬\n                                       ‫م ـص ـ ــدرة الشــري ـح ــة بـذل ــك استن ــاد ًا إلى‬\n         ‫تعميم سمو وزير الداخلية رقم (‪ )9798‬وتاريخ ‪ 9‬ــ‪1428/2/10‬هـ‪.‬‬\n‫‪-5‬إلــزام املذكــور بــرد املبلــغ املرقــم وقــدره ( ‪ )200‬مائتــي ريــال اســتناد ًا‬\n‫لبرقيــة ســمو ولــي العهــد وزيــر الداخليــة رقــم (‪ )65980‬وتاريــخ ‪-22‬‬\n                                                                     ‫‪1428/10/23‬ه ـ ‪.‬‬\n‫وبعــرض ذلــك علــى املدعــى عليــه اجــاب مــا ذكــره املدعــي العــام صحيح‬\n‫مــن ناحيــة ترويــج ســبع حبــات محظورة بالبيع وحيــازة حبة واحدة لقصد‬\n\n\n                                                                                               ‫‪386‬‬\n\f      ‫االســتعمال وقــرر انــه تائــب ونــادم علــى فعلــه كمــا قــرر انــه يســتعمل‬\n      ‫احلبــوب احملظــورة فبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــه وحيــث‬\n      ‫اعتــرف املدعــى عليــه ببيــع ســبع حبــات محظــورة وحيــازة حبــة واحــدة‬\n      ‫لقصــد االســتعمال وحيــث جــرى االطــاع علــى التقريــر الكيمــاوي رقــم‬\n      ‫‪/2982‬س لعــام ‪1434‬ه ـ املتضمــن ايجابيــة العينــة للحبــوب احملظــورة‬\n      ‫وحيــث جــرى التأمــل لــذا قــررت مــا يلــي اوال ثبــت لــدي ترويــج املدعــى‬\n      ‫عليــه لســبع حبــات محظــورة عــن طريــق البيــع وحكمــت عليــه للمــادة‬\n      ‫‪ 38‬بســجنه ســنة ونصــف اعتبــارا مــن توقيفــه وجلــده مائتــي جلــده مفرقة‬\n      ‫علــى اربــع فتــرات بينهــم عشــرة ايــام وبغرامــة ماليــه قدرهــا عشــرة االف‬\n      ‫ريــال تؤخــذ منــه وتــودع بيــت املــال ثانيــا حكمــت مبنعــه مــن الســفر‬\n      ‫للمــادة ‪ 56‬بعــد انتهــاء محكوميتــه ثالثــا ثبــت لــدي حيازتــه حلبــة واحــدة‬\n      ‫لقصــد االســتعمال وتكــون عقوبتــه داخلــة يف اوال اســتنادا للمــادة ‪62‬‬\n      ‫مــن النظــام رابعــا حكمــت عليــه بــرد مبلــغ مائتــي ريــال اســتنادا لبرقيــة‬\n      ‫ســمو ولــي العهــد ووزيــر الداخيــه رقــم ‪ 65980‬يف ‪1428/10/23-22‬ه ـ‬\n      ‫خامســا حكمــت مبصــادرة الهاتــف اعــاه نــوع نوكيــا اســتنادا للمــادة‬\n      ‫‪ 56‬مــن النظــام سادســا حكمــت بالغــاء الشــريحه املســتخدمه رقــم ‪.....‬‬\n      ‫وعــدم صرفهــا للمشــترك اســتنادا لتعميــم وزيــر الداخليــه رقــم ‪9798‬‬\n      ‫يف ‪1428/2/-10-9‬ه ـ وبعرضــه عليــه قنــع بــه وقنــع بــه املدعــي العــام‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                   ‫وســلم ‪ .‬حــرر يف ‪ 1434/04/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافــق ‪1434/4/22‬ه ـ حضــر‬\n      ‫املدعــي العــام وقــرر عــدم قناعتــه باحلكــم وطلــب التمييــز بــدون الئحــه‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n\n\n‫‪387‬‬\n\f                                          ‫وســلم ‪ .‬حــرر يف ‪ 1434/04/22‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء املوافــق ‪1434/8/9‬ه ـ وردت‬\n‫املعاملــة مــن محكمــة االســتئناف وبطيهــا القــرار رقــم ‪ 34249949‬يف‬\n‫‪1434/6/24‬ه ـ ونــص احلاجــه منــه ان فضيلتــه ناظــر القضيــه اثبــت‬\n‫ترويــج املدعــى عليــه لســبع حبــات عــن طريــق البيــع وحكــم بســجنه‬\n‫ســنة ونصــف مبوجــب املــادة ‪ 38‬مــن نظــام مكافحــة املخــدرات واملــادة‬\n‫املذكــورة اقــل عقوبــة خمــس ســنوات ولــم يبــن ناظــر القضيــة ســبب‬\n‫النــزول عــن احلــد االدنــى وحكــم فضيلتــه ناظــر القضيــة مبنــع املدعــى‬\n‫عليــه مــن الســفر ولــم يبــن مقــدراه واجيــب اصحــاب الفضيلــة ان النــزول‬\n‫بســبب قــل الكميــة وصغرهــا وامــا املنــع مــن الســفر فلمــدة ســنتني وبــه‬\n‫حكمــت وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/09‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫األولــى مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن رئيــس‬\n‫احملكمــة اجلزائيــة بالريــاض املكلــف برقــم ‪ 341842596‬وتاريــخ‬\n‫‪1434/8/13‬ه ـ واملرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ‪ /‬د‪ ........‬برقــم ‪ 34194415‬وتاريــخ ‪1434/4/22‬ه ـ‬\n‫واخلــاص بدعــوى املدعــي العــام ضــد ‪ ، ............ /‬وموضوعهــا مخــدرات‬\n‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وبعــد التدقيــق يف‬\n‫إجابــة فضيلــة ناظــر القضيــة وفقــه اهلل علــى قــرار محكمــة االســتئناف‬\n‫الســابق تقــرر املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر لعــدم موجــب‬\n‫املالحظــة‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلى آله وصحبه‬\n                                                                         ‫وســلم‪.‬‬\n\n\n                                                                                   ‫‪388‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":383,"source_page_end":388,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a5cdd333a2acbe32d8a675c093dd3a1b5c8f04803fbe1e014edc7273d700da04","normalized_text_hash":"4bf181efa41798bbaa472211b97e45cc84aa03c14a1e75a62319f17a58632fe6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p383-34194415"},{"id":"f6ba3670-4a99-5d9a-bb7e-e2b973918121","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -حيازة احلبوب احملظورة بقصد التعاطي -اعتراف حتقيق ا -ثبوت إدانه -رد دعوى -تعزير بالسجن واجللد والغرامة -تعزير باملصادرة -إلغاء شريحة جوال املواد 60 - 53 - 56 - 38من نظام مكافحة املخدرات واملؤثرات العقلية","document_number":"34204202","case_number":"34177257","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/4","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -حيازة احلبوب احملظورة بقصد التعاطي -اعتراف حتقيق ا -ثبوت إدانه -رد دعوى -تعزير بالسجن واجللد والغرامة -تعزير باملصادرة -إلغاء شريحة جوال املواد 60 - 53 - 56 - 38من نظام مكافحة املخدرات واملؤثرات العقلية","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34204202:‬تاريخه ‪1434/5/4 :‬هـ‬\n                       ‫رقم الدعوى ‪34177257 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34263965‬تاريخه‪1434/09/15:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬حيــازة احلبــوب احملظــورة‬\n      ‫بقصــد التعاطــي ‪ -‬اعتــراف حتقيقـ ًا ‪ -‬ثبــوت إدانــه ‪ -‬رد دعــوى ‪ -‬تعزيــر‬\n      ‫بالســجن واجللــد والغرامــة ‪ -‬تعزيــر باملصــادرة ‪ -‬إلغــاء شــريحة جــوال‬\n\n\n\n\n      ‫املواد ‪ 60 - 53 - 56 - 38‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج احلبــوب احملظــورة‬\n      ‫وتعاطيــه لهــا وطلــب املدعــي العــام إثبــات إدانتــه مبــا أســند إليــه‬\n      ‫واحلكــم عليــه بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة‬\n      ‫الســيارة واجلــوال املســتخدمان يف اجلرميــة وإلغــاء الشــريحة املســتخدمة‬\n      ‫يف اجلرميــة حيــث إنــه قــد وردت معلومــات مفادهــا أن هنــاك شــخص ًا‬\n      ‫يقــوم بترويــج احلبــوب احملظــورة فتــم التنســيق مــع املصــدر لالتفــاق‬\n      ‫معــه علــى شــراء احلبــوب احملظــورة ومت حتديــد املوعــد وحضــر املتهــم‬\n      ‫يف املــكان احملــدد ومتــت مشــاهدة االســتالم والتســليم وأقــر املدعــى‬\n      ‫عليــه بالدعــوى‪ ،‬ملــا كان مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى‬\n      ‫عليــه بالســجن واجللــد و املنــع مــن الســفر والغرامــة ومصــادرة اجلــوال‪،‬‬\n      ‫وإلغــاء شــريحته وعــدم ثبــوت طلــب املدعــي العــام مبصــادرة الســيارة‬\n\n‫‪389‬‬\n\f   ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n                                          ‫املســتخدمة يف اجلرميــة ُ‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .................‬القاضــي يف احملكمــة‬\n‫اجلزائيــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمة اجلزائية بالرياض برقم ‪ 34177257‬وتاريخ ‪1434/04/17‬هـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 34946693‬وتاريــخ ‪ 1434/04/17‬ه ـ ففــي‬\n‫يوم األربعاء املوافق ‪1434/04/24‬هـ افتتحت اجللســة الســاعة ‪08 : 45‬‬\n‫وفيها حضر املدعي العام ‪....‬وقرر قائال أدعي على ‪ ....................‬البالغ‬\n‫مــن العمــر(‪ )..‬عامـ ًا ســعودي اجلنســية مبوجــب بطاقة الهويــة الوطنية رقم‬\n‫(‪ )................‬أعــزب ‪ ،‬متعلــم ‪ ،‬عاطــل ‪ -‬يقيــم يف مدينــة الريــاض أوقــف‬\n‫بتاريــخ ‪1434/3/1‬ه ـ وأحيــل إلى شــعبة ســجن امللــز مبوجب أمر اإلحالة‬\n‫ومتديــد التوقيــف رقــم (ه ـ را‪ )......../5/‬وتاريــخ ‪1434/3/7‬ه ـ اســتناد ًا‬\n‫للقــرار الــوزاري رقــم (‪ )1900‬وتاريخ‪1428/7/9‬ه ـ املبنــي علــى املــادة‬\n‫(‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة ‪ .‬حيــث أنــه بتاريــخ ‪1434/3/1‬ه ـ‬\n‫قبــض علــى املذكــور مــن قبــل إحــدى فــرق املســاندة القابضــة للمديريــة‬\n‫ـاء علــى املعلومــات الــواردة لهــم مــن أحــد‬‫العامــه ملكافحــة املخــدرات بنـ ً‬\n‫مصادرهــم الســرية عــن وجــود شــخص يقــوم بترويــج احلبــوب احملظــورة‬\n‫ومت متكــن املصــدر مــن االتصــال علــى املــروج علــى هاتفــه جــوال رقــم‬\n‫( ‪ )...................‬وطلــب منــه حبوبـ ًا محظــوره بقيمــة (‪ )650‬ســتمائة مائــه‬\n‫وخمســن ريال فوافق املروج ومت االتفاق على موعد االســتالم والتســليم‬\n‫وعليــه مت تزويــد املصــدر باملبلــغ املرقــم (‪ )650‬ســت مائــه وخمســون ريــال‬\n‫وعليــه مت االنتقــال مــع املصــدر ويرافقــه احــد افــراد الفرقــه الـ ــى امل ــوقع‬\n\n                                                                                         ‫‪390‬‬\n\f      ‫امل ـتـفـق عليه وبـعـد خـمــس دقـائـق ح ـضـرت سـيـارة مـن نـوع ‪ .....‬تـحـمـل‬\n      ‫اللــوح ــة(؟؟؟‪ )...-‬وقــام مبقابلــة املصــدر والفــرد املرافــق واحتــك بهمــا‬\n      ‫وســلمهما شــئ وبعدهــا تفرقــا ومبتابعــة الســيارة ‪ ....‬وعنــد توقفهــا عنــد‬\n      ‫أحــد احملــات التجاريــة مت األقفــال عليه وحــاول الهرب فتم أطالق عيار‬\n      ‫نــاري علــى اإلطــار اخللفــي األميــن ومت القبــض عليــه وأتضــح انــه املذكــور‬\n      ‫وبتفتيشــه شــخصي ًا عثــر علــى املبلــغ املرقــم يف جيبــه وبتفتيــش الســياره‬\n      ‫عثــر علــى ماعــدده (‪ )4‬أربــع حبــات حتمــل عالمــة الكبتاجــون احملظــور‬\n      ‫كمــا عثــر علــى هاتــف جــوال مــن نــوع ‪ .....‬وهــو اجلــوال املســتخدم يف‬\n      ‫اجلرميــه ويحمــل الرقــم املصنعــي (‪ )......................‬وعنــد مقابلــة املصــدر‬\n      ‫والفــرد املرافــق ســلمهما مــا عــدده (‪ )20‬عشــرون حبــه حتمــل عالمــة‬\n                                      ‫الكبتاجــون احملظــور وهــي الكميــة املشــتراه ‪.‬‬\n      ‫وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة‬\n      ‫الســموم والكيميــاء الطبيــة الشــرعية بالريــاض املرفــق رقــم (‪2700‬‬\n      ‫‪/‬س) لعــام ‪1434‬ه ـ احتــواء احلبــوب املضبوطــه وعينــة احلبــوب املروجــه‬\n      ‫لالمفيتامــن وهــو مــن املــواد املنبهــه واملدرجــة باجلــدول رقــم (‪ )2‬فئــة (ب)‬\n                               ‫مــن نظــام مكافحــه املخــدرات واملؤثــرات العقليــة ‪.‬‬\n      ‫وبســماع أقوالــه األوليــه اعتــرف بحيــازة احلبــوب احملظــورة يف ســيارته‬\n      ‫وعددهــا (‪ )4‬أربــع حبــات بقصــد التعاطــي وبأســتجوابه أعتــرف أن‬\n      ‫الهاتــف اجلــوال الــذي يحمــل رقــم الشــريحة (‪ )...................‬عائــد لــه‬\n      ‫واعتــرف بتعاطــي احلبــوب احملظــوره وأن املبلــغ املضبــوط معــه وقــدره‬\n      ‫(‪ )2100‬ألفــان ريــال مصــدره مــن حافــز ومصروفــه الشــخصي (جــرى‬\n      ‫تســليمه املبلــغ املالــي اســتناد ًا الــى املادتني(‪ )88-86‬مــن نظام اإلجراءات‬\n      ‫ا للمصــادره مبوجــب اخلطــاب رقــم (‪)34968‬‬            ‫اجلزائيــة كونــه ليــس محـ ً‬\n\n\n‫‪391‬‬\n\f                                                              ‫وتاريــخ ‪1434/4/7‬هـ‬\n‫وقد أسفرت إجراءات التحقيق عن توجيه االتهام لـ‪ .................. /‬ببيع‬\n‫مــا عــدده (‪ )20‬عشــرون حبــه مــن حبــوب االمفيتامــن املنبــه احملظــورة‬\n‫بقصــد اإلجتــار و الترويــج وحيازتــه ماعــدده (‪ )4‬أربــع حبــات مــن نفــس‬\n‫النــوع بقصــد الترويــج والتعاطــي وتعاطيــه احلبــوب احملظــوره املجــرم‬\n‫مبوجــب املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫وتســتره علــى مصــدر مــا مت ضبطــه معــه ومــا مت ترويجــه املعاقــب علــى‬\n                                                                       ‫ذلــك شــرعا ‪.‬‬\n                                                 ‫وذلك لألدلة والقرائن التالية ‪-:‬‬\n‫‪ -1‬اعترافه حتقيق ًا أن اجلوال الذي يحمل رقم الشريحة (‪).....................‬‬\n                                                                            ‫عائــد له ‪.‬‬\n             ‫‪ -2‬ما تضمنه محضر القبض املنوه عنه املرفق لفه رقم ( ) ‪.‬‬\n‫‪ -3‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــه‬\n                                                                      ‫رقــم (‪. )........‬‬\n                                                   ‫‪-4‬ضبط املبلغ املرقم بحوزته ‪.‬‬\n‫وببحــث ســوابقه العشــرية عثــر لــه علــى ســابقة ســرقة جــواالت مســجله‬\n                                                            ‫يف حقــه حتــى تاريخــه ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫ونظامـ ًا ‪ ،‬لــذا اطلــب إثبــات إدانتــه مبــا أســند إليهمــا واحلكــم عليهمــا‬\n                                                                             ‫باآلتــي‪-:‬‬\n‫‪-1‬بعقوبــة الســجن واجللــد والغرامــه املاليــة بحقــة وفقـ ًا للفقــرة (األولــى)‬\n‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثرات العقلية املشــار‬\n\n\n                                                                                           ‫‪392‬‬\n\f      ‫إليــه وتشــديد العقوبــه عليــه وفقـ ًا للفقــرة (ج) البنــد ثانيـ ًا مــن نفــس املــادة‬\n      ‫واعمــال الفقــره (األولــى ) مــن املــادة (‪ )62‬مــن نفــس النظــام بحقــه لقــاء‬\n                                                                                ‫مــا أســند إليــه‪.‬‬\n      ‫‪ -2‬منعــه مــن الســفر إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة‬\n      ‫ســجنه وفقـ ًا للفقــرة (الثانيــة) مــن املــادة (‪ )56‬مــن النظــام املشــار إليــه ‪.‬‬\n      ‫‪-3‬مصــادرة الســياره مــن نــوع ( ‪ ) .....‬حتمــل اللوحــه رقــم (‪).......‬‬\n      ‫املســتخدمه يف اجلرميــه اســتناد ًا للفقــره ( األولــى ) مــن املــادة (‪ )53‬مــن‬\n                                                                              ‫نفــس النظــام ‪.‬‬\n      ‫‪-4‬مصــادرة الهاتــف النقــال مــن نــوع ‪ ......‬املســتخدم يف اجلرميــه حامــل‬\n      ‫الرقــم املصنعــي (‪ ).......................‬اســتناد ًا للفقــرة (األولــى) مــن املــادة‬\n                         ‫(‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n      ‫‪-5‬إلغــاء الشــريحة املســتخدمة يف اجلرميــة ذات الرقــم (‪)..................‬‬\n      ‫وعــدم صرفهــا لنفــس املشــترك يف حــال صــدور احلكــم باإللغــاء وإبــاغ‬\n      ‫الشــركة مصــدرة الشــريحة بذلــك اســتناد ًا إلــى تعميــم ســمو وزيــر‬\n                                  ‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪ 9‬ــ‪1428/2/10‬هــ‪.‬‬\n      ‫‪-6‬بعقوبــة تعزيريــة بحقــه لقــاء تســتره علــى مصــدر مــا ضبــط ومــامت‬\n      ‫ترويجــه ‪ .‬وبــاهلل التوفيــق وبســؤال املدعــى عليــه أجــاب بقولــه مــا ذكــره‬\n      ‫املدعــي العــام صحيــح جملــة وتفصيــا وقــد قمــت ببيــع عشــرين حبــة‬\n      ‫وهــذه احلبــوب هــي لــي الســتخدامها واتصــل علي متعاون وطلب شــراؤها‬\n      ‫وقمــت ببيــع عشــرين حبــة حلاجتــي للمــال وبقــي معــي اربــع حبــات وهــي‬\n      ‫للتعاطــي وقــد تعاطيــت احلبــوب احملظــورة قبــل القبــض علــي بخمســة‬\n      ‫عشــر يومــا وعلــي ســابقة ســرقة جــواالت فقــط وقــد اشــتريت احلبــوب‬\n      ‫احملظــورة مــن شــخص اثيوبــي يف حــي ‪ ............‬أمــا الســيارة فهــي ليســت‬\n\n\n‫‪393‬‬\n\f‫لــي وإمنــا لعمــي ولــدي البينــة هــذه اجابتــي لــذا رفعــت اجللســة حلضــور بينــة‬\n‫املدعــى عليــه ألن الســيارة ليســت ملــكا لــه وعليــه جــرى التوقيــع وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                    ‫حــرر يف ‪ 1434/04/24‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض ففــي يــوم اإلثنــن املوافــق‪ 1434/04/29‬ه ـ افتتحــت اجللســة‬\n‫الســاعة العاشــرة صباحــا وفيهــا حضــر ســعودي بالســجل املدنــي رقــم‬\n‫‪..................‬وكيــا عــن بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n‫بجنــوب الريــاض برقــم ‪ 34522524‬يف ‪ 1434/4/27‬واملخــول فيهــا‬\n‫باملرافقــة واملدافعــة وســماع الدعــاوى والــرد عليهــا واإلقــرار واإلنــكار‬\n‫وقــرر بقولــه بــأن الســيارة التــي قبضــت مــع املدعــى عليــه أنهــا ملوكلــي‬\n‫وليســت لــه وقــد أخذهــا يف ذلــك اليــوم الــذي قبــض عليــه فيــه عاريــة‬\n‫ليذهــب بهــا إلــى مــكان ثــم يعيدهــا وال زالــت مســجلة باســم موكلــي‬\n‫وأحضــر معــه أصــل اإلســتمارة وبياناتهــا كالتالــي اســم املالــك بالهويــة‬\n‫رقــم ‪ ..................‬رقــم الهيــكل ‪ ..............‬حتمــل اللوحــة رقــم (‪)........‬‬\n‫طــراز املركبــة ‪ .......‬اللــون ذهبــي ســنة الصنــع ‪2001‬م وقــد جــرى‬\n‫االطــاع عليهــا وإرفــاق صــورة منهــا باملعاملــة وعليــه جــرى التوقيــع وباهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫حــرر يف ‪ 1434/04/29‬ه ـ ويف يــوم األربعــاء املوافــق ‪ 1434/05/01‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11 : 45‬وفيهــا حضــر املدعــي العــام واملدعــى‬\n‫عليــه وبعــرض بينــة املدعــى عليــه علــى أن الســيارة ليســت ملــكا لــه علــى‬\n‫املدعــي العــام أجــاب بقولــه ليــس لــدي ســوى مــا يف املعاملــة وبتصفــح‬\n‫املعاملــة لــم أجــد فيهــا مــا يثبــت أن الســيارة ملــكا للمدعــى عليــه ولــم‬\n\n\n                                                                                          ‫‪394‬‬\n\f      ‫يقــر املدعــى عليــه أن الســيارة ملــكا لــه فبنــاء علــى ما تقدم مــن الدعوى‬\n      ‫واالجابــة وحيــث صــادق املدعــى عليــه علــى قيامــه ببيــع ما عدده عشــرين‬\n      ‫حبــة مــن حبــوب الكبتاجــون وتعاطيــه لنوعهــا وحيازتــه ألربــع حبــات من‬\n      ‫نفــس النوعيــة للتعاطــي وحيــث جــرى االطــاع علــى محضــر التحقيــق‬\n      ‫وعلــى التقريــر الكيميائــي واذا هــو كمــا ذكــره املدعــي العــام وحيــث‬\n      ‫ان املدعــى عليــه أنكــر ان الســيارة املســتخدمة يف اجلرميــة انهــا لــه‬\n      ‫واحضــر مــا يثبــت ذلــك وأنهــا ملــك لعمــه واملرفــق صــورة وثيقــة امللكيــة‬\n      ‫باملعاملــة وحيــث أن املدعــى عليــه ليــس عليــه ســابقة مماثلــة جلرميتــه وإمنــا‬\n      ‫ســابقته يف ســرقة جــواالت لــذا ثبــت لــدي قيــام املدعــى عليــه ببيــع مــا‬\n      ‫عــدده عشــرون حبــة مــن حبــوب الكبتاجــون بقصــد االجتــار والترويــج‬\n      ‫وحيازتــه لعــدد أربــع حبــات مــن حبــوب الكبتاجــون بقصــد التعاطــي‬\n      ‫وتعاطيــه لنوعهــا وتســتره علــى مصــدر مــا ضبــط وحكمــت عليــه باالتــي‬\n      ‫أوال ســجنه ثــاث ســنوات تبــدأ مــن تاريــخ دخولــه الســجن يف هــذه‬\n      ‫القضيــة وبغرامــة ماليــة قدرهــا ثالثــة االف ريــال وجلــده ثالثمائــة جلــدة‬\n      ‫مفرقــة علــى دفعــات كل دفعــة خمســون جلــدة بــن الدفعــة واالخــرى‬\n      ‫عشــرة ايــام داخــا يف هــذا اجللــد تســتره علــى مصــدر مــا ضبــط وذلــك‬\n      ‫بنــاء علــى املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات وقــد نزلــت عــن‬\n      ‫العقوبــة املقــررة بهــذه املــادة لقلــة الكميــة ولعــدم وجــود ســوابق عليــه‬\n      ‫مماثلــة وذلــك بنــاء علــى املــادة (‪ )60‬مــن النظــام نفســه ثانيــا منعــه مــن‬\n      ‫الســفر ملــدة ثــاث ســنوات تبــدأ بعــد تنفيــذه عقوبــة الســجن بنــاء علــى‬\n      ‫املــادة رقــم (‪ )56‬مــن النظــام نفســه ثالثــا مصــادرة هاتفــه اجلــوال مــن نــوع‬\n      ‫‪ ......‬يف اجلرميــة رقمــه املصنعــي (‪ )............‬وإلغــاء الشــريحة املســتخدمة‬\n      ‫يف اجلرميــة ذات الرقــم وذلــك بنــاء علــى املــادة رقــم (‪ )53‬مــن النظــام‬\n\n\n‫‪395‬‬\n\f‫نفســه رابعــا جلــده ثمانيــة وســبعون جلــدة دفعــة واحــدة لتعاطيــه احلبــوب‬\n‫احملظــورة ويكــون بينهــا وبــن اجللــد التعزيــري يف أوال خمســة عشــر‬\n‫يومــا خامســا لــم يثبــت لــدي مــا يطالــب بــه املدعــي العــام مــن مصــادرة‬\n‫الســيارة املســتخدمة يف اجلرميــة وحكمــت بــرد دعــواه وبعــرض احلكــم‬\n‫علــى املدعــى عليــه قــرر القناعــة وطلــب املدعــي العــام التمييــز وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                 ‫حــرر يف ‪ 1434/05/01‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض ففــي يــوم األحــد املوافــق‪ 1434/08/07‬ه ـ افتتحــت اجللســة‬\n‫الســاعة التاســعة والنصــف صباحــا بنــاء علــى قــرار أصحــاب الفضيلــة‬\n‫قضــاة الدائــرة الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة اإلســتئناف‬\n          ‫بالريــاض رقــم ‪ 34263965‬يف ‪1434/7/10‬ه ـ والــذي جــاء فيــه‬\n‫( لوحــظ لألكثريــة مــا يلــي ‪ -1‬املدعــي العــام طلــب متييــز احلكــم ولــم‬\n‫جنــد يف املعاملــة الئحــة اعتراضيــة أو أنــه يطلــب رفــع احلكــم بــدون‬\n‫الئحــة ‪ -2‬صــورة الوكالــة وصــورة ملكيــة الســيارة لــم يشــرح عليهــا‬\n‫مبطابقتهــا ألصلهــا فعلــى فضيلتــه مالحظــة مــا ذكــر واكمــال مــا يلــزم‬\n‫واهلل املوفــق) فعليــه حضــر املدعــي العــام وجــرى ســؤاله عــن املالحظــة‬\n‫األولــى فقــرر بأنــه ليــس لديــه الئحــة إعتراضيــة مكتفيــا مبــا جــاء يف‬\n‫أوراق املعاملــة وبالنســبة للمالحظــة الثانيــة فقــد جــرى الشــرح علــى‬\n‫صــورة الوكالــة وصــورة ملكيــة الســيارة مبطابقتهــا ألصلهــا لــذا جــرى‬\n‫تدوينــه وعليــه جــرى التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n             ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/08/07‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n\n\n                                                                                    ‫‪396‬‬\n\f      ‫الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n      ‫خطــاب فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪341854258‬‬\n      ‫وتاريــخ ‪1434/8/25‬ه ـ املرفــق بهــا القــرار الصادرمــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ‪ /‬املســجل برقــم ‪ 34204202‬وتاريــخ ‪1434/5/4‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ضــد ‪ /‬يف قضيــة مخــدرات علــى النحــو‬\n      ‫املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‬\n      ‫وحيــث ســبق دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباإلطــاع‬\n      ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه‬\n      ‫بنــاء علــى القــرار رقــم ‪ 34263965‬وتاريــخ ‪1434/7/10‬ه ـ لــم يظهــر‬\n      ‫لألكثريــة مــا يوجــب نقــض احلكــم بعــد اإلجــراء األخيرمــع تنبيــه‬\n      ‫فضيلتــه إلــى توقيــع املوظــف املختــص علــى ختــم طبــق األصــل بصــورة‬\n      ‫الضبــط فيالحــظ ذلــك مســتقبآل واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                                      ‫محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪397‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":389,"source_page_end":397,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c39651cb653a5ade40d8ae125af74b11903df7a5cc536ff37b774ba1bb69a763","normalized_text_hash":"655c45033f2d37b6c7ad8d4d51e171cefa530e54d7ff3692f20f1119bb3f8e29","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p389-34204202"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
